// بوليفِل لـ window.storage خارج بيئة معاينة Claude.ai:
// الكود في التطبيق ده كان مكتوب بافتراض إن window.storage (تخزين مفتاح/قيمة غير
// متزامن) متاح دايمًا — وده صحيح فقط جوه معاينة Claude.ai نفسها. لما التطبيق بيتفتح
// كموقع حقيقي (على Vercel أو محليًا)، window.storage مش موجود أصلًا، فكل عمليات
// الحفظ كانت بتفشل بصمت (catch فاضي) — وده السبب الحقيقي وراء عدم حفظ "إنجازاتي
// اليومية" و"آخر موضع قراءة" و"المحفوظات" بين مرات فتح التطبيق. الحل: لو
// window.storage مش موجود، نعرّفه إحنا بنفس الشكل بالظبط لكن باستخدام localStorage
// (تخزين حقيقي ودائم على جهاز المستخدمة، خاص بالمتصفح ده وبس). كل أكواد الحفظ في
// باقي الملف فضلت زي ما هي بالظبط — التغيير ده بس بيوفر لها أرضية شغالة فعليًا.
if (typeof window !== "undefined" && !window.storage) {
  const LS_PREFIX = "anisk-storage:";
  window.storage = {
    async get(key, _shared = false) {
      let raw = null;
      try { raw = localStorage.getItem(LS_PREFIX + key); } catch { raw = null; }
      if (raw == null) throw new Error("key-not-found");
      return { key, value: raw, shared: !!_shared };
    },
    async set(key, value, _shared = false) {
      try { localStorage.setItem(LS_PREFIX + key, value); } catch { return null; }
      return { key, value, shared: !!_shared };
    },
    async delete(key, _shared = false) {
      try { localStorage.removeItem(LS_PREFIX + key); } catch { return null; }
      return { key, deleted: true, shared: !!_shared };
    },
    async list(prefix = "", _shared = false) {
      const keys = [];
      try {
        for (let i = 0; i < localStorage.length; i++) {
          const k = localStorage.key(i);
          if (k && k.startsWith(LS_PREFIX) && k.slice(LS_PREFIX.length).startsWith(prefix)) {
            keys.push(k.slice(LS_PREFIX.length));
          }
        }
      } catch { /* تجاهل */ }
      return { keys, prefix, shared: !!_shared };
    },
  };
}

