// ميدالية زخرفية إسلامية أصيلة: نجمة ثمانية هندسية داخل دائرتين متحدتي المركز —
// نفس المبدأ الهندسي المستخدم في زخرفة أطراف عناوين السور بالمصاحف المطبوعة.
function IslamicMedallion({ color = "#B08D57", size = 26, style }) {
  const c = 50, r1 = 46, r2 = 36, r3 = 20;
  const starPoints = (n, rOuter, rInner, rot = 0) => {
    const pts = [];
    for (let i = 0; i < n * 2; i++) {
      const r = i % 2 === 0 ? rOuter : rInner;
      const angle = (Math.PI / n) * i - Math.PI / 2 + rot;
      pts.push(`${c + r * Math.cos(angle)},${c + r * Math.sin(angle)}`);
    }
    return pts.join(" ");
  };
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={style}>
      <circle cx={c} cy={c} r={r1} fill="none" stroke={color} strokeWidth="2.2" />
      <circle cx={c} cy={c} r={r2} fill="none" stroke={color} strokeWidth="1.2" opacity="0.8" />
      <polygon points={starPoints(8, r3, r3 * 0.42)} fill={color} opacity="0.92" />
      <circle cx={c} cy={c} r={r3 * 0.42} fill="none" stroke={color} strokeWidth="1.4" opacity="0.9" />
      {Array.from({ length: 16 }, (_, i) => {
        const angle = (Math.PI / 8) * i;
        const x = c + r1 * Math.cos(angle), y = c + r1 * Math.sin(angle);
        return <circle key={i} cx={x} cy={y} r={1.6} fill={color} opacity="0.85" />;
      })}
    </svg>
  );
}

// شريط عنوان السورة بزخرفة إسلامية هندسية أصيلة: برواز مزدوج + ميداليتا نجمة
// ثمانية على الطرفين، بدل أي رموز نصية أو علامات ترقيم.
function SurahBanner({ name, type, nightMode }) {
  const gold = nightMode ? "#C9A66B" : "#B08D57";
  const bg = nightMode ? "#1b1710" : "var(--accentSoft)";
  return (
    <div style={{
      position: "relative", margin: "20px 0 18px", padding: "14px 20px",
      background: bg, borderRadius: 10, overflow: "hidden",
    }}>
      {/* برواز مزدوج */}
      <div style={{ position: "absolute", inset: 3, border: `1.5px solid ${gold}`, borderRadius: 7, pointerEvents: "none" }} />
      <div style={{ position: "absolute", inset: 0, border: `2.5px solid ${gold}`, borderRadius: 10, pointerEvents: "none" }} />
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 14, position: "relative" }}>
        <IslamicMedallion color={gold} size={30} />
        <div style={{ textAlign: "center" }}>
          <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 19, color: nightMode ? "#E9D9AE" : "var(--accent)" }}>
            سورة {name}
          </div>
          <div style={{ fontSize: 10, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif", marginTop: 2 }}>{type}</div>
        </div>
        <IslamicMedallion color={gold} size={30} />
      </div>
    </div>
  );
}

