function archiveSurahUrl(base, surahNumber) {
  if (!base || !surahNumber) return null;
  return `${base}${String(surahNumber).padStart(3, "0")}.mp3`;
}
// تشغيل السورة من مصدر mp3quran.net الموثّق (تحقّقتُ منه فعليًا عبر الـ API الرسمي
// المباشر) — بديل موثوق أكتر لبعض القراء بدل الاعتماد على مصدر واحد بس
function mp3QuranSurahUrl(server, surahNumber) {
  if (!server || !surahNumber) return null;
  return `${server}${String(surahNumber).padStart(3, "0")}.mp3`;
}

