// عدد صفحات المصحف القياسي
const MUSHAF_TOTAL_PAGES = 604;
// رقم الصفحة (١-٦٠٤) لآية عالمية معيّنة
function mushafPageForGlobal(g) {
  let lo = 1, hi = MUSHAF_TOTAL_PAGES, ans = 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (MUSHAF_PAGE_STARTS[mid - 1] <= g) { ans = mid; lo = mid + 1; } else hi = mid - 1;
  }
  return ans;
}
// أول/آخر آية عالمية على صفحة معيّنة
function mushafPageRange(p) {
  const start = MUSHAF_PAGE_STARTS[p - 1];
  const end = (MUSHAF_PAGE_STARTS[p] || 6237) - 1;
  return [start, end];
}
// السورة التي تقع فيها آية عالمية معيّنة (باستخدام g0 من FULL_QURAN)
function surahForGlobal(g) {
  for (let i = 0; i < FULL_QURAN.length; i++) {
    const s = FULL_QURAN[i];
    if (g >= s.g0 && g < s.g0 + s.verses.length) return s;
  }
  return FULL_QURAN[FULL_QURAN.length - 1];
}

