// كل قيمة هي رقم الآية العالمي اللي يبدأ بيه الجزء/الربع
const JUZ_STARTS = [1,149,260,386,517,641,751,900,1042,1201,1328,1479,1649,1803,2030,2215,2484,2674,2876,3215,3386,3564,3733,4090,4265,4511,4706,5105,5242,5673];
const RUB_STARTS = [1,33,51,67,82,99,113,131,149,165,184,196,210,226,240,250,260,270,279,290,308,326,345,368,386,406,426,446,464,479,494,505,517,529,551,567,581,593,607,628,641,656,670,681,696,710,720,736,751,766,778,802,825,848,863,884,900,916,930,940,955,985,1001,1019,1042,1071,1096,1110,1125,1143,1161,1182,1201,1221,1236,1254,1269,1281,1295,1310,1328,1346,1357,1375,1390,1417,1435,1454,1479,1497,1514,1534,1557,1581,1603,1626,1649,1673,1697,1712,1726,1742,1760,1778,1803,1852,1902,1931,1952,1976,1991,2012,2030,2052,2079,2099,2128,2157,2172,2191,2215,2239,2272,2309,2349,2403,2431,2459,2484,2512,2534,2566,2596,2614,2633,2655,2674,2709,2748,2792,2812,2826,2844,2856,2876,2908,2933,2984,3043,3113,3160,3186,3215,3241,3264,3281,3303,3328,3341,3366,3386,3410,3440,3463,3491,3514,3534,3551,3564,3584,3593,3616,3630,3652,3675,3701,3733,3765,3810,3871,3933,3991,4022,4066,4090,4111,4134,4154,4174,4199,4227,4243,4265,4285,4299,4323,4349,4382,4431,4485,4511,4531,4555,4578,4601,4613,4626,4657,4706,4759,4810,4855,4902,4980,5054,5091,5105,5118,5137,5157,5178,5192,5218,5230,5242,5272,5324,5394,5448,5495,5552,5610,5673,5759,5830,5885,5949,6024,6091,6155];

function juzForGlobal(g) {
  let ans = 1;
  for (let i = 0; i < JUZ_STARTS.length; i++) { if (JUZ_STARTS[i] <= g) ans = i + 1; else break; }
  return ans;
}
function rubIndexForGlobal(g) {
  // فهرس الربع (١ - ٢٤٠) عبر القرآن كله
  let ans = 1;
  for (let i = 0; i < RUB_STARTS.length; i++) { if (RUB_STARTS[i] <= g) ans = i + 1; else break; }
  return ans;
}
function hizbForGlobal(g) {
  return Math.ceil(rubIndexForGlobal(g) / 4); // كل حزب = ٤ أرباع، فالحزب رقم ١-٦٠
}
function rubWithinHizbForGlobal(g) {
  const idx = rubIndexForGlobal(g);
  const r = idx % 4;
  return r === 0 ? 4 : r; // الربع رقم ١-٤ داخل الحزب
}
function juzStartsAt(g) { return JUZ_STARTS.includes(g); }
function rubStartsAt(g) { return RUB_STARTS.includes(g) && !JUZ_STARTS.includes(g); } // الجزء له أولوية في العرض

