// جلب بيانات أحكام التجويد (مرة واحدة لكل الجلسة، من الملف الرسمي الوحيد المتاح
// لكل القرآن ~5.5 ميجابايت) ثم فرزها محليًا حسب السورة — تجنّبًا لتحميلها من جديد
// في كل صفحة. الملف موجود فعليًا وتم التحقق منه (وليس رابطًا مُخمَّنًا).
let tajweedFullDataPromise = null;
async function fetchTajweedFull() {
  if (!tajweedFullDataPromise) {
    tajweedFullDataPromise = fetch(
      "https://raw.githubusercontent.com/cpfair/quran-tajweed/master/output/tajweed.hafs.uthmani-pause-sajdah.json",
      { cache: "force-cache" }
    ).then((res) => { if (!res.ok) throw new Error("tajweed fetch failed"); return res.json(); });
  }
  return tajweedFullDataPromise;
}
const tajweedSurahCache = {};
async function fetchTajweedForSurah(surahId) {
  if (tajweedSurahCache[surahId]) return tajweedSurahCache[surahId];
  const full = await fetchTajweedFull();
  const forSurah = full.filter((e) => e.surah === surahId);
  tajweedSurahCache[surahId] = forSurah;
  return forSurah;
}

// تركيب النص الملوّن بأمان: كل حكم يُطبّق فقط لو حدوده جوه طول النص الفعلي
function buildTajweedSpans(text, annotations) {
  const chars = Array.from(text);
  const colorAt = new Array(chars.length).fill(null);
  (annotations || []).forEach((a) => {
    const color = TAJWEED_COLORS[a.rule];
    if (!color) return;
    const start = Math.max(0, a.start), end = Math.min(chars.length, a.end);
    for (let i = start; i < end; i++) if (!colorAt[i]) colorAt[i] = color;
  });
  const spans = [];
  let cur = null;
  chars.forEach((ch, i) => {
    const c = colorAt[i];
    if (cur && cur.color === c) cur.text += ch;
    else { cur = { color: c, text: ch }; spans.push(cur); }
  });
  return spans;
}

