function greetingHour() {
  const h = new Date().getHours();
  if (h < 12) return "صباح الخير";
  if (h < 17) return "طاب يومك";
  return "مساء الخير";
}

function LiveClock({ tzOffset }) {
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 30000); // نص دقيقة كفاية لساعة حية بدون استهلاك زيادة
    return () => clearInterval(id);
  }, []);
  const utcMs = now.getTime() + now.getTimezoneOffset() * 60000;
  const localMs = tzOffset != null ? utcMs + tzOffset * 3600000 : now.getTime();
  const d = new Date(localMs);
  const hh = String(d.getHours() % 12 || 12).padStart(2, "0");
  const mm = String(d.getMinutes()).padStart(2, "0");
  const ampm = d.getHours() >= 12 ? "م" : "ص";
  return <span style={{ fontFamily: "'Cairo', sans-serif", color: "var(--accent)", fontSize: 11.5, fontWeight: 700 }}>{hh}:{mm} {ampm}</span>;
}

function Home({ state, day, updateDay, prefs, updatePrefs, goTo, streak, welcome, theme, reminders }) {
  const pct = dayCompletion(day);
  const reflection = REFLECTIONS[new Date().getDate() % REFLECTIONS.length];
  const verse = todaysVerse();
  const [sharingCard, setSharingCard] = useState(false);
  // بعد تسجيل صلاة مفروضة (مش إلغاءها)، ولو كانت من الصلوات اللي ليها سنة راتبة،
  // نعرض سؤال سريع وغير مُلحّ بدل ما نفرض نافذة تأكيد أو نطلب ضغطة مزدوجة غامضة.
  const [sunnahPrompt, setSunnahPrompt] = useState(null); // { prayerIndex, links } | null
  const promptCloseTimer = useRef(null);
  const scheduleClosePrompt = () => {
    clearTimeout(promptCloseTimer.current);
    // بنسيب فرصة قصيرة (أقل من ثانية) لو حابة تدوسي على أكتر من خيار (زي سنة قبل
    // وبعد الظهر مع بعض)، لكن من غير ما يفضل المربع معلّق على الشاشة بلا داعي.
    promptCloseTimer.current = setTimeout(() => setSunnahPrompt(null), 900);
  };
  useEffect(() => () => clearTimeout(promptCloseTimer.current), []);
  const togglePrayer = (i) => {
    const wasDone = day.prayers[i];
    updateDay({ prayers: day.prayers.map((v, idx) => (idx === i ? !v : v)) });
    if (!wasDone) {
      setSunnahPrompt({ prayerIndex: i, links: PRAYER_SUNNAH_LINKS[i] || [] });
    } else if (sunnahPrompt?.prayerIndex === i) {
      setSunnahPrompt(null);
    }
  };
  const markSunnah = (sunnahIndex) => {
    updateDay({ sunnah: day.sunnah.map((v, idx) => (idx === sunnahIndex ? true : v)) });
    scheduleClosePrompt();
  };
  const toggleJamaah = (prayerIndex) => {
    updateDay({ jamaah: (day.jamaah || Array(5).fill(false)).map((v, idx) => (idx === prayerIndex ? !v : v)) });
    scheduleClosePrompt();
  };
  const shareVerseCard = async () => {
    setSharingCard(true);
    try {
      const blob = await generateVerseCard(verse);
      const file = new File([blob], "anisk-ayah.png", { type: "image/png" });
      const shareText = `قال تعالى:\n\n${verse.text}\n\n﴿سورة ${verse.surah}: ${verse.ayahNumber}﴾`;
      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: "آية اليوم — أنيسك", text: shareText });
      } else {
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url; a.download = "anisk-ayah.png";
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }
    } catch { /* تجاهل فشل المشاركة */ }
    setSharingCard(false);
  };
  const P = HOME_PALETTE[theme === "dark" ? "dark" : "light"];

  const quranDone = day.quranPages >= Number(prefs.dailyGoal || 2);
  const adhkarDone = Object.values(day.adhkar).filter(Boolean).length;
  const qiyamDone = day.qiyam.length > 0;

  const timeline = [
    { time: "الورد اليومي", icon: <BookOpen size={14} />, done: quranDone, color: P.quran.c2, onToggle: () => goTo("quran") },
    { time: "أذكار المساء", icon: <Star size={14} />, done: day.adhkar.evening, color: P.adhkar.c2, onToggle: () => updateDay({ adhkar: { ...day.adhkar, evening: !day.adhkar.evening } }) },
    { time: "قيام الليل", icon: <Moon size={14} />, done: qiyamDone, color: P.qiyam.c1, onToggle: () => goTo("ibadah") },
  ];

  return (
    <div>
      {welcome && welcome.status === "blocked" && (
        <div onClick={welcome.retry} style={{
          display: "flex", alignItems: "center", gap: 8, background: "var(--accentSoft)", borderRadius: 14,
          padding: "10px 14px", marginBottom: 14, cursor: "pointer",
        }}>
          <Volume2 size={16} color="var(--accent)" />
          <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5, color: "var(--text)" }}>اضغط لتشغيل ترحيب اليوم 🤍</span>
        </div>
      )}

      <div style={{ marginBottom: 4, position: "relative" }}>
        <p style={{ fontFamily: "'Cairo', sans-serif", color: "var(--textDim)", fontSize: 13, margin: 0, letterSpacing: "0.2px" }}>
          {greetingHour()}{prefs.name ? `، ${prefs.name}` : ""} 🤍
        </p>
        <h1 style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 25, color: "var(--text)", margin: "5px 0 0", lineHeight: 1.3 }}>
          كيف كان يومك مع الله؟
        </h1>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 10 }}>
          <div style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "var(--accentSoft)", borderRadius: 20, padding: "4px 12px" }}>
            <span style={{ fontFamily: "'Cairo', sans-serif", color: "var(--accent)", fontSize: 11.5, fontWeight: 700 }}>
              {hijriDateLabel(new Date())}
            </span>
          </div>
          <div style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "var(--accentSoft)", borderRadius: 20, padding: "4px 12px" }}>
            <span style={{ fontFamily: "'Cairo', sans-serif", color: "var(--accent)", fontSize: 11.5, fontWeight: 700 }}>
              {new Date().toLocaleDateString("ar-EG", { day: "numeric", month: "long" })}
            </span>
          </div>
          <div style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "var(--accentSoft)", borderRadius: 20, padding: "4px 12px" }}>
            <Clock size={12} color="var(--accent)" />
            <LiveClock tzOffset={reminders?.locTzOffset} />
          </div>
        </div>
      </div>

      {reminders?.travelNotice && (
        <div className="anisk-stagger-1" style={{ display: "flex", alignItems: "center", gap: 10, background: "var(--accentSoft)", borderRadius: 14, padding: "12px 14px", marginTop: 12 }}>
          <MapPin size={18} color="var(--accent)" style={{ flexShrink: 0 }} />
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5, fontWeight: 700, color: "var(--text)" }}>📍 أنت الآن في {reminders.travelNotice.label}</div>
            <div style={{ fontSize: 11, color: "var(--textDim)" }}>تم تحديث مواقيت الصلاة والقبلة لموقعك الحالي</div>
          </div>
          <X size={15} color="var(--textDim)" style={{ cursor: "pointer", flexShrink: 0 }} onClick={reminders.dismissTravelNotice} />
        </div>
      )}

      {prefs.fajrAlarmEnabled && reminders?.times?.fajr && reminders?.times?.sunrise
        && new Date() >= reminders.times.fajr && new Date() < reminders.times.sunrise
        && prefs.fajrConfirmedDate !== todayKey() && (
        <button
          onClick={() => updatePrefs?.({ fajrConfirmedDate: todayKey() })}
          className="anisk-pop"
          style={{
            width: "100%", marginTop: 14, padding: "14px 16px", borderRadius: 16, border: "none", cursor: "pointer",
            background: "linear-gradient(135deg, var(--primary), color-mix(in srgb, var(--primary) 78%, black))",
            color: "var(--onPrimary)", display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
            fontFamily: "'Cairo', sans-serif", fontSize: 14, fontWeight: 700,
          }}
        >
          ⏰ قمت لصلاة الفجر ✓
        </button>
      )}

      {/* بطاقة صلواتي — تفعيل مباشر لأي صلاة بضغطة واحدة، مع رمز يوحي بوقت كل صلاة ومواقيتها الفعلية */}
      {reminders?.nextPrayer && (
        <div className="anisk-stagger-1" style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginTop: 16,
          fontFamily: "'Cairo', sans-serif", fontSize: 12.5, color: "var(--textDim)",
        }}>
          <Clock size={13} color="var(--accent)" />
          <span>
            <b style={{ color: "var(--accent)" }}>{reminders.nextPrayer[0]}</b> بعد{" "}
            <b style={{ color: "var(--text)" }}>{formatCountdown(reminders.nextPrayer[1])}</b>
          </span>
        </div>
      )}
      <div className="anisk-stagger-1" style={{ display: "flex", gap: 8, marginTop: 10, overflowX: "auto", paddingBottom: 2 }}>
        {PRAYERS.map((name, i) => {
          const done = day.prayers[i];
          const TimeIcon = PRAYER_TIME_ICONS[i];
          const timeKey = PRAYER_TIME_KEYS[i];
          const prayerTime = reminders?.times?.[timeKey];
          return (
            <button
              key={name}
              onClick={() => togglePrayer(i)}
              className={done ? "anisk-pop" : ""}
              style={{
                flexShrink: 0, minWidth: 74, padding: "12px 10px", borderRadius: 16, cursor: "pointer", position: "relative",
                display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
                background: done ? `linear-gradient(135deg, ${P.prayer.c1}, ${P.prayer.c2})` : "var(--surface)",
                boxShadow: done ? `0 4px 14px ${P.prayer.c2}44` : "0 1px 3px rgba(0,0,0,0.05)",
                border: done ? "none" : "1px solid var(--border)",
                transition: "all .25s ease",
              }}
            >
              {done && (
                <span style={{
                  position: "absolute", top: 4, insetInlineEnd: 4, width: 15, height: 15, borderRadius: "50%",
                  background: "rgba(255,255,255,0.9)", display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  <Check size={9} color={P.prayer.c2} />
                </span>
              )}
              <div style={{
                width: 30, height: 30, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center",
                background: done ? "rgba(255,255,255,0.22)" : "var(--surfaceAlt)",
              }}>
                <TimeIcon size={16} color={done ? "#fff" : PRAYER_TIME_COLORS[i]} />
              </div>
              <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12, fontWeight: 600, color: done ? "#fff" : "var(--text)" }}>{name}</span>
              {prayerTime && (
                <span style={{ fontSize: 9.5, color: done ? "rgba(255,255,255,0.85)" : "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>
                  {fmtTime(prayerTime)}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {sunnahPrompt && (
        <Card className="anisk-stagger-1" style={{ padding: 14, marginTop: 10, display: "flex", flexDirection: "column", gap: 10 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: "var(--text)" }}>
              🕌 تفاصيل صلاة {PRAYERS[sunnahPrompt.prayerIndex]}
            </span>
            <X size={16} color="var(--textDim)" style={{ cursor: "pointer" }} onClick={() => setSunnahPrompt(null)} />
          </div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            {(() => {
              const checked = !!(day.jamaah || [])[sunnahPrompt.prayerIndex];
              return (
                <button
                  onClick={() => toggleJamaah(sunnahPrompt.prayerIndex)}
                  style={{
                    flex: 1, minWidth: 130, padding: "9px 12px", borderRadius: 12, cursor: "pointer",
                    display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
                    border: `1px solid ${checked ? "transparent" : "var(--border)"}`,
                    background: checked ? "var(--accent)" : "var(--surface)",
                    color: checked ? "#fff" : "var(--text)",
                    fontFamily: "'Cairo', sans-serif", fontSize: 12.5, fontWeight: 600,
                  }}
                >
                  {checked ? <CheckCircle2 size={14} /> : <Circle size={12} />} صلاة جماعة
                </button>
              );
            })()}
          </div>
          {sunnahPrompt.links.length > 0 && (
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              {sunnahPrompt.links.map((l) => {
                const checked = day.sunnah[l.sunnahIndex];
                return (
                  <button
                    key={l.sunnahIndex}
                    onClick={() => markSunnah(l.sunnahIndex)}
                    style={{
                      flex: 1, minWidth: 130, padding: "9px 12px", borderRadius: 12, cursor: "pointer",
                      display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
                      border: `1px solid ${checked ? "transparent" : "var(--border)"}`,
                      background: checked ? "var(--primary)" : "var(--surface)",
                      color: checked ? "var(--onPrimary)" : "var(--text)",
                      fontFamily: "'Cairo', sans-serif", fontSize: 12.5, fontWeight: 600,
                    }}
                  >
                    {checked ? <CheckCircle2 size={14} /> : <Circle size={12} />} {l.label}
                  </button>
                );
              })}
            </div>
          )}
        </Card>
      )}

      {/* HERO — big gradient card with decorative shapes + progress ring */}
      <div className="anisk-stagger-2" style={{
        position: "relative", overflow: "hidden", borderRadius: 32, marginTop: 20, padding: "30px 24px",
        background: `linear-gradient(135deg, ${P.hero.c1}, ${P.hero.c2})`,
        boxShadow: theme === "dark" ? "0 18px 40px rgba(0,0,0,0.35)" : "0 18px 40px rgba(80,70,110,0.16)",
      }}>
        <BlobShape color="rgba(255,255,255,0.18)" size={200} style={{ top: -60, insetInlineEnd: -50 }} />
        <BlobShape color="rgba(255,255,255,0.10)" size={150} style={{ bottom: -50, insetInlineStart: -40 }} opacity={1} />
        <SparkleIcon color={P.gold} size={16} style={{ top: 18, insetInlineStart: 22 }} />
        <SparkleIcon color="rgba(255,255,255,0.7)" size={10} style={{ top: 50, insetInlineStart: 60 }} />
        <CrescentIcon color="rgba(255,255,255,0.5)" size={26} style={{ position: "absolute", top: 20, insetInlineEnd: 26 }} />

        <div style={{ position: "relative", display: "flex", alignItems: "center", gap: 24, flexWrap: "wrap" }}>
          <div style={{ position: "relative", flexShrink: 0, width: 138, height: 138 }}>
            <svg width={138} height={138} style={{ transform: "rotate(-90deg)" }}>
              <defs>
                <linearGradient id="heroRingGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor={P.gold} />
                  <stop offset="100%" stopColor={P.hero.text} />
                </linearGradient>
              </defs>
              <circle cx={69} cy={69} r={60} stroke="rgba(255,255,255,0.35)" strokeWidth={11} fill="none" />
              <circle
                cx={69} cy={69} r={60} stroke="url(#heroRingGrad)" strokeWidth={11} fill="none"
                strokeDasharray={2 * Math.PI * 60} strokeDashoffset={2 * Math.PI * 60 - (pct / 100) * 2 * Math.PI * 60}
                strokeLinecap="round" style={{ transition: "stroke-dashoffset 0.8s cubic-bezier(.4,0,.2,1)" }}
              />
            </svg>
            <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
              <span style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 28, color: P.hero.text }}>{pct}%</span>
              <span style={{ fontSize: 11, color: P.hero.text, opacity: 0.75 }}>إنجاز اليوم</span>
            </div>
          </div>
          <div style={{ flex: 1, minWidth: 140 }}>
            <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: P.hero.text, lineHeight: 1.8, fontWeight: 500 }}>
              {pct >= 70 ? "يومٌ مبارك، استمر 🤍" : pct >= 30 ? "خطوة كل يوم تقربك أكثر" : "ابدأ من حيث أنت 🤍"}
            </div>
            {streak > 0 && (
              <div style={{ display: "inline-flex", alignItems: "center", gap: 6, marginTop: 12, background: "rgba(255,255,255,0.35)", padding: "6px 12px", borderRadius: 999 }}>
                <Flame size={14} color={P.gold} />
                <span style={{ fontSize: 12.5, color: P.hero.text, fontFamily: "'Cairo', sans-serif", fontWeight: 600 }}>{streak} أيام من الاستمرار</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* CATEGORY CARDS — distinct shapes/colors per activity */}
      <div style={{ marginTop: 18 }}>
        {/* Prayer — wide horizontal card */}
        <div style={{
          position: "relative", overflow: "hidden", borderRadius: 24, padding: "18px 20px",
          background: `linear-gradient(120deg, ${P.prayer.c1}, ${P.prayer.c2})`, marginBottom: 12,
        }}>
          <BlobShape color="rgba(255,255,255,0.22)" size={110} style={{ top: -40, insetInlineEnd: -20 }} opacity={1} />
          <div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
            <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, fontWeight: 700, color: P.prayer.text }}>🕌 صلواتي</span>
            <span style={{ fontSize: 12.5, color: P.prayer.text, opacity: 0.8 }}>{day.prayers.filter(Boolean).length} / 5</span>
          </div>
          <div style={{ position: "relative", display: "flex", gap: 8, justifyContent: "space-between" }}>
            {PRAYERS.map((p, i) => (
              <div key={p} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 5, flex: 1 }}>
                <div style={{
                  width: 30, height: 30, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center",
                  background: day.prayers[i] ? P.prayer.text : "rgba(255,255,255,0.4)", color: day.prayers[i] ? P.prayer.c1 : P.prayer.text,
                  transition: "all .3s",
                }}>
                  {day.prayers[i] ? <Check size={14} /> : <Circle size={10} />}
                </div>
                <span style={{ fontSize: 10, color: P.prayer.text, fontFamily: "'Cairo', sans-serif" }}>{p}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Quran + Adhkar — two-column row, different shapes */}
        <div style={{ display: "grid", gridTemplateColumns: "1.15fr 0.85fr", gap: 12, marginBottom: 12 }}>
          <div onClick={() => goTo("quran")} style={{
            position: "relative", overflow: "hidden", borderRadius: 26, padding: "18px 16px", cursor: "pointer",
            background: `linear-gradient(160deg, ${P.quran.c1}, ${P.quran.c2})`, minHeight: 168,
          }}>
            <LeafIcon color="rgba(255,255,255,0.3)" size={46} style={{ position: "absolute", top: -6, insetInlineStart: -6 }} />
            <div style={{ position: "relative" }}>
              <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: P.quran.text }}>📖 وردك اليوم</span>
              <div style={{ marginTop: 14, display: "flex", alignItems: "center", gap: 12 }}>
                <div style={{ position: "relative", width: 54, height: 54, flexShrink: 0 }}>
                  <Ring percent={Math.min(100, (day.quranPages / (prefs.dailyGoal || 2)) * 100)} size={54} stroke={6} />
                  <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <BookOpen size={18} color={P.quran.text} />
                  </div>
                </div>
                <div>
                  <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, color: P.quran.text, fontWeight: 700 }}>{day.quranPages} / {prefs.dailyGoal || 2}</div>
                  <div style={{ fontSize: 10.5, color: P.quran.text, opacity: 0.75 }}>صفحات</div>
                </div>
              </div>
              <button style={{
                marginTop: 14, display: "inline-flex", alignItems: "center", gap: 5, background: "rgba(255,255,255,0.5)",
                border: "none", borderRadius: 999, padding: "7px 14px", fontSize: 11.5, fontFamily: "'Cairo', sans-serif",
                fontWeight: 700, color: P.quran.text, cursor: "pointer",
              }}>تابع القراءة <ArrowLeft size={12} /></button>
            </div>
          </div>

          <div onClick={() => goTo("adhkar")} style={{
            position: "relative", overflow: "hidden", borderRadius: 26, padding: "16px 14px", cursor: "pointer",
            background: `linear-gradient(160deg, ${P.adhkar.c1}, ${P.adhkar.c2})`, minHeight: 168,
            display: "flex", flexDirection: "column", justifyContent: "space-between",
          }}>
            <SparkleIcon color="rgba(255,255,255,0.6)" size={12} style={{ top: 14, insetInlineEnd: 16 }} />
            <CrescentIcon color="rgba(255,255,255,0.55)" size={22} style={{ position: "absolute", top: 10, insetInlineStart: 12 }} />
            <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: P.adhkar.text, marginTop: 30 }}>📿 أذكارك</span>
            <div>
              <div style={{ position: "relative", width: 44, height: 44, margin: "6px 0" }}>
                <Ring percent={(adhkarDone / 4) * 100} size={44} stroke={5} />
                <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontFamily: "'Cairo', sans-serif", fontWeight: 700, color: P.adhkar.text }}>
                  {adhkarDone}/4
                </div>
              </div>
              <div style={{ fontSize: 11, color: P.adhkar.text, opacity: 0.85 }}>{day.adhkar.morning ? "✓" : "○"} الصباح · {day.adhkar.evening ? "✓" : "○"} المساء</div>
            </div>
          </div>
        </div>

        {/* Qiyam — dark night-inspired card */}
        <div onClick={() => goTo("ibadah")} style={{
          position: "relative", overflow: "hidden", borderRadius: 24, padding: "20px 22px", cursor: "pointer", marginBottom: 12,
          background: `linear-gradient(160deg, ${P.qiyam.c1}, ${P.qiyam.c2})`,
          boxShadow: `0 10px 30px ${theme === "dark" ? "rgba(0,0,0,0.4)" : "rgba(40,30,70,0.25)"}`,
        }}>
          {[...Array(7)].map((_, i) => (
            <SparkleIcon key={i} color="rgba(255,255,255,0.55)" size={6 + (i % 3) * 3} style={{ top: `${10 + i * 11}%`, insetInlineEnd: `${8 + (i * 13) % 70}%` }} />
          ))}
          <div style={{ position: "relative", display: "flex", alignItems: "center", gap: 14 }}>
            <CrescentIcon color={P.gold} size={34} />
            <div>
              <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, fontWeight: 700, color: P.qiyam.text }}>قيام الليل</div>
              <div style={{ fontSize: 12, color: P.qiyam.text, opacity: 0.75, marginTop: 2 }}>{qiyamDone ? "✓ تم — جزاكِ الله خيرًا" : "ولو ركعتين 🤍"}</div>
            </div>
          </div>
        </div>

        {/* Charity — peach pill row */}
        <div style={{
          position: "relative", overflow: "hidden", borderRadius: 24, padding: "16px 18px",
          background: `linear-gradient(120deg, ${P.charity.c1}, ${P.charity.c2})`,
        }}>
          <BlobShape color="rgba(255,255,255,0.2)" size={100} style={{ bottom: -40, insetInlineStart: -30 }} opacity={1} />
          <div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
            <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, fontWeight: 700, color: P.charity.text }}>🤲 صدقة في يومي</span>
            {day.charity.length > 0 && <span style={{ fontSize: 11.5, color: P.charity.text, opacity: 0.75 }}>✓ {day.charity.length}</span>}
          </div>
          <div style={{ position: "relative", display: "flex", gap: 6, overflowX: "auto", paddingBottom: 2 }}>
            {CHARITY_OPTIONS.slice(0, 5).map((o) => (
              <span key={o} style={{
                flexShrink: 0, fontSize: 11.5, fontFamily: "'Cairo', sans-serif", fontWeight: 600, padding: "6px 12px", borderRadius: 999,
                background: day.charity.includes(o) ? P.charity.text : "rgba(255,255,255,0.45)",
                color: day.charity.includes(o) ? P.charity.c1 : P.charity.text,
              }}>{o}</span>
            ))}
          </div>
        </div>
      </div>

      <Card onClick={() => goTo("ai")} style={{ padding: "14px 16px", marginTop: 14, cursor: "pointer", display: "flex", alignItems: "center", gap: 12, background: "linear-gradient(135deg, var(--accentSoft), transparent)" }}>
        <span style={{ fontSize: 22 }}>✨</span>
        <div style={{ flex: 1 }}>
          <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, fontWeight: 700, color: "var(--text)" }}>اسأل أنيسك AI</div>
          <div style={{ fontSize: 11.5, color: "var(--textDim)" }}>تفسير، حديث، فقه، سيرة — بمصادرها</div>
        </div>
        <ChevronLeft size={16} color="var(--textDim)" />
      </Card>

      {/* المناسبات الإسلامية القادمة */}
      {(() => {
        const events = nextIslamicEvents(new Date(), 3);
        if (events.length === 0) return null;
        return (
          <div style={{ display: "flex", gap: 8, overflowX: "auto", marginTop: 14, paddingBottom: 2 }}>
            {events.map((ev, i) => (
              <div key={i} style={{
                flexShrink: 0, background: "var(--accentSoft)", borderRadius: 14, padding: "10px 14px",
                display: "flex", alignItems: "center", gap: 8, minWidth: 150,
              }}>
                <span style={{ fontSize: 18 }}>{ev.icon}</span>
                <div>
                  <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 11.5, fontWeight: 700, color: "var(--text)" }}>{ev.name}</div>
                  <div style={{ fontSize: 10.5, color: "var(--textDim)" }}>{ev.daysLeft === 0 ? "اليوم 🤍" : `بعد ${ev.daysLeft} يوم`}</div>
                </div>
              </div>
            ))}
          </div>
        );
      })()}

      {/* JOURNEY TIMELINE — connected curved line with colored nodes */}
      <SectionTitle>رحلتي اليوم</SectionTitle>
      <Card style={{ padding: "20px 22px" }}>
        <div style={{ position: "relative" }}>
          <div style={{ position: "absolute", insetInlineStart: 16, top: 6, bottom: 6, width: 2, background: "var(--border)", borderRadius: 2 }} />
          {timeline.map((t, i) => (
            <div
              key={i}
              onClick={t.onToggle}
              style={{ position: "relative", display: "flex", alignItems: "center", gap: 14, padding: "11px 4px", cursor: t.onToggle ? "pointer" : "default", borderRadius: 10, transition: "background .15s" }}
            >
              <div style={{
                width: 34, height: 34, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, zIndex: 1,
                background: t.done ? t.color : "var(--surfaceAlt)", color: t.done ? "#fff" : "var(--textDim)",
                boxShadow: t.done ? `0 0 0 4px ${t.color}33` : "none", transition: "all .35s",
              }}>{t.icon}</div>
              <div style={{ flex: 1, fontFamily: "'Cairo', sans-serif", fontSize: 14, color: "var(--text)" }}>{t.time}</div>
              {t.done ? <Check size={16} color={t.color} /> : <Circle size={13} color="var(--border)" />}
            </div>
          ))}
        </div>
      </Card>

      <SectionTitle>آية اليوم</SectionTitle>
      <Card style={{ padding: 24, background: `linear-gradient(160deg, var(--surface), ${P.hero.c1}22)` }}>
        <p style={{ fontFamily: "'Amiri', serif", fontSize: 21, lineHeight: 1.9, color: "var(--text)", margin: 0, textAlign: "center" }}>
          {verse.text} ﴿{verse.ayahNumber}﴾
        </p>
        <p style={{ textAlign: "center", color: "var(--textDim)", fontSize: 12.5, marginTop: 10 }}>سورة {verse.surah} — {verse.note}</p>
        <div style={{ display: "flex", gap: 10, justifyContent: "center", marginTop: 14, flexWrap: "wrap" }}>
          <button onClick={() => goTo("quran")} style={btnGhost()}><BookOpen size={14} /> اقرأ</button>
          <button onClick={() => goTo("listen")} style={btnGhost()}><Volume2 size={14} /> استمع</button>
          <button onClick={shareVerseCard} disabled={sharingCard} style={{ ...btnGhost(), opacity: sharingCard ? 0.6 : 1 }}>
            {sharingCard ? "جارٍ التجهيز..." : "🖼️ شارك كصورة"}
          </button>
        </div>
      </Card>

      <SectionTitle>وقفة اليوم</SectionTitle>
      <Card style={{ padding: 20, background: `linear-gradient(150deg, var(--surfaceAlt), ${P.adhkar.c1}33)`, border: "none" }}>
        <p style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", lineHeight: 1.8, margin: 0 }}>{reflection.text}</p>
        <p style={{ fontSize: 12, color: "var(--textDim)", marginTop: 8 }}>{reflection.source}</p>
      </Card>

      <SectionTitle>كيف كان يومك؟</SectionTitle>
      <Card style={{ padding: 18 }}>
        <textarea
          value={day.reflection}
          onChange={(e) => updateDay({ reflection: e.target.value })}
          placeholder="اليوم أشعر أن..."
          rows={3}
          style={{ width: "100%", border: "none", background: "transparent", resize: "none", outline: "none", fontFamily: "'Cairo', sans-serif", fontSize: 14, color: "var(--text)" }}
        />
      </Card>
      <div style={{ height: 30 }} />
    </div>
  );
}

function MiniStat({ icon, label, value }) {
  return (
    <div style={{ background: "var(--surfaceAlt)", borderRadius: 14, padding: "10px 12px" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6, color: "var(--textDim)", fontSize: 12 }}>{icon}{label}</div>
      <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", fontWeight: 600, marginTop: 4 }}>{value}</div>
    </div>
  );
}

function btnGhost() {
  return {
    display: "flex", alignItems: "center", gap: 6, padding: "9px 14px", borderRadius: 12,
    border: "1px solid var(--border)", background: "var(--surface)", color: "var(--primary)",
    fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 600, cursor: "pointer",
    boxShadow: "0 1px 3px rgba(0,0,0,0.04)", transition: "transform .12s ease",
  };
}


/* =========================================================================
   Quran — reader, audio, memorization & recitation
   ========================================================================= */

function QuranSection({ prefs, updatePrefs, day, updateDay, nightMode, setNightMode, quran, audio, goTo }) {
  const [screen, setScreen] = useState("list"); // list | reader | reciters | memorize | search
  const [surahId, setSurahId] = useState(1);
  const [flip, setFlip] = useState(null); // 'next' | 'prev' | null
  const [search, setSearch] = useState("");
  const [ayahSearchQuery, setAyahSearchQuery] = useState("");
  const [browseMode, setBrowseMode] = useState("surahs"); // surahs | juz | pages | bookmarks
  const [readingPosition, setReadingPosition] = useState(null);
  const [markedAyah, setMarkedAyah] = useState(null); // { globalNumber, surahId, surahName, localIndex } | null
  const [ayahTags, setAyahTags] = useState({}); // { [globalNumber]: [tagId,...] }
  const [tagSetup, setTagSetup] = useState(null); // { item } | null — لوحة اختيار العلامات
  const [shareSetup, setShareSetup] = useState(null); // { item } | null — لوحة اختيار مشاركة نص أو صورة
  const [sharingImage, setSharingImage] = useState(false);
  const [pageJumpInput, setPageJumpInput] = useState("");
  useEffect(() => { loadReadingPosition().then(setReadingPosition); }, []);
  useEffect(() => { loadMarkedAyah().then(setMarkedAyah); }, []);
  useEffect(() => { loadAyahTags().then(setAyahTags); }, []);
  const toggleAyahTag = (globalNumber, tagId) => {
    setAyahTags((prev) => {
      const current = prev[globalNumber] || [];
      const next = current.includes(tagId) ? current.filter((t) => t !== tagId) : [...current, tagId];
      const updated = { ...prev };
      if (next.length) updated[globalNumber] = next; else delete updated[globalNumber];
      saveAyahTags(updated);
      return updated;
    });
  };
  const [ayahSearchResults, setAyahSearchResults] = useState(null); // null = not searched yet

  const runAyahSearch = (q) => {
    setAyahSearchQuery(q);
    const term = normalizeArabic(q.trim());
    if (term.length < 2) { setAyahSearchResults(null); return; }
    const results = [];
    for (const s of FULL_QURAN) {
      for (let i = 0; i < s.verses.length; i++) {
        if (normalizeArabic(s.verses[i]).includes(term)) {
          results.push({ surahId: s.id, surahName: s.name, localIndex: i, text: s.verses[i], globalNumber: s.g0 + i });
          if (results.length >= 100) break;
        }
      }
      if (results.length >= 100) break;
    }
    setAyahSearchResults(results);
  };
  const [tafsirGlobal, setTafsirGlobal] = useState(null); // global ayah number currently shown in tafsir card
  const [tafsirText, setTafsirText] = useState(null); // null | 'loading' | 'error' | string
  const [wordMeanings, setWordMeanings] = useState(null); // null | 'loading' | array of {word, meaning}
  const [mushafPage, setMushafPage] = useState(2); // 1..604, real Uthmani mushaf page
  const [realMushafMode, setRealMushafMode] = useState(true); // المصحف الأساسي في التطبيق = مصحف المدينة الحقيقي (خط QCF4)
  const [offlineDownload, setOfflineDownload] = useState({ status: "idle", done: 0, total: QCF_TOTAL_PAGES }); // تجهيز المصحف كامل في الخلفية للقراءة بدون نت
  const [hiddenAyahs, setHiddenAyahs] = useState({});
  const [hideSetup, setHideSetup] = useState(null);
  const toggleHiddenAyah = (item) => {
    const next = { ...hiddenAyahs };
    if (next[item.globalNumber]) delete next[item.globalNumber];
    else next[item.globalNumber] = true;
    setHiddenAyahs(next);
    saveHiddenAyahs(next);
  };
  const [listenSetup, setListenSetup] = useState(null);
  const [listenPanel, setListenPanel] = useState(null);
  const [listenReciterId, setListenReciterId] = useState(prefs.quranReciter);
  const [listenSpeed, setListenSpeed] = useState(1);
  const listenAudioRef = useRef(ANISK_AYAH_LISTEN_AUDIO);
  const touchStartX = useRef(null);
  useEffect(() => { loadHiddenAyahs().then(setHiddenAyahs); }, []);
  useEffect(() => {
    // تجهيز المصحف بالكامل في الخلفية أول مرة يتفتح فيها التطبيق، من غير ما
    // تحتاجي تدوسي زرار "تنزيل" بنفسك — المصحف واحد بس، وده مجرد تجهيزه
    // مسبقًا عشان يشتغل بدون نت أسرع.
    let cancelled = false;
    downloadFullMushafOffline((done, total) => {
      if (!cancelled) setOfflineDownload({ status: "downloading", done, total });
    })
      .then(() => { if (!cancelled) setOfflineDownload({ status: "done", done: QCF_TOTAL_PAGES, total: QCF_TOTAL_PAGES }); })
      .catch(() => { if (!cancelled) setOfflineDownload({ status: "error", done: 0, total: QCF_TOTAL_PAGES }); });
    return () => { cancelled = true; };
  }, []);

  const list = quran.list;
  const surahIndex = list.findIndex((s) => s.id === surahId);
  const surahMeta = list[surahIndex] || list[0];
  const ayat = quran.ayatCache[surahId]; // whole-surah array, kept for memorize mode + tafsir default

  // بناء محتوى الصفحة الحالية من المصحف الحقيقي (قد تمتد عبر أكثر من سورة)
  const [pgStart, pgEnd] = mushafPageRange(mushafPage);
  const pageItems = [];
  for (let g = pgStart; g <= pgEnd; g++) {
    const s = surahForGlobal(g);
    const localIndex = g - s.g0;
    pageItems.push({ globalNumber: g, surahId: s.id, surahName: s.name, surahType: s.type, localIndex, text: s.verses[localIndex] });
  }
  const firstItemSurahId = pageItems[0] ? pageItems[0].surahId : surahId;

  useEffect(() => {
    if (screen === "reader" || screen === "memorize") quran.ensureAyat(surahId);
  }, [screen, surahId]); // eslint-disable-line

  // إبقاء surahId متزامنًا مع أول سورة تظهر في الصفحة الحالية (لأغراض التسميع والاستماع)
  useEffect(() => { if (firstItemSurahId !== surahId) setSurahId(firstItemSurahId); }, [mushafPage]); // eslint-disable-line

  // حفظ آخر موضع قراءة + احتساب الصفحة تلقائيًا ضمن ورد اليوم.
  // كل صفحة تُحتسب مرة واحدة في اليوم حتى لو رجعتي لها أكثر من مرة.
  useEffect(() => {
    if (screen !== "reader" || !pageItems[0]) return;
    const first = pageItems[0];
    saveReadingPosition({
      surahId: first.surahId, surahName: first.surahName, ayahLocalIndex: first.localIndex,
      mushafPage, juz: juzForGlobal(first.globalNumber), ts: Date.now(),
    });
    const seen = Array.isArray(day.quranReadPages) ? day.quranReadPages : [];
    if (!seen.includes(mushafPage)) {
      const nextSeen = [...seen, mushafPage];
      updateDay({ quranPages: nextSeen.length, quranReadPages: nextSeen });
    }
  }, [mushafPage, screen]); // eslint-disable-line

  // إزالة تلقائية للعلامة المحفوظة: لو رجعتِ لصفحة العلامة وبعدين كملتِ للصفحة اللي
  // بعدها (يعني فعلًا استكملتِ القراءة من مكانك)، العلامة بتتشال لوحدها. لو قفزتِ
  // لمكان تاني في المصحف بعيد عن العلامة أصلًا، العلامة بتفضل موجودة زي ما هي.
  const wasOnMarkPageRef = useRef(false);
  useEffect(() => {
    if (!markedAyah) { wasOnMarkPageRef.current = false; return; }
    const markPage = mushafPageForGlobal(markedAyah.globalNumber);
    if (mushafPage === markPage) {
      wasOnMarkPageRef.current = true;
    } else if (wasOnMarkPageRef.current && mushafPage > markPage) {
      setMarkedAyah(null);
      saveMarkedAyah(null);
      wasOnMarkPageRef.current = false;
    }
  }, [mushafPage]); // eslint-disable-line

  // تتابع الصفحة تلقائيًا مع الاستماع: لما الآية اللي بتتشغّل تعدّي لصفحة تانية، الصفحة المعروضة تتقلب معاها لوحدها
  useEffect(() => {
    if (!audio.player.playing || !audio.player.surahId) return;
    const s = FULL_QURAN.find((x) => x.id === audio.player.surahId);
    if (!s) return;
    const g = s.g0 + audio.player.ayahIndex;
    const targetPage = mushafPageForGlobal(g);
    if (targetPage !== mushafPage) setMushafPage(targetPage);
  }, [audio.player.surahId, audio.player.ayahIndex, audio.player.playing]); // eslint-disable-line
  useEffect(() => { setWordPopup(null); }, [mushafPage]);

  const changeMushafPage = (dir) => {
    const next = mushafPage + (dir === "next" ? 1 : -1);
    if (next < 1 || next > MUSHAF_TOTAL_PAGES) return;
    setFlip(dir);
    setTimeout(() => { setMushafPage(next); setFlip(null); setTafsirText(null); setTafsirGlobal(null); setTafsirTarget(null); setTafsirView("tafsir"); }, 260);
  };

  // فتح سورة من القائمة: الانتقال لصفحة المصحف الحقيقية التي تبدأ بها
  const openSurah = (id) => {
    const s = FULL_QURAN.find((x) => x.id === id);
    setSurahId(id);
    setMushafPage(mushafPageForGlobal(s ? s.g0 : 1));
    setScreen("reader");
  };

  const onTouchStart = (e) => { touchStartX.current = e.touches[0].clientX; };
  const onTouchEnd = (e) => {
    if (touchStartX.current == null) return;
    const delta = e.changedTouches[0].clientX - touchStartX.current;
    touchStartX.current = null;
    // رفعنا حد اللمس المطلوب لتقليب الصفحة (كان 40px) عشان مش تتقلب الصفحة بمجرد
    // لمسة بسيطة أو تمرير خفيف أثناء القراءة، ولازم سحب واضح ومقصود.
    if (Math.abs(delta) < 110) return;
    // سحب من الشمال لليمين (delta > 0) = الصفحة التالية، والعكس = السابقة
    if (delta > 0) changeMushafPage("next"); else changeMushafPage("prev");
  };
  // دعم السحب بالماوس كمان (للاستخدام من الكمبيوتر) بنفس منطق اللمس
  const onMouseDown = (e) => { touchStartX.current = e.clientX; };
  const onMouseUp = (e) => {
    if (touchStartX.current == null) return;
    const delta = e.clientX - touchStartX.current;
    touchStartX.current = null;
    if (Math.abs(delta) < 110) return;
    if (delta > 0) changeMushafPage("next"); else changeMushafPage("prev");
  };

  const [tafsirTarget, setTafsirTarget] = useState(null); // { globalNumber, surahId, localIndex }
  const [tafsirView, setTafsirView] = useState("tafsir"); // tafsir | words

  // تكرار سماع آية بمفردها (لتصحيح النطق) أو نطاق آيات (للحفظ) — مشغّل مستقل بسيط
  const [repeatPanel, setRepeatPanel] = useState(null);
  const [repeatSetup, setRepeatSetup] = useState(null);
  const repeatAudioElRef = useRef(null);
  useEffect(() => {
    const el = new Audio();
    repeatAudioElRef.current = el;
    return () => { el.pause(); };
  }, []);
  const [repeatReciterId, setRepeatReciterId] = useState(prefs.quranReciter);

  // تسميع من صفحة المصحف الحقيقية — بدون تحويل المصحف لقائمة منفصلة
  const [recitationSetup, setRecitationSetup] = useState(null); // { surahId, fromAyah, toAyah } أثناء اختيار النطاق
  const [recitationRange, setRecitationRange] = useState(null); // { surahId, fromAyah, toAyah } بعد البدء فعليًا
  const recitationAyahs = useMemo(() => {
    if (!recitationRange) return [];
    const s = FULL_QURAN.find((x) => x.id === recitationRange.surahId);
    if (!s) return [];
    const list = [];
    for (let i = recitationRange.fromAyah - 1; i <= recitationRange.toAyah - 1 && i < s.verses.length; i++) {
      list.push({ surahId: s.id, ayahIndexInSurah: i, globalNumber: s.g0 + i, text: s.verses[i], words: tokenizeWords(s.verses[i]) });
    }
    return list;
  }, [recitationRange]);
  const recitation = useRecitationEngine(recitationAyahs);

  // تتابع صفحة المصحف تلقائيًا مع تقدّم التسميع، بنفس أسلوب المتابعة مع الاستماع
  useEffect(() => {
    if (!recitationRange || recitation.status !== "listening") return;
    const cur = recitationAyahs[recitation.ayahPos];
    if (!cur) return;
    const targetPage = mushafPageForGlobal(cur.globalNumber);
    if (targetPage !== mushafPage) setMushafPage(targetPage);
  }, [recitation.ayahPos, recitation.status]); // eslint-disable-line

  const startRecitation = () => {
    if (!recitationSetup) return;
    setRecitationRange(recitationSetup);
    setRecitationStartTs(Date.now());
    const s = FULL_QURAN.find((x) => x.id === recitationSetup.surahId);
    if (s) { setSurahId(s.id); setMushafPage(mushafPageForGlobal(s.g0 + recitationSetup.fromAyah - 1)); }
    setRecitationSetup(null);
    setTimeout(() => recitation.start(), 100);
  };
  const stopRecitation = () => { recitation.stop(); setRecitationRange(null); };
  const [recitationStartTs, setRecitationStartTs] = useState(null);
  const [recitationHistory, setRecitationHistory] = useState([]);
  const [showMistakeReview, setShowMistakeReview] = useState(false);
  const [recurringMistakes, setRecurringMistakes] = useState([]);

  // حفظ نتيجة المحاولة + دمج الأخطاء في سجل الأخطاء العام، لما التسميع يخلص
  useEffect(() => {
    if (recitation.status !== "completed" || !recitationRange) return;
    (async () => {
      const total = recitation.summary.total || 1;
      const accuracy = Math.round((recitation.summary.correct / total) * 100);
      const durationSec = recitationStartTs ? Math.round((Date.now() - recitationStartTs) / 1000) : 0;
      const attempt = { surahId: recitationRange.surahId, fromAyah: recitationRange.fromAyah, toAyah: recitationRange.toAyah, date: todayKey(), accuracy, durationSec, errors: recitation.summary.wrong, skipped: recitation.summary.skipped, ts: Date.now() };
      try {
        const res = await window.storage.get("unisk:recitation-history", false);
        const prevHistory = res?.value ? JSON.parse(res.value) : [];
        const nextHistory = [...prevHistory, attempt].slice(-100);
        await window.storage.set("unisk:recitation-history", JSON.stringify(nextHistory), false);
        setRecitationHistory(nextHistory.filter((h) => h.surahId === recitationRange.surahId).slice(-5));
      } catch { /* تجاهل */ }
      if (recitation.sessionMistakes.length > 0) {
        const prevMistakes = await loadMistakes();
        await saveMistakes([...prevMistakes, ...recitation.sessionMistakes]);
      }
      // اكتشاف الكلمات اللي بتتكرر غلطانة عبر أكتر من محاولة لنفس السورة
      const allMistakes = await loadMistakes();
      const surahMistakes = allMistakes.filter((m) => m.surahId === recitationRange.surahId);
      const counts = {};
      surahMistakes.forEach((m) => { const k = `${m.ayahIndex}:${m.word}`; counts[k] = (counts[k] || 0) + 1; });
      const recurring = Object.entries(counts).filter(([, c]) => c >= 2).map(([k, c]) => ({ word: k.split(":")[1], count: c }));
      setRecurringMistakes(recurring.slice(0, 5));
    })();
  }, [recitation.status]); // eslint-disable-line
  const [tajweedData, setTajweedData] = useState({}); // surahId -> annotations[], populated on demand
  const [tajweedLoading, setTajweedLoading] = useState(false);
  // التلوين الحرفي لا يمكن أن يُرسم داخل رموز خط QCF المغلقة؛ لذلك يصبح العرض
  // العثماني الملون هو وضع المصحف تلقائيًا حين يُفعّل التجويد، ويعود خط المدينة
  // الأصلي فور إغلاقه.
  useEffect(() => {
    setRealMushafMode(!prefs.tajweedColoringEnabled);
  }, [prefs.tajweedColoringEnabled]);
  useEffect(() => {
    if (!prefs.tajweedColoringEnabled) return;
    let cancelled = false;
    const surahIds = [...new Set(pageItems.map((it) => it.surahId))];
    (async () => {
      for (const sid of surahIds) {
        if (tajweedData[sid] || cancelled) continue;
        setTajweedLoading(true);
        try {
          const data = await fetchTajweedForSurah(sid);
          if (!cancelled) setTajweedData((d) => ({ ...d, [sid]: data }));
        } catch { /* هيتحاول تاني وقت الحاجة */ }
        setTajweedLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [prefs.tajweedColoringEnabled, mushafPage]); // eslint-disable-line
  const reciterForRepeat = RECITERS.find((r) => r.id === repeatReciterId) || RECITERS.find((r) => r.id === prefs.quranReciter);
  const [ayahMenu, setAyahMenu] = useState(null); // { item, mode: 'menu'|'repeat-setup' } | null — قائمة الدوسة المطوّلة
  const toggleMarkedAyah = (item) => {
    if (markedAyah && markedAyah.globalNumber === item.globalNumber) {
      setMarkedAyah(null);
      saveMarkedAyah(null);
    } else {
      const mark = { globalNumber: item.globalNumber, surahId: item.surahId, surahName: item.surahName, localIndex: item.localIndex };
      setMarkedAyah(mark);
      saveMarkedAyah(mark);
    }
  };
  const longPressTimer = useRef(null);
  const longPressFired = useRef(false);
  const startLongPress = (item) => {
    longPressFired.current = false;
    longPressTimer.current = setTimeout(() => {
      longPressFired.current = true;
      setAyahMenu({ item, mode: "menu" });
    }, 480);
  };
  const cancelLongPress = () => { if (longPressTimer.current) clearTimeout(longPressTimer.current); };
  const playRepeatStep = (panel) => {
    const el = repeatAudioElRef.current;
    const activeReciter = RECITERS.find((r) => r.id === panel.reciterId) || reciterForRepeat;
    if (!el || !activeReciter?.edition || activeReciter?.surahOnly) {
      setRepeatPanel((p) => (p ? { ...p, playing: false, error: "هذا القارئ لا يدعم تشغيل آية بعينها — اختر قارئًا آخر من الإعدادات." } : p));
      return;
    }
    el.src = ayahAudioUrl(activeReciter.edition, panel.cursorGlobal);
    el.playbackRate = panel.speed || 1;
    el.play().catch(() => setRepeatPanel((p) => (p ? { ...p, playing: false, error: "تعذّر تشغيل الصوت." } : p)));
  };
  useEffect(() => {
    const el = repeatAudioElRef.current;
    if (!el) return;
    const onEnded = () => {
      setRepeatPanel((p) => {
        if (!p || !p.playing) return p;
        if (p.mode === "single") {
          const loopsLeft = p.loopsLeft - 1;
          if (loopsLeft <= 0) return { ...p, playing: false, loopsLeft: 0 };
          setTimeout(() => playRepeatStep({ ...p, loopsLeft }), 400);
          return { ...p, loopsLeft };
        }
        // range mode: تقدّم لآية تالية داخل النطاق، ولو خلص النطاق ابدأ لفة جديدة لحد ما تخلص عدد اللفات
        const nextGlobal = p.cursorGlobal + 1;
        if (nextGlobal > p.rangeEndGlobal) {
          const loopsLeft = p.loopsLeft - 1;
          if (loopsLeft <= 0) return { ...p, playing: false, loopsLeft: 0 };
          const restarted = { ...p, cursorGlobal: p.rangeStartGlobal, loopsLeft };
          setTimeout(() => playRepeatStep(restarted), 500);
          return restarted;
        }
        const advanced = { ...p, cursorGlobal: nextGlobal };
        setTimeout(() => playRepeatStep(advanced), 400);
        return advanced;
      });
    };
    el.addEventListener("ended", onEnded);
    return () => el.removeEventListener("ended", onEnded);
  }, [reciterForRepeat]); // eslint-disable-line

  const startSingleRepeat = (item, count) => {
    const panel = { item, mode: "single", loopsLeft: count, cursorGlobal: item.globalNumber, playing: true, error: null, reciterId: repeatReciterId, speed: 1 };
    setRepeatPanel(panel);
    playRepeatStep(panel);
  };
  const startRangeRepeat = (item, rangeSize, loops) => {
    const rangeEndGlobal = item.globalNumber + rangeSize - 1;
    const panel = { item, mode: "range", loopsLeft: loops, cursorGlobal: item.globalNumber, rangeStartGlobal: item.globalNumber, rangeEndGlobal, playing: true, error: null, reciterId: repeatReciterId, speed: 1 };
    setRepeatPanel(panel);
    playRepeatStep(panel);
  };
  const stopRepeat = () => { repeatAudioElRef.current?.pause(); setRepeatPanel(null); };
  const [wordPopup, setWordPopup] = useState(null); // { globalNumber, word, meaning, loading } | null

  // كاش محلي دائم (window.storage) لكل آية تفسير + معاني كلماتها — بعد أول تحميل ناجح
  // تُقرأ من الجهاز مباشرة بدون إنترنت في أي مرة تالية لنفس الآية
  const cacheKeyFor = (surahId, ayahNum) => `tafsir:${surahId}:${ayahNum}`;

  const loadTafsirData = async (surahId, ayahNum) => {
    const key = cacheKeyFor(surahId, ayahNum);
    try {
      const cached = await window.storage.get(key);
      if (cached?.value) return JSON.parse(cached.value); // موجود محليًا — لا حاجة للإنترنت
    } catch { /* لا يوجد كاش، تابع للشبكة */ }
    const [tafsirRes, wordsRes] = await Promise.allSettled([
      fetchTafsir(surahId, ayahNum),
      fetchWordMeanings(surahId, ayahNum),
    ]);
    const tafsir = tafsirRes.status === "fulfilled" ? (tafsirRes.value || "لا يوجد تفسير متاح لهذه الآية حاليًا.") : null;
    const words = wordsRes.status === "fulfilled" ? wordsRes.value : null;
    if (tafsir || words) {
      try { await window.storage.set(key, JSON.stringify({ tafsir, words: words || [] })); } catch { /* تجاهل فشل الحفظ */ }
    }
    if (!tafsir && !words) throw new Error("both failed");
    return { tafsir, words: words || [] };
  };

  // تحميل استباقي هادئ لتفسير ومعاني كل آيات الصفحة الحالية في الخلفية (لو النت متاح)
  // عشان الصفحة اللي اتفتحت مرة تبقى شغالة بالكامل بدون نت في أي زيارة تالية، مش بس اللي اتدوس عليها
  useEffect(() => {
    let cancelled = false;
    (async () => {
      for (const item of pageItems) {
        if (cancelled) return;
        try { await loadTafsirData(item.surahId, item.localIndex + 1); } catch { /* هيتحاول تاني وقت الحاجة */ }
        await new Promise((r) => setTimeout(r, 150)); // مسافة بسيطة بين الطلبات
      }
    })();
    return () => { cancelled = true; };
  }, [mushafPage]); // eslint-disable-line

  const loadTafsir = async (item, view = "tafsir") => {
    const target = item || tafsirTarget;
    if (!target) return;
    setTafsirTarget(target);
    setTafsirView(view);
    setTafsirGlobal(target.globalNumber);
    setTafsirText("loading");
    setWordMeanings("loading");
    try {
      const data = await loadTafsirData(target.surahId, target.localIndex + 1);
      setTafsirText(data.tafsir || "لا يوجد تفسير متاح لهذه الآية حاليًا.");
      setWordMeanings(data.words || []);
    } catch {
      setTafsirText("error");
      setWordMeanings("error");
    }
  };

  // قاموس معاني الكلمات: دوسة على كلمة بمفردها تعرض معناها في نافذة صغيرة، بدون فتح التفسير كاملًا
  const lookupWord = async (item, word) => {
    setWordPopup({ globalNumber: item.globalNumber, word, meaning: null, loading: true });
    try {
      const data = await loadTafsirData(item.surahId, item.localIndex + 1);
      const norm = (s) => (s || "").replace(/[\u064B-\u065F\u0670]/g, "").trim();
      const hit = (data.words || []).find((w) => norm(w.word) === norm(word) || norm(word).includes(norm(w.word)) || norm(w.word).includes(norm(word)));
      setWordPopup({
        globalNumber: item.globalNumber, word, loading: false,
        meaning: hit ? hit.meaning : "هذه الكلمة من الكلمات الواضحة — دوسي على رقم الآية للتفسير الكامل.",
      });
    } catch {
      setWordPopup({ globalNumber: item.globalNumber, word, loading: false, meaning: "تعذّر تحميل المعنى الآن." });
    }
  };

  useEffect(() => {
    const el = listenAudioRef.current;
    if (!el) return;
    const onEnded = () => {
      setListenPanel((p) => {
        if (!p) return null;
        if (p.cursorGlobal >= p.endGlobal) return { ...p, playing: false, done: true };
        return { ...p, cursorGlobal: p.cursorGlobal + 1 };
      });
    };
    const onError = () => setListenPanel((p) => p ? { ...p, playing: false, error: "تعذّر تشغيل الصوت." } : p);
    el.addEventListener("ended", onEnded);
    el.addEventListener("error", onError);
    return () => { el.removeEventListener("ended", onEnded); el.removeEventListener("error", onError); /* لا نوقف الصوت عند تغيير التبويب */ };
  }, []);
  useEffect(() => {
    if (!listenPanel?.playing || !listenAudioRef.current) return;
    const r = RECITERS.find((x) => x.id === listenPanel.reciterId);
    if (!r?.edition || r.surahOnly) {
      setListenPanel((p) => p ? { ...p, playing: false, error: "اختاري قارئًا يدعم تشغيل الآيات." } : p);
      return;
    }
    const el = listenAudioRef.current;
    el.src = ayahAudioUrl(r.edition, listenPanel.cursorGlobal);
    el.playbackRate = listenPanel.speed || 1;
    el.play().catch(() => setListenPanel((p) => p ? { ...p, playing: false, error: "تعذّر تشغيل الصوت — اضغطي تشغيل مرة أخرى." } : p));
  }, [listenPanel?.playing, listenPanel?.cursorGlobal, listenPanel?.reciterId, listenPanel?.speed]);

  const startListenRange = (item, fromAyah, toAyah, reciterId, speed) => {
    const s = FULL_QURAN.find((x) => x.id === item.surahId);
    if (!s) return;
    const start = s.g0 + fromAyah - 1;
    const end = s.g0 + toAyah - 1;
    listenAudioRef.current?.pause();
    setListenPanel({ item, fromAyah, toAyah, startGlobal: start, endGlobal: end, cursorGlobal: start, reciterId, speed, playing: true, done: false, error: null });
  };
  const stopListenRange = () => { listenAudioRef.current?.pause(); setListenPanel(null); };

  const markPageRead = () => {
    const seen = Array.isArray(day.quranReadPages) ? day.quranReadPages : [];
    if (seen.includes(mushafPage)) return;
    updateDay({ quranPages: seen.length + 1, quranReadPages: [...seen, mushafPage] });
  };

  const filteredList = search.trim()
    ? list.filter((s) => s.name.includes(search.trim()) || String(s.id) === search.trim())
    : list;

  if (screen === "reciters") return <RecitersScreen prefs={prefs} updatePrefs={updatePrefs} onBack={() => setScreen("list")} field="quranReciter" title="قارئ القرآن (للقراءة والتكرار)" />;
  if (screen === "search") {
    return (
      <div>
        <TopBarBack onBack={() => setScreen("list")} title="البحث في القرآن الكريم" />
        <input
          value={ayahSearchQuery}
          onChange={(e) => runAyahSearch(e.target.value)}
          placeholder="اكتبي كلمة أو جزء من آية..."
          style={{ ...inputStyle(), width: "100%", marginBottom: 14 }}
          autoFocus
        />
        <p style={{ fontSize: 11.5, color: "var(--textDim)", marginBottom: 14 }}>
          البحث يعمل بالكامل من داخل الجهاز — بدون إنترنت. اكتبي بدون تشكيل، والبحث بيتجاهل التشكيل تلقائيًا.
        </p>
        {ayahSearchResults === null && ayahSearchQuery.trim().length > 0 && (
          <p style={{ fontSize: 12.5, color: "var(--textDim)", textAlign: "center" }}>اكتبي حرفين على الأقل...</p>
        )}
        {ayahSearchResults && ayahSearchResults.length === 0 && (
          <EmptyState icon={<Info size={22} />} title="مفيش نتائج — جرّبي كلمة تانية" />
        )}
        {ayahSearchResults && ayahSearchResults.length > 0 && (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <p style={{ fontSize: 11.5, color: "var(--textDim)" }}>
              {ayahSearchResults.length}{ayahSearchResults.length >= 100 ? "+" : ""} نتيجة
            </p>
            {ayahSearchResults.map((r, i) => (
              <Card
                key={i}
                onClick={() => { setSurahId(r.surahId); setMushafPage(mushafPageForGlobal(r.globalNumber)); setScreen("reader"); }}
                style={{ padding: 14, cursor: "pointer" }}
              >
                <div style={{ fontSize: 11.5, color: "var(--accent)", marginBottom: 5, fontFamily: "'Cairo', sans-serif" }}>
                  سورة {r.surahName} — آية {r.localIndex + 1}
                </div>
                <div style={{ fontFamily: "'Amiri', serif", fontSize: 16, color: "var(--text)", lineHeight: 1.9 }}>{r.text}</div>
              </Card>
            ))}
          </div>
        )}
      </div>
    );
  }
  if (screen === "memorize") {
    if (!ayat || ayat === "error") {
      return (
        <div>
          <TopBarBack onBack={() => setScreen("reader")} title="وضع التسميع" />
          <EmptyState icon={<Mic size={26} />} title={ayat === "error" ? "تعذّر تحميل نص هذه السورة الآن" : "جارٍ تحميل الآيات..."} />
        </div>
      );
    }
    return <MemorizeFlow surahId={surahId} surahName={surahMeta.name} ayat={ayat} reciter={RECITERS.find((r) => r.id === prefs.quranReciter)} day={day} updateDay={updateDay} onBack={() => setScreen("reader")} />;
  }

  if (screen === "reader") {
    const audioSurahOnPage = audio.player.playing && pageItems.some((it) => it.surahId === audio.player.surahId);
    // عنوان الصفحة: إذا كانت الصفحة بأكملها لسورة واحدة اعرض اسمها، وإلا اعرض "سورة X ... Y"
    const surahsOnPage = [...new Set(pageItems.map((it) => it.surahId))];
    const pageTitle = surahsOnPage.length === 1
      ? `سورة ${surahForGlobal(pgStart).name}`
      : `${surahForGlobal(pgStart).name} ← ${surahForGlobal(pgEnd).name}`;
    let lastRenderedSurah = null;
    return (
      <div>
        <TopBarBack onBack={() => setScreen("list")} title="القرآن الكريم" right={
          <button onClick={() => setNightMode(!nightMode)} style={iconBtn()}><Moon size={17} color={nightMode ? "var(--accent)" : "var(--textDim)"} /></button>
        } />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "0 4px 10px" }}>
          <span style={{
            fontSize: 11, color: nightMode ? "#C9A66B" : "var(--accent)", fontFamily: "'Cairo', sans-serif", fontWeight: 700,
            border: `1px solid ${nightMode ? "#4a4636" : "var(--accent)"}`, borderRadius: 20, padding: "3px 12px",
          }}>
            الجزء {juzForGlobal(pgStart)}
          </span>
          <span style={{
            fontSize: 11, color: nightMode ? "#C9A66B" : "var(--accent)", fontFamily: "'Cairo', sans-serif", fontWeight: 700,
            border: `1px solid ${nightMode ? "#4a4636" : "var(--accent)"}`, borderRadius: 20, padding: "3px 12px",
          }}>
            الحزب {hizbForGlobal(pgStart)}
          </span>
        </div>
        <div
          onTouchStart={onTouchStart}
          onTouchEnd={onTouchEnd}
          onMouseDown={onMouseDown}
          onMouseUp={onMouseUp}
          style={{
            background: nightMode ? "#100D07" : "var(--surface)",
            border: `1px solid ${nightMode ? "#3a3627" : "var(--accent)"}`,
            outline: `1px solid ${nightMode ? "#241f14" : "var(--border)"}`,
            outlineOffset: -6,
            borderRadius: 16,
            padding: "14px 10px 24px", minHeight: 380, position: "relative", overflow: "hidden",
            boxShadow: nightMode ? "var(--shadow)" : "0 14px 34px rgba(60,50,30,0.10), inset 0 0 40px rgba(60,50,30,0.03)",
            perspective: 1200, touchAction: "pan-y", cursor: "grab", userSelect: "none",
          }}
        >
          <div style={{
            transform: flip ? `rotateY(${flip === "next" ? "-16deg" : "16deg"}) scale(0.96)` : "rotateY(0deg) scale(1)",
            opacity: flip ? 0.35 : 1, transition: "transform .26s ease, opacity .26s ease", transformOrigin: flip === "next" ? "right" : "left",
            boxShadow: flip ? (flip === "next" ? "-18px 0 30px -20px rgba(0,0,0,0.35)" : "18px 0 30px -20px rgba(0,0,0,0.35)") : "none",
          }}>
            {(prefs.tajweedColoringEnabled || offlineDownload.status === "downloading") && (
              <div style={{ textAlign: "center", marginBottom: 10 }}>
                {!prefs.tajweedColoringEnabled ? (
                  <span
                    title="مصحف المدينة النبوية — بيتجهّز في الخلفية عشان يشتغل بدون نت"
                    style={{ fontSize: 10, color: nightMode ? "#5f5c4d" : "#b7ac8f", fontFamily: "'Cairo', sans-serif" }}
                  >
                    {`⏳ بيتجهّز للقراءة بدون نت… ${offlineDownload.done}/${offlineDownload.total}`}
                  </span>
                ) : (
                  <span style={{ fontSize: 10.5, color: nightMode ? "#8f8a72" : "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>
                    مصحف عثماني ملوّن بأحكام التجويد
                  </span>
                )}
              </div>
            )}
            {true ? (
              <MushafRealPage
                pageNum={mushafPage}
                pageItems={pageItems}
                markedAyah={markedAyah}
                ayahTags={ayahTags}
                hiddenAyahs={hiddenAyahs}
                onToggleHiddenAyah={toggleHiddenAyah}
                nightMode={nightMode}
                tajweedEnabled={prefs.tajweedColoringEnabled}
                tajweedData={tajweedData}
                onOpenAyahMenu={(item) => setAyahMenu({ item, mode: "menu" })}
              />
            ) : (
            /* نص متدفق متصل تمامًا كما في المصحف — الإخفاء يتم داخل السطر بدون كسر التخطيط */
            <div style={{ textAlign: "justify", lineHeight: 2.6, fontFamily: "'Amiri', serif", fontWeight: 600, WebkitTextStroke: nightMode ? "0.4px currentColor" : "0.35px currentColor" }}>
              {pageItems.map((a) => {
                const g = a.globalNumber;
                const showSurahHeader = a.surahId !== lastRenderedSurah && a.localIndex === 0;
                lastRenderedSurah = a.surahId;
                const isHidden = !!hiddenAyahs[g];
                return (
                  <React.Fragment key={g}>
                    {showSurahHeader && (
                      <div style={{
                        display: "flex", alignItems: "center", justifyContent: "center", gap: 10,
                        margin: "16px 0 12px",
                      }}>
                        <span style={{ flex: 1, maxWidth: 40, height: 1, background: "var(--accent)", opacity: 0.4 }} />
                        <span style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 17, color: "var(--accent)" }}>
                          سورة {a.surahName}
                        </span>
                        <span style={{ flex: 1, maxWidth: 40, height: 1, background: "var(--accent)", opacity: 0.4 }} />
                      </div>
                    )}
                    {showSurahHeader && a.surahId !== 1 && a.surahId !== 9 && (
                      <div style={{
                        display: "block", textAlign: "center", margin: "0 0 16px",
                        fontFamily: "'Amiri', serif", fontSize: nightMode ? 24 : 23, fontWeight: 700,
                        color: nightMode ? "#E9D9AE" : "var(--accent)",
                      }}>
                        بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ
                      </div>
                    )}
                    {isHidden ? (
                      /* إخفاء الكلمات مع الحفاظ على أبعاد الآية نفسها: كل كلمة تصبح
                         خطًا متقطعًا مستقلًا، بينما النص الأصلي يظل موجودًا بشفافية
                         حتى لا يتغير التفاف السطر أو المسافات أو مكان رقم الآية. */
                      <span
                        onClick={() => {
                          const next = { ...hiddenAyahs };
                          delete next[g];
                          setHiddenAyahs(next);
                          saveHiddenAyahs(next);
                        }}
                        title="اضغطي على الآية لإظهارها مرة أخرى"
                        aria-label={`إظهار الآية ${a.localIndex + 1}`}
                        style={{
                          fontSize: nightMode ? 23 : 22,
                          fontWeight: 600,
                          lineHeight: 2.6,
                          color: "transparent",
                          borderRadius: 4,
                          padding: "6px 3px",
                          cursor: "pointer",
                          display: "inline",
                          boxDecorationBreak: "clone",
                          WebkitBoxDecorationBreak: "clone",
                          transition: "opacity .15s",
                        }}
                      >
                        {a.text.trim().split(/\s+/).map((word, wi, words) => (
                          <React.Fragment key={`${g}-hidden-${wi}`}>
                            <span style={{
                              display: "inline-block",
                              color: "transparent",
                              borderBottom: `2px dashed ${nightMode ? "#8a7a4d" : "var(--accent)"}`,
                              padding: "0 2px 1px",
                              lineHeight: 1.35,
                              verticalAlign: "baseline",
                            }}>{word}</span>
                            {wi < words.length - 1 ? " " : ""}
                          </React.Fragment>
                        ))}
                        {" "}
                        <span style={{ color: "var(--accent)", fontSize: 13, backgroundImage: "none", display: "inline-block", border: "none" }}>﴿{a.localIndex + 1}﴾</span>
                        {"  "}
                      </span>
                    ) : (
                      <span
                        onTouchStart={() => startLongPress(a)}
                        onTouchEnd={cancelLongPress}
                        onTouchMove={cancelLongPress}
                        onMouseDown={() => startLongPress(a)}
                        onMouseUp={cancelLongPress}
                        onMouseLeave={cancelLongPress}
                        style={{
                          fontSize: nightMode ? 23 : 22, fontWeight: 600, color: nightMode ? "#EBE1C6" : "var(--text)",
                          background: (audioSurahOnPage && audio.player.surahId === a.surahId && audio.player.ayahIndex === a.localIndex) || (tafsirGlobal === g && tafsirText)
                            ? "var(--accentSoft)"
                            : "transparent",
                          borderRadius: 6, padding: "6px 3px", display: "inline",
                          boxDecorationBreak: "clone", WebkitBoxDecorationBreak: "clone",
                          transition: "background .3s",
                        }}
                      >
                        {(() => {
                          const inRecitationRange = recitationRange && a.surahId === recitationRange.surahId && a.localIndex + 1 >= recitationRange.fromAyah && a.localIndex + 1 <= recitationRange.toAyah;
                          if (inRecitationRange) {
                            const rangeIdx = a.localIndex - (recitationRange.fromAyah - 1);
                            const words = tokenizeWords(a.text);
                            return words.map((w, wi) => {
                              const st = recitation.getWordStatus(rangeIdx, w.id);
                              // 🟢 صحيح | 🔴 خطأ (بيتحدد ويظهر النص الصح تحته) | 🟡 يحتاج مراجعة (غير واثق أو اتخطى)
                              const revealed = st !== "pending";
                              let color = "inherit", underline = "none", bg = "transparent";
                              if (!revealed) {
                                color = "transparent";
                                underline = `2px dashed ${nightMode ? "#5a563f" : "var(--accent)"}`;
                              } else if (st === "correct" || st === "reordered") {
                                color = "#1a9c5c"; // 🟢
                              } else if (st === "wrong") {
                                color = "#d0342c"; bg = "rgba(208,52,44,0.1)"; // 🔴
                              } else if (st === "uncertain" || st === "skipped") {
                                color = "#c78a1e"; bg = "rgba(199,138,30,0.1)"; // 🟡
                              }
                              return (
                                <span key={wi}>
                                  <span style={{ color, backgroundColor: bg, borderBottom: underline, borderRadius: 3, padding: revealed && bg !== "transparent" ? "0 2px" : 0 }}>
                                    {w.text}
                                  </span>
                                  {wi < words.length - 1 ? " " : ""}
                                </span>
                              );
                            });
                          }
                          if (prefs.tajweedColoringEnabled && tajweedData[a.surahId]) {
                            const entry = tajweedData[a.surahId].find((e) => e.ayah === a.localIndex + 1);
                            const spans = buildTajweedSpans(a.text, entry ? entry.annotations : []);
                            return spans.map((s, si) => (
                              <span key={si} style={s.color ? { color: s.color } : undefined}>{s.text}</span>
                            ));
                          }
                          return a.text.split(/(\s+)/).map((tok, wi) => (
                            /\s+/.test(tok) ? tok : (
                              <span
                                key={wi}
                                onClick={(e) => { e.stopPropagation(); if (!longPressFired.current) lookupWord(a, tok); }}
                                title="اضغط لمعنى الكلمة، أو اضغطي مطوّلًا على الآية لكل الخيارات"
                                style={{
                                  cursor: "pointer",
                                  background: wordPopup && wordPopup.globalNumber === g && wordPopup.word === tok ? "var(--accentSoft)" : "transparent",
                                  borderRadius: 4,
                                }}
                              >
                                {tok}
                              </span>
                            )
                          ));
                        })()}
                        {" "}
                        <span
                          onClick={() => { if (!longPressFired.current) setAyahMenu({ item: a, mode: "menu" }); }}
                          title="اضغطي هنا (أو اضغطي مطوّلًا على الآية) لكل خيارات هذه الآية"
                          style={{
                            color: "var(--accent)", fontSize: 13, cursor: "pointer", fontWeight: 700,
                            background: "var(--accentSoft)", borderRadius: 8, padding: "2px 7px", display: "inline-block",
                          }}
                        >
                          ﴿{a.localIndex + 1}﴾
                        </span>
                        {markedAyah?.globalNumber === g && (
                          <span
                            onClick={(e) => { e.stopPropagation(); toggleMarkedAyah(a); }}
                            title="اضغطي لإلغاء العلامة"
                            style={{ display: "inline-flex", verticalAlign: "middle", margin: "0 2px", cursor: "pointer", color: "var(--accent)" }}
                          >
                            <Bookmark size={15} fill="currentColor" strokeWidth={1.5} />
                          </span>
                        )}
                        {(ayahTags[g] || []).length > 0 && (
                          <span
                            onClick={(e) => { e.stopPropagation(); setTagSetup({ item: a }); }}
                            title="اضغطي لتعديل علامات هذه الآية"
                            style={{ display: "inline-flex", verticalAlign: "middle", margin: "0 2px", cursor: "pointer", fontSize: 12 }}
                          >
                            {ayahTags[g].map((tid) => AYAH_TAG_TYPES.find((t) => t.id === tid)?.icon).join("")}
                          </span>
                        )}
                        {"  "}
                      </span>
                    )}
                  </React.Fragment>
                );
              })}
            </div>
            )}
          </div>
          {wordPopup && (
            <div
              onClick={() => setWordPopup(null)}
              style={{
                position: "absolute", insetInline: 16, bottom: 14, background: "var(--surface)", border: "1px solid var(--accent)",
                borderRadius: 14, padding: "10px 14px", boxShadow: "0 8px 24px rgba(0,0,0,0.18)", cursor: "pointer", zIndex: 5,
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
                <div>
                  <span style={{ fontFamily: "'Amiri', serif", fontSize: 17, color: "var(--accent)", fontWeight: 700 }}>{wordPopup.word}</span>
                  <p style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5, color: "var(--text)", margin: "4px 0 0", lineHeight: 1.7 }}>
                    {wordPopup.loading ? "جارٍ البحث عن المعنى..." : wordPopup.meaning}
                  </p>
                </div>
                <X size={15} color="var(--textDim)" style={{ flexShrink: 0, marginTop: 2 }} />
              </div>
            </div>
          )}
          {ayahMenu && ayahMenu.mode === "menu" && (
            <div style={{
              position: "absolute", inset: 0, zIndex: 12,
              pointerEvents: "none",
            }}>
              <div style={{
                position: "absolute", left: "50%", top: "50%", transform: "translate(-50%,-50%)",
                width: 260, height: 260, pointerEvents: "none",
              }}>
                {/* هالة خفيفة حول المركز بدل طبقة سوداء كاملة فوق المصحف */}
                <div style={{
                  position: "absolute", left: "50%", top: "50%", transform: "translate(-50%,-50%)",
                  width: 78, height: 78, borderRadius: "50%", border: "1px solid var(--accent)",
                  background: "color-mix(in srgb, var(--surface) 92%, transparent)",
                  boxShadow: "0 8px 24px rgba(0,0,0,.18)",
                }} />
                <button
                  onClick={() => setAyahMenu(null)}
                  aria-label="إغلاق قائمة الآية"
                  style={{
                    position: "absolute", left: "50%", top: "50%", transform: "translate(-50%,-50%)",
                    width: 62, height: 62, borderRadius: "50%", border: "2px solid var(--accent)",
                    background: "var(--surface)", color: "var(--text)", fontFamily: "'Cairo', sans-serif",
                    fontSize: 11.5, fontWeight: 700, zIndex: 2, cursor: "pointer", pointerEvents: "auto",
                    boxShadow: "0 7px 22px rgba(0,0,0,.2)",
                  }}
                >
                  آية {ayahMenu.item.localIndex + 1}
                </button>
                {[
                  { label: "استماع", icon: "🔊", angle: -90, action: () => { const it = ayahMenu.item; setListenSetup({ item: it, fromAyah: it.localIndex + 1, toAyah: it.localIndex + 1 }); setAyahMenu(null); } },
                  { label: "التفسير", icon: "📖", angle: -45, action: () => { loadTafsir(ayahMenu.item, "tafsir"); setAyahMenu(null); } },
                  { label: "معاني الكلمات", icon: "🔤", angle: 0, action: () => { loadTafsir(ayahMenu.item, "words"); setAyahMenu(null); } },
                  {
                    label: hiddenAyahs[ayahMenu.item.globalNumber] ? "إظهار الآية" : "إخفاء الآيات",
                    icon: <EyeOff size={17} strokeWidth={1.75} />,
                    angle: 45,
                    action: () => {
                      const it = ayahMenu.item;
                      if (hiddenAyahs[it.globalNumber]) toggleHiddenAyah(it);
                      else setHideSetup({ item: it, fromAyah: it.localIndex + 1, toAyah: it.localIndex + 1 });
                      setAyahMenu(null);
                    },
                  },
                  {
                    label: markedAyah?.globalNumber === ayahMenu.item.globalNumber ? "إلغاء العلامة" : "علّمي هنا",
                    icon: <Bookmark size={17} strokeWidth={1.75} fill={markedAyah?.globalNumber === ayahMenu.item.globalNumber ? "currentColor" : "none"} />,
                    angle: 90,
                    action: () => { toggleMarkedAyah(ayahMenu.item); setAyahMenu(null); },
                  },
                  {
                    label: "علامات", icon: "🏷️", angle: 135,
                    action: () => { setTagSetup({ item: ayahMenu.item }); setAyahMenu(null); },
                  },
                  { label: "تكرار الآيات", icon: "🔁", angle: 180, action: () => { const it = ayahMenu.item; setAyahMenu(null); setRepeatSetup({ item: it, fromAyah: it.localIndex + 1, toAyah: it.localIndex + 1, count: 5, speed: 1 }); } },
                  {
                    label: "مشاركة", icon: "↗", angle: 225,
                    action: () => { const it = ayahMenu.item; setAyahMenu(null); setShareSetup({ item: it }); },
                  },
                ].map((o) => {
                  const rad = o.angle * Math.PI / 180;
                  const x = 50 + Math.cos(rad) * 35;
                  const y = 50 + Math.sin(rad) * 35;
                  return (
                    <button key={o.label} onClick={o.action} style={{
                      position: "absolute", left: `${x}%`, top: `${y}%`, transform: "translate(-50%,-50%)",
                      width: 62, height: 62, borderRadius: "50%", border: "1px solid var(--accent)",
                      background: "var(--surface)", color: "var(--text)", fontFamily: "'Cairo', sans-serif",
                      fontSize: 8.5, fontWeight: 700, cursor: "pointer", pointerEvents: "auto",
                      boxShadow: "0 6px 18px rgba(0,0,0,.16)", display: "flex", flexDirection: "column",
                      alignItems: "center", justifyContent: "center", gap: 2,
                    }}>
                      <span style={{ fontSize: 17, lineHeight: 1 }}>{o.icon}</span>
                      <span style={{ whiteSpace: "nowrap" }}>{o.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {tafsirTarget && tafsirText && (
            <div style={{
              position: "absolute", top: 18, left: 18, right: 18, zIndex: 16,
              background: "var(--surface)", border: "1px solid var(--accent)", borderRadius: 18,
              padding: "14px 16px 16px", boxShadow: "0 18px 42px rgba(0,0,0,.28)",
              maxHeight: "62%", overflowY: "auto", direction: "rtl",
            }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, marginBottom: 10 }}>
                <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: "var(--accent)" }}>
                  {tafsirView === "words" ? "معاني كلمات الآية" : `تفسير الآية ${tafsirTarget.localIndex + 1}`}
                </div>
                <button onClick={() => { setTafsirTarget(null); setTafsirGlobal(null); setTafsirText(null); setWordMeanings(null); }} aria-label="إغلاق" style={{
                  width: 30, height: 30, borderRadius: "50%", border: "1px solid var(--border)",
                  background: "var(--accentSoft)", color: "var(--textDim)", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center",
                }}><X size={16} /></button>
              </div>
              <div style={{ fontSize: 10.5, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif", marginBottom: 8 }}>
                سورة {tafsirTarget.surahId ? (FULL_QURAN.find(s => s.id === tafsirTarget.surahId)?.name || "") : ""} — آية {tafsirTarget.localIndex + 1}
              </div>
              {tafsirView === "tafsir" && (
                <p style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, color: "var(--text)", lineHeight: 1.95, margin: 0 }}>
                  {tafsirText === "loading" ? "جارٍ تحميل التفسير..." : tafsirText === "error" ? "تعذّر تحميل التفسير الآن." : tafsirText}
                </p>
              )}
              {tafsirView === "words" && (
                wordMeanings === "loading" ? <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5, color: "var(--textDim)" }}>جارٍ تحميل معاني الكلمات...</div> :
                wordMeanings === "error" ? <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5, color: "var(--textDim)" }}>تعذّر تحميل المعاني الآن.</div> :
                <div style={{ display: "grid", gap: 7 }}>
                  {(Array.isArray(wordMeanings) ? wordMeanings : []).map((w, i) => (
                    <div key={i} style={{ display: "flex", alignItems: "baseline", gap: 8, paddingBottom: 6, borderBottom: i < wordMeanings.length - 1 ? "1px solid var(--border)" : "none" }}>
                      <span style={{ fontFamily: "'Amiri', serif", fontSize: 16, color: "var(--accent)", fontWeight: 700 }}>{w.word}</span>
                      <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5, color: "var(--textDim)", lineHeight: 1.7 }}>{w.meaning}</span>
                    </div>
                  ))}
                  {Array.isArray(wordMeanings) && wordMeanings.length === 0 && <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5, color: "var(--textDim)" }}>لا توجد معاني كلمات متاحة لهذه الآية حاليًا.</div>}
                </div>
              )}
            </div>
          )}

          {hideSetup && (
            <div style={{ position: "absolute", insetInline: 16, bottom: 14, background: "var(--surface)", border: "1px solid var(--accent)", borderRadius: 16, padding: 14, boxShadow: "0 10px 28px rgba(0,0,0,.2)", zIndex: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                <b style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, display: "flex", alignItems: "center", gap: 6 }}><EyeOff size={15} strokeWidth={1.75} /> إخفاء آيات محددة</b>
                <X size={16} color="var(--textDim)" style={{ cursor: "pointer" }} onClick={() => setHideSetup(null)} />
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <label style={{ ...fieldLabel(), flex: 1 }}>من الآية
                  <select value={hideSetup.fromAyah} onChange={(e) => setHideSetup({ ...hideSetup, fromAyah: Number(e.target.value), toAyah: Math.max(Number(e.target.value), hideSetup.toAyah) })} style={inputStyle()}>
                    {Array.from({ length: FULL_QURAN.find((s) => s.id === hideSetup.item.surahId)?.verses.length || 1 }, (_, i) => i + 1).map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </label>
                <label style={{ ...fieldLabel(), flex: 1 }}>إلى الآية
                  <select value={hideSetup.toAyah} onChange={(e) => setHideSetup({ ...hideSetup, toAyah: Number(e.target.value) })} style={inputStyle()}>
                    {Array.from({ length: FULL_QURAN.find((s) => s.id === hideSetup.item.surahId)?.verses.length || 1 }, (_, i) => i + 1).filter(n => n >= hideSetup.fromAyah).map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </label>
              </div>
              <p style={{ fontSize: 10.5, color: "var(--textDim)", margin: "8px 0", lineHeight: 1.6 }}>سيتم إخفاء هذه الآيات فقط، ولن يختفي باقي المصحف.</p>
              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={() => setHideSetup(null)} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}>إلغاء</button>
                <button onClick={() => {
                  const s = FULL_QURAN.find(x => x.id === hideSetup.item.surahId);
                  const next = { ...hiddenAyahs };
                  for (let n = hideSetup.fromAyah; n <= hideSetup.toAyah; n++) next[s.g0 + n - 1] = true;
                  setHiddenAyahs(next); saveHiddenAyahs(next); setHideSetup(null);
                }} style={{ ...btnPrimarySmall(), flex: 1 }}>إخفاء الآن</button>
              </div>
            </div>
          )}

          {tagSetup && (
            <div style={{ position: "absolute", insetInline: 16, bottom: 14, background: "var(--surface)", border: "1px solid var(--accent)", borderRadius: 16, padding: 14, boxShadow: "0 10px 28px rgba(0,0,0,.2)", zIndex: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                <b style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13 }}>🏷️ علامات على الآية {tagSetup.item.localIndex + 1}</b>
                <X size={16} color="var(--textDim)" style={{ cursor: "pointer" }} onClick={() => setTagSetup(null)} />
              </div>
              <p style={{ fontSize: 10.5, color: "var(--textDim)", margin: "0 0 10px", lineHeight: 1.6 }}>تقدري تختاري أكتر من علامة على نفس الآية.</p>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                {AYAH_TAG_TYPES.map((t) => {
                  const active = (ayahTags[tagSetup.item.globalNumber] || []).includes(t.id);
                  return (
                    <button
                      key={t.id}
                      onClick={() => { toggleAyahTag(tagSetup.item.globalNumber, t.id); setTagSetup(null); }}
                      style={{
                        padding: "8px 12px", borderRadius: 12, cursor: "pointer",
                        border: `1px solid ${active ? "transparent" : "var(--border)"}`,
                        background: active ? "var(--primary)" : "var(--surfaceAlt)",
                        color: active ? "var(--onPrimary)" : "var(--text)",
                        fontFamily: "'Cairo', sans-serif", fontSize: 12.5, fontWeight: 600,
                        display: "flex", alignItems: "center", gap: 6,
                      }}
                    >
                      {t.icon} {t.label}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {shareSetup && (
            <div style={{ position: "absolute", insetInline: 16, bottom: 14, background: "var(--surface)", border: "1px solid var(--accent)", borderRadius: 16, padding: 14, boxShadow: "0 10px 28px rgba(0,0,0,.2)", zIndex: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                <b style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13 }}>↗ مشاركة الآية {shareSetup.item.localIndex + 1}</b>
                <X size={16} color="var(--textDim)" style={{ cursor: "pointer" }} onClick={() => setShareSetup(null)} />
              </div>
              <div style={{ display: "flex", gap: 10 }}>
                <button
                  onClick={async () => {
                    const it = shareSetup.item;
                    setShareSetup(null);
                    const shareText = `قال تعالى:\n\n${it.text}\n\n﴿سورة ${it.surahName}: ${it.localIndex + 1}﴾\n\nمشاركة من تطبيق أنيسك`;
                    if (navigator.share) {
                      try { await navigator.share({ title: `آية ${it.localIndex + 1} من سورة ${it.surahName}`, text: shareText }); return; } catch { /* تجاهل */ }
                    }
                    try { await navigator.clipboard?.writeText(shareText); } catch { /* تجاهل */ }
                  }}
                  style={{ ...btnGhost(), flex: 1, justifyContent: "center", flexDirection: "column", gap: 6, padding: "16px 10px", height: "auto" }}
                >
                  <span style={{ fontSize: 22 }}>📝</span>
                  <span>مشاركة كنص</span>
                </button>
                <button
                  disabled={sharingImage}
                  onClick={async () => {
                    const it = shareSetup.item;
                    setSharingImage(true);
                    const shareText = `قال تعالى:\n\n${it.text}\n\n﴿سورة ${it.surahName}: ${it.localIndex + 1}﴾\n\nمشاركة من تطبيق أنيسك`;
                    let blob = null;
                    try { blob = await generateVerseCardQCF(it); }
                    catch { try { blob = await generateVerseCard({ text: it.text, ayahNumber: it.localIndex + 1, surah: it.surahName }); } catch { /* تجاهل */ } }
                    setSharingImage(false);
                    setShareSetup(null);
                    if (blob && navigator.share && navigator.canShare) {
                      try {
                        const file = new File([blob], "anisk-ayah.png", { type: "image/png" });
                        if (navigator.canShare({ files: [file] })) {
                          await navigator.share({ files: [file], title: `آية ${it.localIndex + 1} من سورة ${it.surahName}`, text: shareText });
                          return;
                        }
                      } catch { /* تجاهل ونزل للتنزيل المباشر تحت */ }
                    }
                    // احتياطي شغال دايمًا: تنزيل الصورة مباشرة — مهم خصوصًا وقت التطوير المحلي
                    // (زي فتح التطبيق من عنوان IP بدل localhost أو HTTPS) حيث navigator.share
                    // مش متاح خالص لأسباب أمنية في المتصفح.
                    if (blob) {
                      const url = URL.createObjectURL(blob);
                      const a = document.createElement("a");
                      a.href = url; a.download = "anisk-ayah.png";
                      document.body.appendChild(a); a.click(); document.body.removeChild(a);
                      URL.revokeObjectURL(url);
                    }
                  }}
                  style={{ ...btnPrimarySmall(), flex: 1, justifyContent: "center", flexDirection: "column", gap: 6, padding: "16px 10px", height: "auto", opacity: sharingImage ? 0.6 : 1 }}
                >
                  <span style={{ fontSize: 22 }}>{sharingImage ? "⏳" : "🖼️"}</span>
                  <span>مشاركة كصورة</span>
                </button>
              </div>
            </div>
          )}

          {listenSetup && (
            <div style={{ position: "absolute", insetInline: 16, bottom: 14, background: "var(--surface)", border: "1px solid var(--accent)", borderRadius: 16, padding: 14, boxShadow: "0 10px 28px rgba(0,0,0,.2)", zIndex: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                <b style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13 }}>🔊 استماع لنطاق من السورة</b>
                <X size={16} color="var(--textDim)" style={{ cursor: "pointer" }} onClick={() => setListenSetup(null)} />
              </div>
              <label style={fieldLabel()}>القارئ
                <select value={listenReciterId} onChange={(e) => setListenReciterId(e.target.value)} style={inputStyle()}>
                  {RECITERS.filter(r => r.edition && !r.surahOnly).map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                </select>
              </label>
              <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                <label style={{ ...fieldLabel(), flex: 1 }}>من الآية
                  <select value={listenSetup.fromAyah} onChange={(e) => setListenSetup({ ...listenSetup, fromAyah: Number(e.target.value), toAyah: Math.max(Number(e.target.value), listenSetup.toAyah) })} style={inputStyle()}>
                    {Array.from({ length: FULL_QURAN.find(s => s.id === listenSetup.item.surahId)?.verses.length || 1 }, (_, i) => i + 1).map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </label>
                <label style={{ ...fieldLabel(), flex: 1 }}>إلى الآية
                  <select value={listenSetup.toAyah} onChange={(e) => setListenSetup({ ...listenSetup, toAyah: Number(e.target.value) })} style={inputStyle()}>
                    {Array.from({ length: FULL_QURAN.find(s => s.id === listenSetup.item.surahId)?.verses.length || 1 }, (_, i) => i + 1).filter(n => n >= listenSetup.fromAyah).map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </label>
              </div>
              <label style={{ ...fieldLabel(), marginTop: 8 }}>سرعة الاستماع
                <select value={listenSpeed} onChange={(e) => setListenSpeed(Number(e.target.value))} style={inputStyle()}>
                  {[0.75, 1, 1.25, 1.5].map(v => <option key={v} value={v}>{v}×</option>)}
                </select>
              </label>
              <button onClick={() => { startListenRange(listenSetup.item, listenSetup.fromAyah, listenSetup.toAyah, listenReciterId, listenSpeed); setListenSetup(null); }} style={{ ...btnPrimarySmall(), width: "100%", marginTop: 10 }}>ابدأ الاستماع</button>
            </div>
          )}

          {listenPanel && (
            <div style={{ position: "absolute", insetInline: 16, bottom: 14, background: "var(--surface)", border: "1px solid var(--primary)", borderRadius: 14, padding: 12, boxShadow: "0 8px 24px rgba(0,0,0,.18)", zIndex: 7 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <b style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5 }}>🔊 استماع — آية {listenPanel.cursorGlobal - FULL_QURAN.find(s => s.id === listenPanel.item.surahId).g0 + 1}</b>
                <button onClick={stopListenRange} style={{ ...btnGhost(), padding: "5px 9px", fontSize: 11 }}>إيقاف</button>
              </div>
              <div style={{ fontSize: 11, color: "var(--textDim)", marginTop: 5 }}>{listenPanel.done ? "انتهى النطاق." : listenPanel.error || `حتى الآية ${listenPanel.toAyah}`}</div>
            </div>
          )}

          {repeatSetup && (
            <div style={{ position: "absolute", insetInline: 16, bottom: 14, background: "var(--surface)", border: "1px solid var(--accent)", borderRadius: 16, padding: 14, boxShadow: "0 10px 28px rgba(0,0,0,.2)", zIndex: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                <b style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13 }}>🔁 تكرار الآيات</b>
                <X size={16} color="var(--textDim)" style={{ cursor: "pointer" }} onClick={() => setRepeatSetup(null)} />
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <label style={{ ...fieldLabel(), flex: 1 }}>من الآية
                  <select value={repeatSetup.fromAyah} onChange={(e) => setRepeatSetup({ ...repeatSetup, fromAyah: Number(e.target.value), toAyah: Math.max(Number(e.target.value), repeatSetup.toAyah) })} style={inputStyle()}>
                    {Array.from({ length: FULL_QURAN.find(s => s.id === repeatSetup.item.surahId)?.verses.length || 1 }, (_, i) => i + 1).map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </label>
                <label style={{ ...fieldLabel(), flex: 1 }}>إلى الآية
                  <select value={repeatSetup.toAyah} onChange={(e) => setRepeatSetup({ ...repeatSetup, toAyah: Number(e.target.value) })} style={inputStyle()}>
                    {Array.from({ length: FULL_QURAN.find(s => s.id === repeatSetup.item.surahId)?.verses.length || 1 }, (_, i) => i + 1).filter(n => n >= repeatSetup.fromAyah).map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </label>
              </div>
              <label style={{ ...fieldLabel(), marginTop: 8 }}>القارئ
                <select value={repeatReciterId} onChange={(e) => setRepeatReciterId(e.target.value)} style={inputStyle()}>
                  {RECITERS.filter(r => r.edition && !r.surahOnly).map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                </select>
              </label>
              <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                <label style={{ ...fieldLabel(), flex: 1 }}>عدد التكرار
                  <input type="number" min="1" max="100" value={repeatSetup.count} onChange={(e) => setRepeatSetup({ ...repeatSetup, count: Math.max(1, Math.min(100, Number(e.target.value) || 1)) })} style={inputStyle()} />
                </label>
                <label style={{ ...fieldLabel(), flex: 1 }}>السرعة
                  <select value={repeatSetup.speed} onChange={(e) => setRepeatSetup({ ...repeatSetup, speed: Number(e.target.value) })} style={inputStyle()}>
                    {[0.75, 1, 1.25, 1.5].map(v => <option key={v} value={v}>{v}×</option>)}
                  </select>
                </label>
              </div>
              <button onClick={() => {
                const s = FULL_QURAN.find(x => x.id === repeatSetup.item.surahId);
                const panel = { item: repeatSetup.item, mode: "range", loopsLeft: repeatSetup.count, cursorGlobal: s.g0 + repeatSetup.fromAyah - 1, rangeStartGlobal: s.g0 + repeatSetup.fromAyah - 1, rangeEndGlobal: s.g0 + repeatSetup.toAyah - 1, playing: true, error: null, speed: repeatSetup.speed, reciterId: repeatReciterId };
                setAyahMenu(null); setRepeatPanel(panel); setRepeatSetup(null);
                setTimeout(() => playRepeatStep(panel), 0);
              }} style={{ ...btnPrimarySmall(), width: "100%", marginTop: 10 }}>ابدأ التكرار</button>
            </div>
          )}

          {repeatPanel && (
            <div style={{
              position: "absolute", insetInline: 16, bottom: 14, background: "var(--surface)", border: "1px solid var(--primary)",
              borderRadius: 14, padding: "12px 14px", boxShadow: "0 8px 24px rgba(0,0,0,0.18)", zIndex: 6,
            }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: "var(--text)" }}>
                  🔁 آية {repeatPanel.item.localIndex + 1} — {repeatPanel.item.surahName}
                </span>
                <X size={16} color="var(--textDim)" style={{ cursor: "pointer" }} onClick={stopRepeat} />
              </div>
              <div>
                {repeatPanel.error ? (
                  <p style={{ fontSize: 12.5, color: "var(--danger)" }}>{repeatPanel.error}</p>
                ) : (
                  <p style={{ fontSize: 12.5, color: "var(--textDim)" }}>
                    {repeatPanel.playing
                      ? (repeatPanel.mode === "single" ? `متبقّي ${repeatPanel.loopsLeft} تكرار...` : `جارٍ تكرار النطاق — متبقّي ${repeatPanel.loopsLeft} لفّة...`)
                      : "انتهى التكرار."}
                  </p>
                )}
              </div>
              <button onClick={stopRepeat} style={{ ...btnGhost(), marginTop: 8, padding: "6px 12px", fontSize: 12.5 }}>إغلاق</button>
            </div>
          )}
        </div>
        {prefs.tajweedColoringEnabled && (
          <div style={{
            display: "flex", alignItems: "center", gap: 8, overflowX: "auto", whiteSpace: "nowrap",
            margin: "6px 2px 0", padding: "4px 6px", borderTop: `1px solid ${nightMode ? "#2a2718" : "var(--border)"}`,
            scrollbarWidth: "none",
          }}>
            {TAJWEED_LEGEND.map((l, i) => (
              <span key={i} style={{ display: "inline-flex", alignItems: "center", gap: 3, flexShrink: 0 }}>
                <span style={{ width: 6, height: 6, borderRadius: "50%", background: l.color, flexShrink: 0 }} />
                <span style={{ fontSize: 8.5, fontWeight: 400, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>{l.short}</span>
              </span>
            ))}
          </div>
        )}
        <div style={{ display: "flex", justifyContent: "center", alignItems: "center", gap: 10, marginTop: prefs.tajweedColoringEnabled ? 6 : -14, position: "relative", zIndex: 2 }}>
          <button onClick={() => changeMushafPage("prev")} disabled={mushafPage <= 1} aria-label="الصفحة السابقة" style={{ ...circleBtn(), width: 30, height: 30, opacity: mushafPage <= 1 ? 0.35 : 1 }}><ChevronRight size={16} /></button>
          <span style={{
            background: nightMode ? "#1a160e" : "var(--accentSoft)", border: `1px solid ${nightMode ? "#3a3627" : "var(--accent)"}`,
            borderRadius: "50%", width: 30, height: 30, display: "flex", alignItems: "center", justifyContent: "center",
            fontFamily: "'Reem Kufi', sans-serif", fontSize: 11.5, color: nightMode ? "#C9A66B" : "var(--accent)",
            boxShadow: "0 2px 6px rgba(0,0,0,0.12)",
          }}>
            {mushafPage}
          </span>
          <button onClick={() => changeMushafPage("next")} disabled={mushafPage >= 604} aria-label="الصفحة التالية" style={{ ...circleBtn(), width: 30, height: 30, opacity: mushafPage >= 604 ? 0.35 : 1 }}><ChevronLeft size={16} /></button>
        </div>
        <p style={{ textAlign: "center", fontSize: 11, color: "var(--textDim)", marginTop: 8, fontFamily: "'Cairo', sans-serif" }}>
          {g(prefs.gender, "اضغطي على رقم الآية لفتح الخيارات الدائرية. استخدمي السهمين أو اسحبي لتقليب الصفحة.", "اضغطي على رقم الآية لفتح الخيارات الدائرية. استخدمي السهمين أو اسحبي لتقليب الصفحة.")}
        </p>

        <div style={{ display: "flex", gap: 10, marginTop: 16, flexWrap: "wrap" }}>
          <button onClick={() => audio.toggle({ id: firstItemSurahId, name: surahForGlobal(pgStart).name })} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}>
            {audioSurahOnPage ? <Pause size={15} /> : <Play size={15} />} {audioSurahOnPage ? "إيقاف" : "استماع"}
          </button>
          <button onClick={() => {
            const hiddenOnPage = pageItems.filter((item) => hiddenAyahs[item.globalNumber]);
            if (hiddenOnPage.length) {
              const next = { ...hiddenAyahs };
              hiddenOnPage.forEach((item) => delete next[item.globalNumber]);
              setHiddenAyahs(next); saveHiddenAyahs(next);
            } else {
              setHideSetup({ item: pageItems[0], fromAyah: pageItems[0]?.localIndex + 1 || 1, toAyah: pageItems[0]?.localIndex + 1 || 1 });
            }
          }} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}>
            <EyeOff size={15} strokeWidth={1.75} /> {pageItems.some((item) => hiddenAyahs[item.globalNumber]) ? "إظهار آيات الصفحة" : "إخفاء الآيات"}
          </button>
          <button
            onClick={() => (recitationRange ? stopRecitation() : setRecitationSetup({ surahId: firstItemSurahId, fromAyah: pageItems[0] ? pageItems[0].localIndex + 1 : 1, toAyah: pageItems[0] ? pageItems[0].localIndex + 1 : 1 }))}
            style={recitationRange ? { ...btnPrimarySmall(), flex: 1 } : { ...btnGhost(), flex: 1, justifyContent: "center" }}
          >
            <Mic size={15} /> {recitationRange ? "إنهاء التسميع" : "🎙️ تسميع من الصفحة"}
          </button>
          <button onClick={markPageRead} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}><Bookmark size={15} /> علّم كمقروء</button>
        </div>

        {recitationSetup && (
          <Card style={{ padding: 16, marginTop: 14 }}>
            <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, fontWeight: 700, color: "var(--text)", marginBottom: 10 }}>🎙️ اختاري نطاق التسميع</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              <label style={fieldLabel()}>السورة
                <select
                  value={recitationSetup.surahId}
                  onChange={(e) => { const sid = Number(e.target.value); setRecitationSetup({ surahId: sid, fromAyah: 1, toAyah: 1 }); }}
                  style={inputStyle()}
                >
                  {FULL_QURAN.map((s) => <option key={s.id} value={s.id}>سورة {s.name}</option>)}
                </select>
              </label>
              <div style={{ display: "flex", gap: 10 }}>
                <label style={{ ...fieldLabel(), flex: 1 }}>من الآية
                  <select value={recitationSetup.fromAyah} onChange={(e) => setRecitationSetup({ ...recitationSetup, fromAyah: Number(e.target.value), toAyah: Math.max(Number(e.target.value), recitationSetup.toAyah) })} style={inputStyle()}>
                    {Array.from({ length: FULL_QURAN.find((s) => s.id === recitationSetup.surahId)?.verses.length || 1 }, (_, i) => i + 1).map((n) => <option key={n} value={n}>{n}</option>)}
                  </select>
                </label>
                <label style={{ ...fieldLabel(), flex: 1 }}>إلى الآية
                  <select value={recitationSetup.toAyah} onChange={(e) => setRecitationSetup({ ...recitationSetup, toAyah: Number(e.target.value) })} style={inputStyle()}>
                    {Array.from({ length: FULL_QURAN.find((s) => s.id === recitationSetup.surahId)?.verses.length || 1 }, (_, i) => i + 1).filter((n) => n >= recitationSetup.fromAyah).map((n) => <option key={n} value={n}>{n}</option>)}
                  </select>
                </label>
              </div>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <button onClick={() => setRecitationSetup({ ...recitationSetup, toAyah: FULL_QURAN.find((s) => s.id === recitationSetup.surahId)?.verses.length || recitationSetup.toAyah })} style={{ ...btnGhost(), padding: "6px 12px", fontSize: 11.5 }}>
                  حتى نهاية السورة
                </button>
              </div>
              <label style={fieldLabel()}>مستوى التسميع
                <div style={{ display: "flex", gap: 6, marginTop: 4 }}>
                  {[
                    ["training", "🟢 تدريب"], ["test", "🟡 اختبار"], ["advanced", "🔴 اختبار متقدّم"],
                  ].map(([id, label]) => (
                    <button
                      key={id} type="button"
                      onClick={() => setRecitationSetup({ ...recitationSetup, level: id })}
                      style={(recitationSetup.level || "training") === id ? { ...btnPrimarySmall(), flex: 1, fontSize: 11.5 } : { ...btnGhost(), flex: 1, justifyContent: "center", fontSize: 11.5 }}
                    >
                      {label}
                    </button>
                  ))}
                </div>
              </label>
              <p style={{ fontSize: 10.5, color: "var(--textDim)", margin: 0, lineHeight: 1.6 }}>
                {(recitationSetup.level || "training") === "training" && "التدريب: تلميحات متاحة بسهولة، ومساعدة أكتر لو اتعطّلتِ."}
                {recitationSetup.level === "test" && "الاختبار: التلميحات محدودة، والخطأ بيتحدد بس من غير حل جاهز فورًا."}
                {recitationSetup.level === "advanced" && "المتقدّم: تقييم صارم، من غير تلميحات، ومحاولات الكلمة الواحدة أقل قبل ما تتخطّى تلقائيًا."}
              </p>
              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={() => setRecitationSetup(null)} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}>إلغاء</button>
                <button onClick={startRecitation} style={{ ...btnPrimarySmall(), flex: 1 }}>ابدئي التسميع</button>
              </div>
            </div>
          </Card>
        )}

        {recitationRange && (
          <Card style={{ padding: 16, marginTop: 14, border: "1.5px solid var(--primary)" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
              <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: "var(--text)" }}>
                🎙️ تسميع سورة {FULL_QURAN.find((s) => s.id === recitationRange.surahId)?.name} — آية {recitationRange.fromAyah + recitation.ayahPos}
              </span>
              <X size={16} color="var(--textDim)" style={{ cursor: "pointer" }} onClick={stopRecitation} />
            </div>
            {recitation.errorMsg && <p style={{ fontSize: 12, color: "var(--danger)", marginBottom: 8 }}>{recitation.errorMsg}</p>}

            {recitation.status !== "completed" && (
              <>
                <div style={{ display: "flex", gap: 6, marginBottom: 10, fontSize: 10.5 }}>
                  <span style={{ display: "flex", alignItems: "center", gap: 3, color: "#1a9c5c" }}>🟢 صحيح</span>
                  <span style={{ display: "flex", alignItems: "center", gap: 3, color: "#d0342c" }}>🔴 خطأ</span>
                  <span style={{ display: "flex", alignItems: "center", gap: 3, color: "#c78a1e" }}>🟡 يحتاج مراجعة</span>
                </div>
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                  {recitation.status === "listening" ? (
                    <button onClick={recitation.pause} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}>⏸ إيقاف مؤقت</button>
                  ) : (
                    <button onClick={recitation.resume} style={{ ...btnPrimarySmall(), flex: 1 }}>🎙️ استكمال</button>
                  )}
                  <button onClick={recitation.retryCurrentAyah} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}>إعادة الآية</button>
                  {recitationRange?.level !== "advanced" && (
                    <button onClick={recitation.useHint} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}>💡 تلميح</button>
                  )}
                </div>
                <p style={{ fontSize: 10, color: "var(--textDim)", marginTop: 10, lineHeight: 1.6 }}>
                  🔒 صوتك بيتحلل لحظيًا من متصفحك مباشرة (خدمة التعرف الصوتي المدمجة فيه) — مفيش تسجيلات بتتخزن جوه أنيسك.
                </p>
              </>
            )}

            {recitation.status === "completed" && (() => {
              const total = recitation.summary.total || 1;
              const accuracy = Math.round((recitation.summary.correct / total) * 100);
              return (
                <div className="anisk-pop">
                  <div style={{ textAlign: "center", marginBottom: 14 }}>
                    <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 36, color: accuracy >= 90 ? "#1a9c5c" : accuracy >= 70 ? "#c78a1e" : "#d0342c" }}>{accuracy}%</div>
                    <div style={{ fontSize: 12, color: "var(--textDim)" }}>نسبة الدقة</div>
                  </div>
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginBottom: 14 }}>
                    <div style={{ textAlign: "center", background: "var(--surfaceAlt)", borderRadius: 10, padding: "8px 4px" }}>
                      <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 18, color: "#1a9c5c" }}>{recitation.summary.correct}</div>
                      <div style={{ fontSize: 10, color: "var(--textDim)" }}>صحيح</div>
                    </div>
                    <div style={{ textAlign: "center", background: "var(--surfaceAlt)", borderRadius: 10, padding: "8px 4px" }}>
                      <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 18, color: "#d0342c" }}>{recitation.summary.wrong}</div>
                      <div style={{ fontSize: 10, color: "var(--textDim)" }}>أخطاء</div>
                    </div>
                    <div style={{ textAlign: "center", background: "var(--surfaceAlt)", borderRadius: 10, padding: "8px 4px" }}>
                      <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 18, color: "#c78a1e" }}>{recitation.summary.skipped}</div>
                      <div style={{ fontSize: 10, color: "var(--textDim)" }}>مُتخطّى</div>
                    </div>
                  </div>

                  {recitationHistory.length > 1 && (
                    <div style={{ marginBottom: 14 }}>
                      <div style={{ fontSize: 11.5, color: "var(--textDim)", marginBottom: 6 }}>محاولاتك في هذه السورة</div>
                      <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                        {recitationHistory.map((h, i) => (
                          <span key={i} style={{ fontSize: 11, background: "var(--surfaceAlt)", borderRadius: 8, padding: "4px 9px", color: "var(--text)" }}>
                            محاولة {i + 1}: {h.accuracy}%
                          </span>
                        ))}
                      </div>
                    </div>
                  )}

                  {recurringMistakes.length > 0 && (
                    <div style={{ marginBottom: 14, padding: 10, background: "var(--accentSoft)", borderRadius: 10 }}>
                      <div style={{ fontSize: 11.5, fontWeight: 700, color: "var(--text)", marginBottom: 6 }}>⚠️ كلمات بتتكرر غلطانة معاكِ</div>
                      <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                        {recurringMistakes.map((m, i) => (
                          <span key={i} style={{ fontFamily: "'Amiri', serif", fontSize: 14, background: "var(--surface)", borderRadius: 8, padding: "4px 10px" }}>{m.word}</span>
                        ))}
                      </div>
                    </div>
                  )}

                  <div style={{ display: "flex", gap: 8 }}>
                    <button
                      onClick={() => { const range = recitationRange; setRecitationRange(null); setTimeout(() => setRecitationSetup(range), 0); }}
                      style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}
                    >
                      🔁 إعادة التسميع
                    </button>
                    <button onClick={stopRecitation} style={{ ...btnPrimarySmall(), flex: 1 }}>إنهاء</button>
                  </div>
                </div>
              );
            })()}
          </Card>
        )}
        {audio.player.errorMsg && (
          <p style={{ textAlign: "center", fontSize: 12, color: "var(--danger)", marginTop: 10, fontFamily: "'Cairo', sans-serif" }}>{audio.player.errorMsg}</p>
        )}
        <p style={{ textAlign: "center", fontSize: 11.5, color: "var(--textDim)", marginTop: 10, fontFamily: "'Cairo', sans-serif" }}>
          {quran.status === "live" ? "الرسم العثماني موافق لمصحف المدينة النبوية (طبعة ١٤٢١هـ) — نص alquran.cloud، وترقيم الصفحات مطابق للمصحف المطبوع القياسي (٦٠٤ صفحة)." : "نص محلي موثّق من جزء عمّ — القرآن كامل يتوفر تلقائيًا عند تشغيل التطبيق خارج بيئة المعاينة."}
        </p>
      </div>
    );
  }

  return (
    <div>
      <SectionTitle right={<button onClick={() => setScreen("reciters")} style={btnGhost()}><ListMusic size={14} /> القارئ</button>}>القرآن</SectionTitle>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 7, padding: 4, background: "var(--surfaceAlt)", borderRadius: 14, marginBottom: 14 }}>
        <button onClick={() => {}} style={{ border: "none", borderRadius: 10, padding: "8px 6px", background: "var(--surface)", color: "var(--primary)", fontFamily: "'Cairo', sans-serif", fontSize: 11.5, fontWeight: 700, boxShadow: "0 1px 5px rgba(0,0,0,.06)" }}>📖 القرآن الكريم</button>
        <button onClick={() => goTo?.("listen")} style={{ border: "none", borderRadius: 10, padding: "8px 6px", background: "transparent", color: "var(--textDim)", fontFamily: "'Cairo', sans-serif", fontSize: 11.5, fontWeight: 600, cursor: "pointer" }}>🎧 الاستماع والراديو</button>
      </div>

      <button onClick={() => setScreen("search")} style={{ ...btnGhost(), width: "100%", justifyContent: "center", marginBottom: 14 }}>
        🔍 ابحثي عن كلمة أو آية في القرآن كله
      </button>

      {readingPosition && (
        <Card
          onClick={() => { setSurahId(readingPosition.surahId); setMushafPage(readingPosition.mushafPage); setScreen("reader"); }}
          style={{ padding: 14, marginBottom: 14, cursor: "pointer", background: "var(--accentSoft)", display: "flex", alignItems: "center", gap: 10 }}
        >
          <Bookmark size={18} color="var(--accent)" style={{ flexShrink: 0 }} />
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: "var(--text)" }}>{g(prefs.gender, "أكمل من حيث توقفت 🤍", "أكملي من حيث توقفتِ 🤍")}</div>
            <div style={{ fontSize: 11.5, color: "var(--textDim)" }}>
              سورة {readingPosition.surahName} · آية {readingPosition.ayahLocalIndex + 1} · صفحة {readingPosition.mushafPage} · جزء {readingPosition.juz}
            </div>
          </div>
          <ChevronLeft size={16} color="var(--textDim)" />
        </Card>
      )}

      <Card style={{ padding: 16, marginBottom: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, color: "var(--text)", fontWeight: 600 }}>وضع القراءة الليلية</div>
            <div style={{ fontSize: 11.5, color: "var(--textDim)" }}>سطوع خافت وراحة للعين ليلًا</div>
          </div>
          <Toggle checked={nightMode} onChange={setNightMode} />
        </div>
        <div style={{ height: 1, background: "var(--border)", margin: "12px 0" }} />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, color: "var(--text)", fontWeight: 600 }}>🖍️ تلوين أحكام التجويد</div>
            <div style={{ fontSize: 11.5, color: "var(--textDim)" }}>يلوّن الحروف حسب أحكام التجويد (مصدر علمي موثّق)</div>
          </div>
          <Toggle checked={prefs.tajweedColoringEnabled} onChange={(v) => updatePrefs({ tajweedColoringEnabled: v })} />
        </div>
        {prefs.tajweedColoringEnabled && (
          <p style={{ fontSize: 11, color: "var(--textDim)", lineHeight: 1.7, margin: "10px 0 0" }}>
            أول مرة تفتحي فيها آية، هيتحمّل ملف الأحكام لسورتها من مصدر خارجي (يحتاج نت أول مرة بس لكل سورة). مفتاح الألوان ظاهر أعلى إطار المصحف، وليس داخله.
            <br /><br />
            عند تفعيل التجويد، تتحول شاشة القراءة تلقائيًا إلى النص العثماني الملوّن داخل إطار المصحف نفسه؛ وعند إيقافه يعود مصحف المدينة بخطه الأصلي.
          </p>
        )}
      </Card>

      {/* تبويبات طرق التصفح */}
      <div style={{ display: "flex", gap: 6, marginBottom: 14, background: "var(--surfaceAlt)", padding: 4, borderRadius: 14 }}>
        {[
          ["surahs", "📖 السور"], ["juz", "🕌 الأجزاء"], ["pages", "📄 الصفحات"], ["bookmarks", "🔖 المحفوظات"],
        ].map(([id, label]) => (
          <button
            key={id}
            onClick={() => setBrowseMode(id)}
            style={{
              flex: 1, padding: "9px 6px", borderRadius: 10, border: "none", cursor: "pointer",
              background: browseMode === id ? "var(--surface)" : "transparent",
              boxShadow: browseMode === id ? "0 1px 4px rgba(0,0,0,0.08)" : "none",
              color: browseMode === id ? "var(--primary)" : "var(--textDim)",
              fontFamily: "'Cairo', sans-serif", fontSize: 11.5, fontWeight: 700,
            }}
          >
            {label}
          </button>
        ))}
      </div>

      {browseMode === "surahs" && (
        <>
          <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="ابحث عن سورة..." style={{ ...inputStyle(), width: "100%", marginBottom: 14 }} />
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {filteredList.map((s) => (
              <Card key={s.id} onClick={() => openSurah(s.id)} style={{ padding: "15px 18px", cursor: "pointer", display: "flex", alignItems: "center", gap: 14 }}>
                <div style={{ width: 40, height: 40, borderRadius: 12, background: "var(--surfaceAlt)", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Reem Kufi', sans-serif", color: "var(--primary)", fontSize: 14, flexShrink: 0 }}>{s.id}</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 16, color: "var(--text)" }}>سورة {s.name}</div>
                  <div style={{ fontSize: 12, color: "var(--textDim)" }}>{s.revelation} · {s.verses} آيات</div>
                </div>
                <ChevronLeft size={18} color="var(--textDim)" />
              </Card>
            ))}
            {filteredList.length === 0 && <EmptyState icon={<BookOpen size={26} />} title="لا توجد نتائج مطابقة" />}
          </div>
        </>
      )}

      {browseMode === "juz" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {Array.from({ length: 30 }, (_, i) => i + 1).map((j) => {
            const startGlobal = JUZ_STARTS[j - 1];
            const s = surahForGlobal(startGlobal);
            return (
              <Card
                key={j}
                onClick={() => { setSurahId(s.id); setMushafPage(mushafPageForGlobal(startGlobal)); setScreen("reader"); }}
                style={{ padding: "13px 16px", cursor: "pointer", display: "flex", alignItems: "center", gap: 12 }}
              >
                <div style={{ width: 36, height: 36, borderRadius: "50%", background: "var(--accentSoft)", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Reem Kufi', sans-serif", color: "var(--accent)", fontSize: 13, flexShrink: 0 }}>{j}</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, fontWeight: 700, color: "var(--text)" }}>الجزء {j}</div>
                  <div style={{ fontSize: 11.5, color: "var(--textDim)" }}>يبدأ من سورة {s.name} · صفحة {mushafPageForGlobal(startGlobal)}</div>
                </div>
                <ChevronLeft size={16} color="var(--textDim)" />
              </Card>
            );
          })}
        </div>
      )}

      {browseMode === "pages" && (
        <div>
          <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
            <input
              value={pageJumpInput}
              onChange={(e) => setPageJumpInput(e.target.value.replace(/[^\d]/g, ""))}
              placeholder="اكتبي رقم صفحة من ١ إلى ٦٠٤"
              style={{ ...inputStyle(), flex: 1 }}
              inputMode="numeric"
            />
            <button
              onClick={() => {
                const n = Math.min(604, Math.max(1, Number(pageJumpInput) || 1));
                const g = mushafPageRange(n)[0];
                setSurahId(surahForGlobal(g).id); setMushafPage(n); setScreen("reader");
              }}
              style={btnPrimarySmall()}
            >
              اذهبي
            </button>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(6, 1fr)", gap: 8 }}>
            {Array.from({ length: 604 }, (_, i) => i + 1).filter((p) => p % 10 === 1 || p === 604).map((p) => (
              <button
                key={p}
                onClick={() => { const g = mushafPageRange(p)[0]; setSurahId(surahForGlobal(g).id); setMushafPage(p); setScreen("reader"); }}
                style={{ ...btnGhost(), justifyContent: "center", padding: "8px 4px", fontSize: 11.5 }}
              >
                {p}
              </button>
            ))}
          </div>
          <p style={{ fontSize: 11, color: "var(--textDim)", marginTop: 10, textAlign: "center" }}>الأرقام دي بداية كل ١٠ صفحات — استخدمي المربع فوق للذهاب لأي صفحة بالظبط.</p>
        </div>
      )}

      {browseMode === "bookmarks" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {markedAyah && (
            <Card style={{ padding: 16 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
                <div onClick={() => { setSurahId(markedAyah.surahId); setMushafPage(mushafPageForGlobal(markedAyah.globalNumber)); setScreen("reader"); }} style={{ cursor: "pointer", flex: 1 }}>
                  <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, fontWeight: 700, color: "var(--accent)", marginBottom: 4, display: "flex", alignItems: "center", gap: 6 }}>
                    <Bookmark size={15} fill="currentColor" /> موضع توقّفكِ
                  </div>
                  <div style={{ fontSize: 12.5, color: "var(--textDim)" }}>
                    سورة {markedAyah.surahName} · آية {markedAyah.localIndex + 1}
                  </div>
                </div>
                <X size={16} color="var(--textDim)" style={{ cursor: "pointer", flexShrink: 0 }} onClick={() => toggleMarkedAyah(markedAyah)} />
              </div>
            </Card>
          )}
          {readingPosition ? (
            <Card
              onClick={() => { setSurahId(readingPosition.surahId); setMushafPage(readingPosition.mushafPage); setScreen("reader"); }}
              style={{ padding: 16, cursor: "pointer" }}
            >
              <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, fontWeight: 700, color: "var(--text)", marginBottom: 4 }}>📖 آخر موضع قراءة</div>
              <div style={{ fontSize: 12.5, color: "var(--textDim)" }}>
                سورة {readingPosition.surahName} · آية {readingPosition.ayahLocalIndex + 1} · صفحة {readingPosition.mushafPage} · جزء {readingPosition.juz}
              </div>
            </Card>
          ) : (
            !markedAyah && Object.keys(ayahTags).length === 0 && <EmptyState icon={<Bookmark size={26} />} title="لسه مفيش موضع قراءة محفوظ — افتحي أي سورة وابدئي القراءة" />
          )}

          {Object.keys(ayahTags).length > 0 && (
            <div style={{ marginTop: 6 }}>
              <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: "var(--text)", margin: "4px 2px 10px" }}>🏷️ آياتي المحفوظة بالعلامات</div>
              {AYAH_TAG_TYPES.map((t) => {
                const items = Object.entries(ayahTags).filter(([, tags]) => tags.includes(t.id)).map(([g]) => Number(g));
                if (!items.length) return null;
                return (
                  <div key={t.id} style={{ marginBottom: 14 }}>
                    <div style={{ fontSize: 12, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif", marginBottom: 6 }}>{t.icon} {t.label} ({items.length})</div>
                    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                      {items.map((g) => {
                        const s = surahForGlobal(g);
                        const localIdx = g - s.g0;
                        return (
                          <Card
                            key={g}
                            onClick={() => { setSurahId(s.id); setMushafPage(mushafPageForGlobal(g)); setScreen("reader"); }}
                            style={{ padding: "10px 14px", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}
                          >
                            <span style={{ fontSize: 12.5, color: "var(--text)", fontFamily: "'Cairo', sans-serif" }}>سورة {s.name} · آية {localIdx + 1}</span>
                            <ChevronLeft size={14} color="var(--textDim)" />
                          </Card>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function TopBarBack({ onBack, title, right }) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
      <button onClick={onBack} style={iconBtn()}><ArrowRight size={18} /></button>
      <h2 style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 17, color: "var(--text)", margin: 0 }}>{title}</h2>
      {right || <div style={{ width: 36 }} />}
    </div>
  );
}
function iconBtn() {
  return { width: 36, height: 36, borderRadius: 12, border: "1px solid var(--border)", background: "var(--surface)", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: "var(--text)" };
}
function pageArrow() {
  return { position: "absolute", top: "50%", transform: "translateY(-50%)", width: 34, height: 34, borderRadius: "50%", border: "1px solid var(--border)", background: "var(--surface)", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: "var(--text)" };
}
function btnPrimarySmall() {
  return { display: "flex", alignItems: "center", gap: 6, justifyContent: "center", padding: "9px 14px", borderRadius: 12, border: "none", background: "var(--primary)", color: "var(--onPrimary)", fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 600, cursor: "pointer" };
}

/* =========================================================================
   Listen Hub — "استماع للشيوخ": browse reciters, stream full-surah audio
   on demand from the official CDN. Nothing is downloaded/stored in bulk;
   each tap opens a live stream, same as any Quran radio/listen website.
   ========================================================================= */

// آيات الرقية الشرعية المعروفة (الفاتحة، آية الكرسي، خواتيم البقرة، المعوذات) — تُشغَّل بصوت القارئ المختار
// كل عنصر بصيغة [رقم السورة, رقم الآية من...إلى]
const RUQYAH_SEQUENCE = [
  { surahId: 1, from: 1, to: 7 },     // الفاتحة كاملة
  { surahId: 2, from: 255, to: 255 }, // آية الكرسي
  { surahId: 2, from: 285, to: 286 }, // خواتيم سورة البقرة
  { surahId: 112, from: 1, to: 4 },   // الإخلاص
  { surahId: 113, from: 1, to: 5 },   // الفلق
  { surahId: 114, from: 1, to: 6 },   // الناس
];
function buildRuqyahGlobalList() {
  const out = [];
  RUQYAH_SEQUENCE.forEach((r) => { for (let n = r.from; n <= r.to; n++) out.push(globalAyahNumberFor(r.surahId, n)); });
  return out;
}

// تحميل صوت السور للاستماع بدون إنترنت — بيستخدم Cache API (نفس التقنية اللي
// بيستخدمها Service Worker) عشان يخزّن الملف الصوتي فعليًا على الجهاز. مختلف عن
// localStorage (سعته صغيرة جدًا ومش مناسبة لملفات صوت) — الـ Cache API مصمَّم
// تحديدًا لتخزين استجابات HTTP كبيرة زي الصوت والفيديو.
const OFFLINE_AUDIO_CACHE = "anisk-offline-audio-v1";
function offlineAudioKey(reciterId, surahId) { return `https://anisk.offline/${reciterId}/${surahId}.mp3`; }
async function isSurahDownloaded(reciterId, surahId) {
  if (typeof caches === "undefined") return false;
  try {
    const cache = await caches.open(OFFLINE_AUDIO_CACHE);
    const match = await cache.match(offlineAudioKey(reciterId, surahId));
    return !!match;
  } catch { return false; }
}
async function downloadSurahOffline(reciterId, surahId, url) {
  if (typeof caches === "undefined") throw new Error("offline-storage-unsupported");
  const res = await fetch(url);
  if (!res.ok) throw new Error("download-failed");
  // نتأكد إن المحتوى اللي هنحفظه فعلًا صوت حقيقي مش استجابة فاضية/تالفة (زي لو
  // الخادم رفض الطلب برد فارغ من غير ما يفشل الطلب نفسه بوضوح) — قبل ما نأكّد
  // للمستخدمة إن التحميل نجح.
  const blob = await res.blob();
  if (!blob || blob.size < 2000) throw new Error("download-invalid");
  const cache = await caches.open(OFFLINE_AUDIO_CACHE);
  await cache.put(offlineAudioKey(reciterId, surahId), new Response(blob, { headers: res.headers }));
}
async function deleteOfflineSurah(reciterId, surahId) {
  if (typeof caches === "undefined") return;
  try {
    const cache = await caches.open(OFFLINE_AUDIO_CACHE);
    await cache.delete(offlineAudioKey(reciterId, surahId));
  } catch { /* تجاهل */ }
}
async function getOfflineSurahUrl(reciterId, surahId) {
  if (typeof caches === "undefined") return null;
  try {
    const cache = await caches.open(OFFLINE_AUDIO_CACHE);
    const match = await cache.match(offlineAudioKey(reciterId, surahId));
    if (!match) return null;
    const blob = await match.blob();
    // لو النسخة المخزّنة فاضية أو تالفة لأي سبب، نتصرّف كأنها مش موجودة أصلًا
    // (بدل ما نرجّع رابط هيفشل وقت التشغيل) — فالكود اللي بينادينا يرجع تلقائيًا
    // للتشغيل من الإنترنت بدل ما يوقف برسالة خطأ.
    if (!blob || blob.size < 2000) {
      await cache.delete(offlineAudioKey(reciterId, surahId));
      return null;
    }
    return URL.createObjectURL(blob);
  } catch { return null; }
}

const LISTEN_SPEEDS = [0.75, 0.9, 1, 1.1, 1.25, 1.5];

// مشغلات الاستماع والراديو معمولة مرة واحدة على مستوى التطبيق كله، مش داخل
// ListenHub. كده لما المستخدمة تنتقل بين التبويبات، المكوّن ممكن يتفك ويتركب
// من جديد لكن الصوت نفسه يفضل شغال.
const ANISK_LISTEN_AUDIO = typeof Audio !== "undefined" ? new Audio() : null;
const ANISK_AYAH_LISTEN_AUDIO = typeof Audio !== "undefined" ? new Audio() : null;
const ANISK_RADIO_AUDIO = typeof Audio !== "undefined" ? new Audio() : null;
if (ANISK_RADIO_AUDIO) ANISK_RADIO_AUDIO.referrerPolicy = "no-referrer";

const ANISK_LISTEN_SESSION = {
  playingSurah: null,
  status: "idle",
  queue: null,
  speed: 1,
  ruqyahIndex: null,
  radioPlaying: false,
  radioStatus: "idle",
  radioSource: "primary",
};

const PLAYLISTS_STORAGE_KEY = "anisk-listen-playlists-v1";

function loadListenPlaylistsSync() {
  try {
    const raw = localStorage.getItem(PLAYLISTS_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length) return parsed;
    }
  } catch {}
  return [
    { id: "sleep", name: "قبل النوم", ids: [] },
    { id: "memorize", name: "الحفظ", ids: [] },
  ];
}

function saveListenPlaylistsSync(playlists) {
  try { localStorage.setItem(PLAYLISTS_STORAGE_KEY, JSON.stringify(playlists)); } catch {}
}

function ListenHub({ quran, prefs, updatePrefs, goTo }) {
  const [reciterId, setReciterId] = useState(prefs.reciter);
  const [playingSurah, setPlayingSurah] = useState(ANISK_LISTEN_SESSION.playingSurah);
  const [status, setStatus] = useState(ANISK_LISTEN_SESSION.status); // idle | loading | playing | paused | error
  const [errorMsg, setErrorMsg] = useState("");
  const [search, setSearch] = useState("");
  const [ruqyahIndex, setRuqyahIndex] = useState(ANISK_LISTEN_SESSION.ruqyahIndex);
  const [radioPlaying, setRadioPlaying] = useState(ANISK_LISTEN_SESSION.radioPlaying);
  const [radioStatus, setRadioStatus] = useState(ANISK_LISTEN_SESSION.radioStatus); // idle | loading | playing | error | offline
  const [radioSource, setRadioSource] = useState(ANISK_LISTEN_SESSION.radioSource); // "primary" | "fallback"
  const [queue, setQueue] = useState(ANISK_LISTEN_SESSION.queue);
  const [speed, setSpeed] = useState(ANISK_LISTEN_SESSION.speed || 1);
  const [rangeFrom, setRangeFrom] = useState(null);
  const [rangeTo, setRangeTo] = useState(null);
  const [playerExpanded, setPlayerExpanded] = useState(false);
  const [playerMode, setPlayerMode] = useState("range"); // "range" | "custom"
  const [downloadedKeys, setDownloadedKeys] = useState(new Set());
  const [downloadingKey, setDownloadingKey] = useState(null);
  const [playlists, setPlaylists] = useState(loadListenPlaylistsSync);
  const [activePlaylistId, setActivePlaylistId] = useState(() => loadListenPlaylistsSync()[0]?.id || null);
  const [newPlaylistName, setNewPlaylistName] = useState("");
  const [customSearch, setCustomSearch] = useState("");
  const [draggedPlaylistIndex, setDraggedPlaylistIndex] = useState(null);
  const radioRef = useRef(ANISK_RADIO_AUDIO);
  const audioRef = useRef(ANISK_LISTEN_AUDIO);
  const ruqyahListRef = useRef(buildRuqyahGlobalList());
  // مرايا (refs) لتفادي مشكلة الـ stale closure جوه onEnded، اللي بيتسجَّل مرة واحدة
  // بس عند تركيب المكوّن (mount) — من غيرها onEnded هيفضل شايف القيم القديمة بس
  const ruqyahIndexRef = useRef(null);
  const queueRef = useRef(null);
  const loadAndPlaySurahRef = useRef(null);
  useEffect(() => { ruqyahIndexRef.current = ruqyahIndex; ANISK_LISTEN_SESSION.ruqyahIndex = ruqyahIndex; }, [ruqyahIndex]);
  useEffect(() => { queueRef.current = queue; ANISK_LISTEN_SESSION.queue = queue; }, [queue]);
  useEffect(() => { ANISK_LISTEN_SESSION.speed = speed; if (audioRef.current && status !== "idle") audioRef.current.playbackRate = speed; }, [speed, status]); // eslint-disable-line
  useEffect(() => { saveListenPlaylistsSync(playlists); }, [playlists]);

  const activePlaylist = playlists.find((p) => p.id === activePlaylistId) || playlists[0] || null;
  const customList = activePlaylist?.ids || [];

  const addPlaylist = () => {
    const name = newPlaylistName.trim();
    if (!name) return;
    const id = `playlist-${Date.now()}`;
    setPlaylists((prev) => [...prev, { id, name, ids: [] }]);
    setActivePlaylistId(id);
    setNewPlaylistName("");
  };
  const renameActivePlaylist = () => {
    if (!activePlaylist) return;
    const name = window.prompt("اسم القائمة الجديدة:", activePlaylist.name);
    if (!name?.trim()) return;
    setPlaylists((prev) => prev.map((p) => p.id === activePlaylist.id ? { ...p, name: name.trim() } : p));
  };
  const deleteActivePlaylist = () => {
    if (!activePlaylist || playlists.length <= 1) return;
    if (!window.confirm(`حذف قائمة «${activePlaylist.name}»؟`)) return;
    const next = playlists.filter((p) => p.id !== activePlaylist.id);
    setPlaylists(next);
    setActivePlaylistId(next[0]?.id || null);
  };
  const updateActivePlaylistIds = (ids) => {
    if (!activePlaylist) return;
    setPlaylists((prev) => prev.map((p) => p.id === activePlaylist.id ? { ...p, ids } : p));
  };
  const addToActivePlaylist = (id) => {
    if (!activePlaylist || activePlaylist.ids.includes(id)) return;
    updateActivePlaylistIds([...activePlaylist.ids, id]);
  };
  const removeFromActivePlaylist = (index) => {
    if (!activePlaylist) return;
    updateActivePlaylistIds(activePlaylist.ids.filter((_, i) => i !== index));
  };
  const movePlaylistItem = (from, to) => {
    if (!activePlaylist || from === to || to < 0 || to >= activePlaylist.ids.length) return;
    const ids = [...activePlaylist.ids];
    const [item] = ids.splice(from, 1);
    ids.splice(to, 0, item);
    updateActivePlaylistIds(ids);
  };

  useEffect(() => {
    const el = radioRef.current;
    if (!el) return;
    const onPlay = () => { setRadioStatus("playing"); setRadioPlaying(true); ANISK_LISTEN_SESSION.radioStatus = "playing"; ANISK_LISTEN_SESSION.radioPlaying = true; };
    const onPause = () => { setRadioPlaying(false); ANISK_LISTEN_SESSION.radioPlaying = false; };
    const onError = () => { setRadioStatus("error"); setRadioPlaying(false); ANISK_LISTEN_SESSION.radioStatus = "error"; ANISK_LISTEN_SESSION.radioPlaying = false; };
    el.addEventListener("play", onPlay);
    el.addEventListener("pause", onPause);
    el.addEventListener("error", onError);
    return () => { el.removeEventListener("play", onPlay); el.removeEventListener("pause", onPause); el.removeEventListener("error", onError); };
  }, []);

  useEffect(() => {
    const el = audioRef.current;
    if (!el) return;
    const onPlay = () => { setStatus("playing"); ANISK_LISTEN_SESSION.status = "playing"; };
    const onPause = () => {
      if (!el.ended) { setStatus("paused"); ANISK_LISTEN_SESSION.status = "paused"; }
    };
    const onEnded = () => {
      if (ruqyahIndexRef.current != null) {
        const list = ruqyahListRef.current;
        const next = ruqyahIndexRef.current + 1;
        if (next >= list.length) { setStatus("idle"); setRuqyahIndex(null); ANISK_LISTEN_SESSION.status = "idle"; }
        else setRuqyahIndex(next);
        return;
      }
      const q = queueRef.current;
      if (q) {
        const nextIdx = q.index + 1;
        if (nextIdx >= q.ids.length) { setStatus("idle"); setPlayingSurah(null); setQueue(null); ANISK_LISTEN_SESSION.status = "idle"; ANISK_LISTEN_SESSION.playingSurah = null; return; }
        const nextId = q.ids[nextIdx];
        setQueue({ ...q, index: nextIdx });
        setPlayingSurah(nextId);
        ANISK_LISTEN_SESSION.playingSurah = nextId;
        loadAndPlaySurahRef.current?.(nextId);
        return;
      }
      setStatus("idle"); setPlayingSurah(null); ANISK_LISTEN_SESSION.status = "idle"; ANISK_LISTEN_SESSION.playingSurah = null;
    };
    const onError = () => { setStatus("error"); setErrorMsg("تعذّر تحميل الصوت — تحقّق من الاتصال بالإنترنت."); ANISK_LISTEN_SESSION.status = "error"; };
    el.addEventListener("play", onPlay);
    el.addEventListener("pause", onPause);
    el.addEventListener("ended", onEnded);
    el.addEventListener("error", onError);
    return () => {
      el.removeEventListener("play", onPlay);
      el.removeEventListener("pause", onPause);
      el.removeEventListener("ended", onEnded);
      el.removeEventListener("error", onError);
      // مهم: لا نوقف الصوت هنا. الانتقال بين التبويبات يفك المكوّن فقط.
    };
  }, []);

  // مزامنة الواجهة عند الرجوع لتبويب الاستماع إذا كان الصوت لسه شغالًا.
  useEffect(() => {
    if (ANISK_LISTEN_SESSION.playingSurah != null) {
      setPlayingSurah(ANISK_LISTEN_SESSION.playingSurah);
      setStatus(ANISK_LISTEN_SESSION.status || (audioRef.current?.paused ? "paused" : "playing"));
    }
    setQueue(ANISK_LISTEN_SESSION.queue);
    setSpeed(ANISK_LISTEN_SESSION.speed || 1);
    setRuqyahIndex(ANISK_LISTEN_SESSION.ruqyahIndex);
    setRadioPlaying(ANISK_LISTEN_SESSION.radioPlaying);
    setRadioStatus(ANISK_LISTEN_SESSION.radioStatus);
    setRadioSource(ANISK_LISTEN_SESSION.radioSource);
  }, []);

  // مشغلات الاستماع والراديو مشتركة على مستوى التطبيق؛ لا يتم إنشاء Audio جديد
  // ولا إيقافه عند unmount.
  useEffect(() => {
    const el = radioRef.current;
    if (el) el.referrerPolicy = "no-referrer";
  }, []);

  // البث بيروح عبر /api/radio (سيرفر Vercel نفسه) — الملف /api/radio.js هو اللي
  // بيجيب البث من المصدر الحقيقي ويوصّله للمستخدم بدون أي حجب من مزودي البث.
  const RADIO_URLS = [
    "/api/radio",                               // البروكسي (الأولوية دايماً على Vercel)
    "https://backup.qurango.net/radio/cairo",   // احتياطي مباشر لو البروكسي فشل
    "https://backup.qurango.net/radio/mix",     // احتياطي ثاني
    "https://stream.radiojar.com/8s5u5tpdtwzuv", // احتياطي أخير
  ];

  const toggleRadio = (forceSource) => {
    if (radioPlaying && !forceSource) { radioRef.current.pause(); setRadioPlaying(false); setRadioStatus("idle"); ANISK_LISTEN_SESSION.radioPlaying = false; ANISK_LISTEN_SESSION.radioStatus = "idle"; return; }
    audioRef.current?.pause();
    radioRef.current?.pause();
    setRadioStatus("loading");
    setRadioPlaying(false);
    ANISK_LISTEN_SESSION.radioStatus = "loading";
    ANISK_LISTEN_SESSION.radioPlaying = false;

    const el = radioRef.current;
    // نجرّب الروابط واحد بعد واحد — لو رابط فشل أو ما بدأش في ٦ ثواني ننتقل للتالي
    const tryNext = (index) => {
      if (index >= RADIO_URLS.length) {
        setRadioStatus("error"); setRadioPlaying(false);
        ANISK_LISTEN_SESSION.radioStatus = "error"; ANISK_LISTEN_SESSION.radioPlaying = false;
        return;
      }
      const url = RADIO_URLS[index];
      setRadioSource(index === 0 ? "primary" : "fallback");
      ANISK_LISTEN_SESSION.radioSource = index === 0 ? "primary" : "fallback";
      let settled = false;
      let timer = null;
      el.onerror = null;
      const cleanup = () => { clearTimeout(timer); el.removeEventListener("playing", onPlaying); };
      const onPlaying = () => {
        if (settled) return;
        settled = true; cleanup();
        setRadioPlaying(true); setRadioStatus("idle");
        ANISK_LISTEN_SESSION.radioPlaying = true; ANISK_LISTEN_SESSION.radioStatus = "playing";
      };
      el.addEventListener("playing", onPlaying);
      el.src = url;
      el.play().catch(() => { if (settled) return; settled = true; cleanup(); tryNext(index + 1); });
      timer = setTimeout(() => { if (settled) return; settled = true; cleanup(); el.pause(); tryNext(index + 1); }, 6000);
    };
    tryNext(0);
  };

  useEffect(() => {
    const el = new Audio();
    audioRef.current = el;
    const onPlay = () => setStatus("playing");
    const onEnded = () => {
      // أولوية للرقية الشرعية لو شغالة (نفس السلوك الأصلي)
      if (ruqyahIndexRef.current != null) {
        const list = ruqyahListRef.current;
        const next = ruqyahIndexRef.current + 1;
        if (next >= list.length) { setStatus("idle"); setRuqyahIndex(null); }
        else setRuqyahIndex(next);
        return;
      }
      // بعدها: تشغيل متسلسل لقائمة سور (من سورة → إلى سورة) لو مفعّلة
      const q = queueRef.current;
      if (q) {
        const nextIdx = q.index + 1;
        if (nextIdx >= q.ids.length) { setStatus("idle"); setPlayingSurah(null); setQueue(null); return; }
        const nextId = q.ids[nextIdx];
        setQueue({ ...q, index: nextIdx });
        loadAndPlaySurahRef.current?.(nextId);
        return;
      }
      setStatus("idle"); setPlayingSurah(null);
    };
    const onError = () => { setStatus("error"); setErrorMsg("تعذّر تحميل الصوت — تحقّق من الاتصال بالإنترنت."); };
    el.addEventListener("play", onPlay);
    el.addEventListener("ended", onEnded);
    el.addEventListener("error", onError);
    return () => {
      el.removeEventListener("play", onPlay);
      el.removeEventListener("ended", onEnded);
      el.removeEventListener("error", onError);
      el.pause();
    };
  }, []);

  const reciter = RECITERS.find((r) => r.id === reciterId);
  // قائمة السور المتاحة فعليًا بصوت القارئ الحالي (بعض القراء عندهم مجموعة محدودة فقط)
  const scopedList = reciter?.limitedSurahs ? quran.list.filter((s) => reciter.limitedSurahs.includes(s.id)) : quran.list;

  // كل ما تتغيّر القارئة، نفحص أي سور محمّلة بصوتها فعليًا (Cache API) عشان نعرض
  // علامة "محمّلة" الصح على القائمة
  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (typeof caches === "undefined") return;
      try {
        const cache = await caches.open(OFFLINE_AUDIO_CACHE);
        const keys = await cache.keys();
        if (cancelled) return;
        const prefix = `https://anisk.offline/${reciter.id}/`;
        const found = new Set();
        keys.forEach((req) => {
          if (req.url.startsWith(prefix)) {
            const surahId = Number(req.url.slice(prefix.length).replace(".mp3", ""));
            found.add(surahId);
          }
        });
        setDownloadedKeys(found);
      } catch { /* تجاهل */ }
    })();
    return () => { cancelled = true; };
  }, [reciter.id]);

  const downloadSurah = async (surahId) => {
    if (typeof caches === "undefined" || (typeof window !== "undefined" && !window.isSecureContext)) {
      setErrorMsg("التحميل للاستماع بدون نت محتاج سياقًا آمنًا (HTTPS) — مش هيشتغل من رابط IP محلي زي 192.168.x.x. جرّبي من الموقع بعد رفعه على Vercel، أو من http://localhost أثناء التطوير.");
      return;
    }
    setDownloadingKey(surahId);
    try {
      const url = reciter.archiveBase ? archiveSurahUrl(reciter.archiveBase, surahId)
        : reciter.mp3q ? mp3QuranSurahUrl(reciter.mp3q, surahId) : surahAudioUrl(reciter.edition, surahId);
      await downloadSurahOffline(reciter.id, surahId, url);
      setDownloadedKeys((prev) => new Set(prev).add(surahId));
    } catch {
      setErrorMsg("تعذّر تحميل السورة — تأكدي من اتصال الإنترنت وحاولي تاني.");
    }
    setDownloadingKey(null);
  };
  const removeDownload = async (surahId) => {
    await deleteOfflineSurah(reciter.id, surahId);
    setDownloadedKeys((prev) => { const next = new Set(prev); next.delete(surahId); return next; });
  };

  // تشغيل تسلسل آيات الرقية آية آية عند تقدّم ruqyahIndex
  useEffect(() => {
    if (ruqyahIndex == null || !audioRef.current) return;
    if (!reciter?.edition || reciter.surahOnly) { setStatus("error"); setErrorMsg("هذا القارئ لا يدعم تشغيل آية بعينها — اختر قارئًا آخر لتشغيل الرقية."); setRuqyahIndex(null); return; }
    const g = ruqyahListRef.current[ruqyahIndex];
    setPlayingSurah(null);
    setStatus("loading");
    audioRef.current.src = ayahAudioUrl(reciter.edition, g);
    audioRef.current.play().catch(() => { setStatus("error"); setErrorMsg("تعذّر تشغيل الصوت."); });
  }, [ruqyahIndex]); // eslint-disable-line

  const playRuqyah = () => {
    setErrorMsg("");
    if (ruqyahIndex != null) { audioRef.current.pause(); setStatus("idle"); setRuqyahIndex(null); return; }
    radioRef.current?.pause(); setRadioPlaying(false);
    if (!reciter?.edition || reciter.surahOnly) { setStatus("error"); setErrorMsg("اختر قارئًا يدعم الاستماع آيةً آيةً (غير محمود علي البنا) لتشغيل الرقية."); return; }
    setRuqyahIndex(0);
  };

  // تحميل سورة جديدة من الصفر والتشغيل مباشرة (تُستخدم من playSurah ومن التقدّم
  // التلقائي جوه قائمة الاستماع المتسلسلة "من سورة إلى سورة")
  const loadAndPlaySurah = async (surahId) => {
    setPlayingSurah(surahId);
    setStatus("loading");
    ANISK_LISTEN_SESSION.playingSurah = surahId;
    ANISK_LISTEN_SESSION.status = "loading";

    const playFromNetwork = () => {
      const primaryUrl = reciter.archiveBase ? archiveSurahUrl(reciter.archiveBase, surahId)
        : reciter.mp3q ? mp3QuranSurahUrl(reciter.mp3q, surahId) : surahAudioUrl(reciter.edition, surahId);
      const fallbackUrl = reciter.mp3q && reciter.edition ? surahAudioUrl(reciter.edition, surahId) : null;
      audioRef.current.src = primaryUrl;
      audioRef.current.playbackRate = speed;
      audioRef.current.onerror = null;
      if (fallbackUrl) {
        audioRef.current.onerror = () => {
          audioRef.current.onerror = null;
          audioRef.current.src = fallbackUrl;
          audioRef.current.playbackRate = speed;
          audioRef.current.play().catch(() => { setStatus("error"); setErrorMsg("تعذّر تشغيل الصوت من أي مصدر."); });
        };
      }
      audioRef.current.play().catch(() => {
        if (fallbackUrl) {
          audioRef.current.src = fallbackUrl;
          audioRef.current.playbackRate = speed;
          audioRef.current.play().catch(() => { setStatus("error"); setErrorMsg("تعذّر تشغيل الصوت من أي مصدر."); });
        } else {
          setStatus("error"); setErrorMsg("تعذّر تشغيل الصوت.");
        }
      });
    };

    // لو السورة محمّلة مسبقًا للاستماع بدون نت، نشغّلها من النسخة المحلية المخزّنة
    // فورًا — من غير أي طلب شبكة خالص، فتشتغل حتى لو الإنترنت مقطوع تمامًا. ولو
    // النسخة المحلية فشلت لأي سبب (نادر بعد التحقق من صحتها وقت التحميل)، نرجع
    // تلقائيًا للتشغيل من الإنترنت بدل ما نوقف برسالة خطأ نهائية.
    const offlineUrl = await getOfflineSurahUrl(reciter.id, surahId);
    if (offlineUrl) {
      audioRef.current.src = offlineUrl;
      audioRef.current.playbackRate = speed;
      audioRef.current.onerror = () => {
        audioRef.current.onerror = null;
        URL.revokeObjectURL(offlineUrl);
        playFromNetwork();
      };
      audioRef.current.play().catch(() => {
        URL.revokeObjectURL(offlineUrl);
        playFromNetwork();
      });
      return;
    }
    // نجرّب مصدر mp3quran.net الموثّق أولًا لو متاح لهذا القارئ، وإلا نرجع لمصدر islamic.network
    playFromNetwork();
  };
  loadAndPlaySurahRef.current = loadAndPlaySurah;

  const playSurah = (surahId) => {
    setErrorMsg("");
    setRuqyahIndex(null);
    setQueue(null); // النقر المباشر على سورة بيلغي أي قائمة استماع متسلسلة كانت شغالة
    ANISK_LISTEN_SESSION.queue = null;
    radioRef.current?.pause(); setRadioPlaying(false); // إيقاف الإذاعة المباشرة لو شغالة
    if (!reciter?.edition && !reciter?.mp3q && !reciter?.archiveBase) { setStatus("error"); setErrorMsg("لا يتوفر صوت لهذا القارئ حاليًا — جرّب قارئًا آخر."); return; }
    if (playingSurah === surahId) {
      if (status === "playing") { audioRef.current.pause(); setStatus("paused"); return; }
      if (status === "paused") {
        // استكمال من نفس المكان بدون إعادة تحميل المصدر — أهم فرق عن السلوك القديم
        audioRef.current.play().catch(() => { setStatus("error"); setErrorMsg("تعذّر استكمال التشغيل."); });
        return;
      }
    }
    loadAndPlaySurah(surahId);
  };

  const restartFromBeginning = () => {
    if (queue) {
      setQueue({ ...queue, index: 0 });
      loadAndPlaySurah(queue.ids[0]);
      return;
    }
    if (playingSurah != null && audioRef.current) {
      audioRef.current.currentTime = 0;
      audioRef.current.play().catch(() => {});
      setStatus("playing");
    }
  };

  const startRangeQueue = (fromId, toId) => {
    const ids = scopedList.map((s) => s.id);
    const i0 = ids.indexOf(fromId), i1 = ids.indexOf(toId);
    if (i0 === -1 || i1 === -1) return;
    const [lo, hi] = i0 <= i1 ? [i0, i1] : [i1, i0];
    const rangeIds = ids.slice(lo, hi + 1);
    if (!rangeIds.length) return;
    setErrorMsg("");
    setRuqyahIndex(null);
    radioRef.current?.pause(); setRadioPlaying(false);
    setQueue({ ids: rangeIds, index: 0 });
    ANISK_LISTEN_SESSION.queue = { ids: rangeIds, index: 0 };
    loadAndPlaySurah(rangeIds[0]);
  };

  const startCustomQueue = () => {
    if (!customList.length) return;
    setErrorMsg("");
    setRuqyahIndex(null);
    radioRef.current?.pause(); setRadioPlaying(false);
    setQueue({ ids: customList, index: 0 });
    ANISK_LISTEN_SESSION.queue = { ids: customList, index: 0 };
    loadAndPlaySurah(customList[0]);
  };

  const filteredList = search.trim()
    ? scopedList.filter((s) => s.name.includes(search.trim()) || String(s.id) === search.trim())
    : scopedList;

  return (
    <div>
      <SectionTitle>🎙️ استماع للشيوخ</SectionTitle>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 7, padding: 4, background: "var(--surfaceAlt)", borderRadius: 14, marginBottom: 14 }}>
        <button onClick={() => goTo?.("quran")} style={{ border: "none", borderRadius: 10, padding: "8px 6px", background: "transparent", color: "var(--textDim)", fontFamily: "'Cairo', sans-serif", fontSize: 11.5, fontWeight: 600, cursor: "pointer" }}>📖 القرآن الكريم</button>
        <button onClick={() => {}} style={{ border: "none", borderRadius: 10, padding: "8px 6px", background: "var(--surface)", color: "var(--primary)", fontFamily: "'Cairo', sans-serif", fontSize: 11.5, fontWeight: 700, boxShadow: "0 1px 5px rgba(0,0,0,.06)" }}>🎧 الاستماع والراديو</button>
      </div>

      <div style={{ display: "flex", gap: 8, overflowX: "auto", paddingBottom: 4, marginBottom: 16 }}>
        {RECITERS.map((r) => (
          <button
            key={r.id}
            onClick={() => { setReciterId(r.id); updatePrefs({ reciter: r.id }); }}
            style={{
              flexShrink: 0, padding: "9px 16px", borderRadius: 999, whiteSpace: "nowrap",
              border: `1px solid ${reciterId === r.id ? "transparent" : "var(--border)"}`,
              background: reciterId === r.id ? "var(--primary)" : "var(--surface)",
              color: reciterId === r.id ? "var(--onPrimary)" : "var(--textDim)",
              fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 600, cursor: "pointer",
            }}
          >
            {r.name.replace("الشيخ ", "")}
          </button>
        ))}
      </div>

      {!reciter?.edition && !reciter?.mp3q && !reciter?.archiveBase && (
        <Card style={{ padding: 14, marginBottom: 14, display: "flex", gap: 8, alignItems: "flex-start" }}>
          <Info size={15} color="var(--textDim)" style={{ marginTop: 2, flexShrink: 0 }} />
          <span style={{ fontSize: 12, color: "var(--textDim)", lineHeight: 1.7 }}>لا يتوفر بث صوتي لهذا القارئ في المصدر الحالي — جرّبي العفاسي أو الحصري أو السديس أو المعيقلي (مؤكَّد شغالين).</span>
        </Card>
      )}

      {reciter?.limitedSurahs && (
        <Card style={{ padding: 14, marginBottom: 14, display: "flex", gap: 8, alignItems: "flex-start" }}>
          <Info size={15} color="var(--textDim)" style={{ marginTop: 2, flexShrink: 0 }} />
          <span style={{ fontSize: 12, color: "var(--textDim)", lineHeight: 1.7 }}>هذا القارئ لسه ما سجّلش المصحف كاملًا — التلاوات المتاحة بصوته محصورة في السور الظاهرة تحت فقط.</span>
        </Card>
      )}

      <Card style={{ position: "sticky", bottom: 8, zIndex: 5, padding: "10px 12px", marginBottom: 14, boxShadow: "0 8px 24px rgba(0,0,0,0.2)" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <button
            onClick={() => {
              if (playingSurah != null) { playSurah(playingSurah); return; }
              if (playerMode === "custom") { startCustomQueue(); return; }
              const f = rangeFrom ?? scopedList[0]?.id;
              const t = rangeTo ?? f;
              if (f != null) startRangeQueue(f, t);
            }}
            style={{
              width: 36, height: 36, borderRadius: "50%", border: "none", cursor: "pointer", flexShrink: 0,
              background: "var(--primary)", color: "var(--onPrimary)",
              display: "flex", alignItems: "center", justifyContent: "center",
            }}
          >
            {status === "loading" && playingSurah != null ? <Gauge size={16} /> : status === "playing" ? <Pause size={16} /> : <Play size={16} />}
          </button>

          <div onClick={() => setPlayerExpanded((v) => !v)} style={{ flex: 1, minWidth: 0, cursor: "pointer" }}>
            <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5, fontWeight: 700, color: "var(--text)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
              {playingSurah != null ? (() => { const s = quran.list.find((x) => x.id === playingSurah); return s ? `سورة ${s.name}` : "مشغل الاستماع"; })() : "🎧 مشغل الاستماع"}
            </div>
            {(queue || playingSurah != null) && (
              <div style={{ fontSize: 10.5, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>
                {queue ? `(${queue.index + 1} من ${queue.ids.length}) · ` : ""}{speed}×
              </div>
            )}
          </div>

          <button onClick={restartFromBeginning} title="إعادة من البداية" style={{ ...iconBtn(), width: 28, height: 28, flexShrink: 0 }}>
            <SkipBack size={13} />
          </button>
          <button onClick={() => setPlayerExpanded((v) => !v)} style={{ ...iconBtn(), width: 28, height: 28, flexShrink: 0 }}>
            <ChevronDown size={14} style={{ transform: playerExpanded ? "rotate(180deg)" : "none", transition: "transform .2s" }} />
          </button>
        </div>

        {playerExpanded && (
          <div style={{ marginTop: 10, paddingTop: 10, borderTop: "1px solid var(--border)" }}>
            <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
              <button
                onClick={() => setPlayerMode("range")}
                style={{
                  flex: 1, padding: "6px 8px", borderRadius: 10, cursor: "pointer",
                  border: `1px solid ${playerMode === "range" ? "transparent" : "var(--border)"}`,
                  background: playerMode === "range" ? "var(--primary)" : "var(--surface)",
                  color: playerMode === "range" ? "var(--onPrimary)" : "var(--textDim)",
                  fontFamily: "'Cairo', sans-serif", fontSize: 11.5, fontWeight: 700,
                }}
              >
                نطاق متتالي
              </button>
              <button
                onClick={() => setPlayerMode("custom")}
                style={{
                  flex: 1, padding: "6px 8px", borderRadius: 10, cursor: "pointer",
                  border: `1px solid ${playerMode === "custom" ? "transparent" : "var(--border)"}`,
                  background: playerMode === "custom" ? "var(--primary)" : "var(--surface)",
                  color: playerMode === "custom" ? "var(--onPrimary)" : "var(--textDim)",
                  fontFamily: "'Cairo', sans-serif", fontSize: 11.5, fontWeight: 700,
                }}
              >
                قائمتي الخاصة
              </button>
            </div>

            {playerMode === "range" ? (
              <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
                <select
                  value={rangeFrom ?? scopedList[0]?.id ?? ""}
                  onChange={(e) => setRangeFrom(Number(e.target.value))}
                  style={{ ...inputStyle(), flex: 1, fontSize: 12, padding: "7px 8px" }}
                >
                  {scopedList.map((s) => <option key={s.id} value={s.id}>من: {s.name}</option>)}
                </select>
                <select
                  value={rangeTo ?? scopedList[0]?.id ?? ""}
                  onChange={(e) => setRangeTo(Number(e.target.value))}
                  style={{ ...inputStyle(), flex: 1, fontSize: 12, padding: "7px 8px" }}
                >
                  {scopedList.map((s) => <option key={s.id} value={s.id}>إلى: {s.name}</option>)}
                </select>
              </div>
            ) : (
              <div style={{ marginBottom: 10 }}>
                <div style={{ display: "flex", gap: 6, marginBottom: 8 }}>
                  <select
                    value={activePlaylistId || ""}
                    onChange={(e) => setActivePlaylistId(e.target.value)}
                    style={{ ...inputStyle(), flex: 1, fontSize: 12, padding: "7px 8px" }}
                  >
                    {playlists.map((p) => <option key={p.id} value={p.id}>{p.name} ({p.ids.length})</option>)}
                  </select>
                  <button onClick={renameActivePlaylist} title="تعديل اسم القائمة" style={{ ...iconBtn(), width: 34, height: 34 }}>✏️</button>
                  <button onClick={deleteActivePlaylist} disabled={playlists.length <= 1} title="حذف القائمة" style={{ ...iconBtn(), width: 34, height: 34, opacity: playlists.length <= 1 ? 0.4 : 1 }}>🗑️</button>
                </div>

                <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
                  <input
                    value={newPlaylistName}
                    onChange={(e) => setNewPlaylistName(e.target.value)}
                    onKeyDown={(e) => { if (e.key === "Enter") addPlaylist(); }}
                    placeholder="اسم قائمة جديدة: قبل النوم، الحفظ..."
                    style={{ ...inputStyle(), flex: 1, fontSize: 12, padding: "7px 10px" }}
                  />
                  <button onClick={addPlaylist} disabled={!newPlaylistName.trim()} style={{ ...btnPrimarySmall(), padding: "7px 12px", opacity: newPlaylistName.trim() ? 1 : 0.5 }}>+ قائمة</button>
                </div>

                <div style={{ position: "relative", marginBottom: 8 }}>
                  <input
                    value={customSearch}
                    onChange={(e) => setCustomSearch(e.target.value)}
                    placeholder={activePlaylist ? `أضيفي سورة إلى «${activePlaylist.name}»...` : "ابحثي عن سورة عشان تضيفيها..."}
                    style={{ ...inputStyle(), width: "100%", fontSize: 12.5, padding: "8px 10px" }}
                  />
                  {customSearch.trim() && (
                    <div style={{
                      position: "absolute", top: "calc(100% + 4px)", right: 0, left: 0, zIndex: 6,
                      background: "var(--surface)", border: "1px solid var(--border)", borderRadius: 10,
                      maxHeight: 160, overflowY: "auto", boxShadow: "0 8px 20px rgba(0,0,0,0.18)",
                    }}>
                      {scopedList.filter((s) => s.name.includes(customSearch.trim())).slice(0, 8).map((s) => (
                        <div
                          key={s.id}
                          onClick={() => { addToActivePlaylist(s.id); setCustomSearch(""); }}
                          style={{ padding: "8px 10px", cursor: "pointer", fontSize: 12.5, fontFamily: "'Cairo', sans-serif", color: "var(--text)", display: "flex", justifyContent: "space-between", alignItems: "center" }}
                        >
                          <span>{s.name}</span>
                          <span style={{ color: activePlaylist?.ids.includes(s.id) ? "var(--textDim)" : "var(--primary)", fontSize: 16 }}>{activePlaylist?.ids.includes(s.id) ? "✓" : "+"}</span>
                        </div>
                      ))}
                      {scopedList.filter((s) => s.name.includes(customSearch.trim())).length === 0 && (
                        <div style={{ padding: "8px 10px", fontSize: 12, color: "var(--textDim)" }}>لا توجد نتائج</div>
                      )}
                    </div>
                  )}
                </div>

                {activePlaylist?.ids.length ? (
                  <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 8 }}>
                    {activePlaylist.ids.map((id, idx) => {
                      const s = quran.list.find((x) => x.id === id);
                      return (
                        <div
                          key={`${id}-${idx}`}
                          draggable
                          onDragStart={() => setDraggedPlaylistIndex(idx)}
                          onDragOver={(e) => e.preventDefault()}
                          onDrop={(e) => { e.preventDefault(); if (draggedPlaylistIndex != null) movePlaylistItem(draggedPlaylistIndex, idx); setDraggedPlaylistIndex(null); }}
                          onDragEnd={() => setDraggedPlaylistIndex(null)}
                          style={{ display: "flex", alignItems: "center", gap: 7, background: "var(--surfaceAlt)", borderRadius: 10, padding: "6px 8px", cursor: "grab", opacity: draggedPlaylistIndex === idx ? 0.55 : 1 }}
                        >
                          <span style={{ fontSize: 11, color: "var(--textDim)", width: 18, textAlign: "center" }}>☷</span>
                          <span style={{ fontSize: 11, color: "var(--textDim)", width: 16 }}>{idx + 1}</span>
                          <span style={{ flex: 1, fontSize: 12.5, color: "var(--text)", fontFamily: "'Cairo', sans-serif" }}>{s?.name || id}</span>
                          <button onClick={() => movePlaylistItem(idx, idx - 1)} disabled={idx === 0} title="تحريك لأعلى" style={{ ...iconBtn(), width: 26, height: 26, opacity: idx === 0 ? 0.3 : 1 }}>↑</button>
                          <button onClick={() => movePlaylistItem(idx, idx + 1)} disabled={idx === activePlaylist.ids.length - 1} title="تحريك لأسفل" style={{ ...iconBtn(), width: 26, height: 26, opacity: idx === activePlaylist.ids.length - 1 ? 0.3 : 1 }}>↓</button>
                          <button onClick={() => removeFromActivePlaylist(idx)} title="حذف من القائمة" style={{ ...iconBtn(), width: 26, height: 26 }}>×</button>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div style={{ fontSize: 11.5, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif", textAlign: "center", padding: "8px 0" }}>
                    أضيفي السور بالبحث، وبعدها تقدري تغيّري ترتيبها بالسحب أو بأسهم ↑ ↓.
                  </div>
                )}

                <div style={{ display: "flex", gap: 8 }}>
                  <button onClick={startCustomQueue} disabled={!customList.length} style={{ ...btnPrimarySmall(), flex: 1, opacity: customList.length ? 1 : 0.5 }}>▶️ تشغيل «{activePlaylist?.name || "القائمة"}»</button>
                  {customList.length > 0 && (
                    <button onClick={() => updateActivePlaylistIds([])} style={{ ...btnGhost(), padding: "8px 12px" }}>مسح السور</button>
                  )}
                </div>
              </div>
            )}

            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", justifyContent: "center" }}>
              {LISTEN_SPEEDS.map((sp) => (
                <button
                  key={sp}
                  onClick={() => setSpeed(sp)}
                  style={{
                    padding: "4px 9px", borderRadius: 999, border: `1px solid ${speed === sp ? "transparent" : "var(--border)"}`,
                    background: speed === sp ? "var(--primary)" : "var(--surface)",
                    color: speed === sp ? "var(--onPrimary)" : "var(--textDim)",
                    fontFamily: "'Cairo', sans-serif", fontSize: 10.5, fontWeight: 600, cursor: "pointer",
                  }}
                >
                  {sp}×
                </button>
              ))}
            </div>
          </div>
        )}
      </Card>

      <Card onClick={toggleRadio} style={{ padding: "14px 16px", marginBottom: 8, display: "flex", alignItems: "center", gap: 12, cursor: "pointer", background: "linear-gradient(135deg, var(--primary), color-mix(in srgb, var(--primary) 75%, black))" }}>
        <div style={{
          width: 40, height: 40, borderRadius: "50%", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center",
          background: "rgba(255,255,255,0.2)", color: "var(--onPrimary)",
        }}>
          {radioStatus === "loading" ? <Gauge size={18} /> : radioPlaying ? <Pause size={18} /> : <span style={{ fontSize: 18 }}>📻</span>}
        </div>
        <div style={{ flex: 1 }}>
          <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, fontWeight: 700, color: "var(--onPrimary)" }}>إذاعة القرآن الكريم{radioSource === "fallback" ? " (عام)" : " — القاهرة"}</div>
          <div style={{ fontSize: 11.5, color: "rgba(255,255,255,0.8)" }}>
            {radioStatus === "offline" ? "البث المباشر محتاج إنترنت — جرّبي الاستماع للقرآن من قسم الاستماع بدل الراديو" : radioStatus === "error" ? "تعذّر الاتصال بالإذاعة الآن" : radioPlaying ? "🔴 بث مباشر الآن" : "بث مباشر ٢٤ ساعة"}
          </div>
        </div>
      </Card>
      <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
        <button onClick={() => toggleRadio("primary")} style={{ ...btnGhost(), flex: 1, justifyContent: "center", fontSize: 11.5, padding: "6px 10px" }}>القاهرة</button>
        <button onClick={() => toggleRadio("fallback")} style={{ ...btnGhost(), flex: 1, justifyContent: "center", fontSize: 11.5, padding: "6px 10px" }}>عام (احتياطي)</button>
      </div>

      <Card onClick={playRuqyah} style={{ padding: "10px 14px", marginBottom: 14, display: "flex", alignItems: "center", gap: 10, cursor: "pointer", background: "var(--accentSoft)" }}>
        <div style={{
          width: 30, height: 30, borderRadius: "50%", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center",
          background: ruqyahIndex != null ? "var(--primary)" : "var(--surface)", color: ruqyahIndex != null ? "var(--onPrimary)" : "var(--accent)",
        }}>
          {ruqyahIndex != null && status === "loading" ? <Gauge size={14} /> : ruqyahIndex != null && status === "playing" ? <Pause size={14} /> : <span style={{ fontSize: 13 }}>🛡️</span>}
        </div>
        <div style={{ flex: 1 }}>
          <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: "var(--text)" }}>الرقية الشرعية</div>
          <div style={{ fontSize: 10.5, color: "var(--textDim)" }}>
            {ruqyahIndex != null ? `آية ${ruqyahIndex + 1} من ${ruqyahListRef.current.length}` : "الفاتحة، آية الكرسي، خواتيم البقرة، والمعوذات"}
          </div>
        </div>
      </Card>

      <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="ابحث عن سورة..." style={{ ...inputStyle(), width: "100%", marginBottom: 12 }} />

      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {filteredList.map((s) => {
          const isThis = playingSurah === s.id;
          const isDownloaded = downloadedKeys.has(s.id);
          const isDownloading = downloadingKey === s.id;
          return (
            <Card key={s.id} style={{ padding: "12px 16px", display: "flex", alignItems: "center", gap: 12 }}>
              <button onClick={() => playSurah(s.id)} style={{
                width: 38, height: 38, borderRadius: "50%", border: "none", cursor: "pointer", flexShrink: 0,
                background: isThis ? "var(--primary)" : "var(--surfaceAlt)", color: isThis ? "var(--onPrimary)" : "var(--textDim)",
                display: "flex", alignItems: "center", justifyContent: "center",
              }}>
                {isThis && status === "loading" ? <Gauge size={16} /> : isThis && status === "playing" ? <Pause size={16} /> : <Play size={16} />}
              </button>
              <div style={{ flex: 1 }}>
                <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 15, color: "var(--text)" }}>سورة {s.name}</div>
                <div style={{ fontSize: 11.5, color: "var(--textDim)" }}>{s.verses} آيات{isDownloaded ? " · محمّلة للاستماع بدون نت" : ""}</div>
              </div>
              {isThis && status === "error" && <span style={{ fontSize: 11, color: "var(--danger)" }}>خطأ</span>}
              <button
                onClick={() => (isDownloaded ? removeDownload(s.id) : downloadSurah(s.id))}
                disabled={isDownloading}
                title={isDownloaded ? "حذف النسخة المحمّلة" : "تحميل للاستماع بدون نت"}
                style={{ ...iconBtn(), width: 32, height: 32, flexShrink: 0, color: isDownloaded ? "var(--primary)" : "var(--textDim)" }}
              >
                {isDownloading ? <Gauge size={14} /> : isDownloaded ? <CheckCircle2 size={14} /> : <Download size={14} />}
              </button>
            </Card>
          );
        })}
      </div>
      {errorMsg && <p style={{ textAlign: "center", fontSize: 12, color: "var(--danger)", marginTop: 12, fontFamily: "'Cairo', sans-serif" }}>{errorMsg} لو فضل مايشتغلش، جرّبي العفاسي أو الحصري أو السديس أو المعيقلي.</p>}
      <p style={{ textAlign: "center", fontSize: 11, color: "var(--textDim)", marginTop: 14, fontFamily: "'Cairo', sans-serif" }}>
        بث مباشر عند الطلب من مصدر رسمي (cdn.islamic.network) — دوسي على أيقونة التحميل ↓ بجانب أي سورة عشان تشتغل بدون إنترنت لاحقًا.
      </p>
      <div style={{ height: 24 }} />
    </div>
  );
}

// أفتار مميّز لكل قارئ: أول حرف من اسمه بخط عربي جميل على خلفية متدرّجة لونها
// مُشتق من اسمه (ثابت دائمًا لنفس القارئ). بديل احترافي عن صور حقيقية، لتفادي
// استخدام صور لأشخاص حقيقيين بدون ترخيص واضح لإعادة توزيعها داخل الكود.
const AVATAR_HUES = [210, 260, 340, 25, 160, 190, 305, 40];
function hashStr(s) { let h = 0; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h; }
function ReciterAvatar({ name, size = 40 }) {
  const hue = AVATAR_HUES[hashStr(name) % AVATAR_HUES.length];
  const initial = name.replace("الشيخ ", "").trim()[0] || "ق";
  return (
    <div style={{
      width: size, height: size, borderRadius: "50%", flexShrink: 0,
      background: `linear-gradient(135deg, hsl(${hue},38%,88%), hsl(${hue},32%,74%))`,
      display: "flex", alignItems: "center", justifyContent: "center",
      border: `1.5px solid hsl(${hue},30%,60%)`,
    }}>
      <span style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: size * 0.42, color: `hsl(${hue},45%,28%)` }}>{initial}</span>
    </div>
  );
}

function RecitersScreen({ prefs, updatePrefs, onBack, field = "reciter", title = "اختر القارئ" }) {
  const current = prefs[field];
  return (
    <div>
      <TopBarBack onBack={onBack} title={title} />
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {RECITERS.map((r) => (
          <Card key={r.id} onClick={() => updatePrefs({ [field]: r.id })} style={{ padding: "15px 18px", cursor: "pointer", display: "flex", alignItems: "center", gap: 14, border: current === r.id ? "1.5px solid var(--primary)" : "1px solid var(--border)" }}>
            <ReciterAvatar name={r.name} size={44} />
            <div style={{ flex: 1 }}>
              <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", fontWeight: 500 }}>{r.name}</div>
              <div style={{ fontSize: 12, color: "var(--textDim)" }}>{r.style}</div>
            </div>
            {current === r.id && <CheckCircle2 size={19} color="var(--primary)" />}
          </Card>
        ))}
      </div>
      <p style={{ fontSize: 11, color: "var(--textDim)", marginTop: 14, fontFamily: "'Cairo', sans-serif", textAlign: "center", lineHeight: 1.7 }}>
        الأفاتار عبارة عن حرف مميّز بدل صورة حقيقية — كده نتجنّب استخدام صور أشخاص من الإنترنت بدون ترخيص واضح لإعادة نشرها داخل التطبيق.
      </p>
    </div>
  );
}


/* =========================================================================
   Memorization & voice recitation flow
   ========================================================================= */

function normalizeArabic(s) {
  return s
    .replace(/[\u064B-\u065F\u0670]/g, "") // remove tashkeel
    .replace(/[إأآا]/g, "ا")
    .replace(/ة/g, "ه")
    .replace(/ى/g, "ي")
    .replace(/[^\u0600-\u06FF\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function speechSupported() {
  return typeof window !== "undefined" && !!(window.SpeechRecognition || window.webkitSpeechRecognition);
}
// سفاري (آيفون/ماك) لسه ما بيدعمش واجهة SpeechRecognition خالص لحد دلوقتي —
// ده قيد حقيقي من آبل نفسها، مش خطأ في التطبيق. نكتشفه عشان نديها رسالة واضحة
// ومحدّدة ("افتحي من Chrome") بدل رسالة عامة مبهمة متسيبها من غير حل.
function isSafariBrowser() {
  if (typeof navigator === "undefined") return false;
  const ua = navigator.userAgent || "";
  return /Safari/.test(ua) && !/Chrome|CriOS|Chromium|Android/.test(ua);
}

// Tokenize a canonical ayah into word objects, keeping the original (with
// tashkeel) for display and a normalized form for matching speech against.
function tokenizeWords(canonicalText) {
  return canonicalText.split(" ").filter(Boolean).map((w, i) => ({
    id: i, text: w, norm: normalizeArabic(w),
  }));
}

async function loadMistakes() {
  try {
    const res = await window.storage.get("unisk:mistakes", false);
    return res?.value ? JSON.parse(res.value) : [];
  } catch { return []; }
}
async function saveMistakes(list) {
  try { await window.storage.set("unisk:mistakes", JSON.stringify(list.slice(-300)), false); } catch { /* best effort */ }
}
async function loadRecitationPosition() {
  try {
    const res = await window.storage.get("unisk:recitation-position", false);
    return res?.value ? JSON.parse(res.value) : null;
  } catch { return null; }
}
async function saveRecitationPosition(pos) {
  try { await window.storage.set("unisk:recitation-position", JSON.stringify(pos), false); } catch { /* best effort */ }
}

// آخر موضع قراءة عام (مستقل عن موضع التسميع) — يُحفظ تلقائيًا كل ما اتقلبت صفحة في المصحف
async function loadReadingPosition() {
  try {
    const res = await window.storage.get("unisk:reading-position", false);
    return res?.value ? JSON.parse(res.value) : null;
  } catch { return null; }
}
async function saveReadingPosition(pos) {
  try { await window.storage.set("unisk:reading-position", JSON.stringify(pos), false); } catch { /* best effort */ }
}

// علامة توقّف صريحة تحطّيها المستخدمة بنفسها على آية معيّنة (زي شريط الفاصل في
// المصحف الورقي) — مختلفة عن "آخر موضع قراءة" اللي بيتسجّل تلقائيًا مجرد ما تفتحي
// أي صفحة، دي بالذات محتاجة فعل إرادي من المستخدمة (من قائمة الآية).
async function loadMarkedAyah() {
  try {
    const res = await window.storage.get("unisk:marked-ayah", false);
    return res?.value ? JSON.parse(res.value) : null;
  } catch { return null; }
}
async function saveMarkedAyah(mark) {
  try {
    if (mark) await window.storage.set("unisk:marked-ayah", JSON.stringify(mark), false);
    else await window.storage.delete("unisk:marked-ayah", false);
  } catch { /* best effort */ }
}

// علامات ذكية متعدّدة على الآيات — مختلفة عن "موضع التوقّف" اللي بيبقى واحد بس
// وبيتشال تلقائيًا؛ العلامات دي تصنيفية وبتفضل زي ما هي، وممكن الآية الواحدة
// تاخد أكتر من علامة في نفس الوقت (زي "أحبها" و"للحفظ" مع بعض).
const AYAH_TAG_TYPES = [
  { id: "important", label: "آية مهمة", icon: "⭐" },
  { id: "loved", label: "آية أحبها", icon: "❤️" },
  { id: "memorize", label: "آية للحفظ", icon: "🧠" },
  { id: "review", label: "آية للمراجعة", icon: "🔁" },
  { id: "revisit", label: "أريد الرجوع إليها", icon: "📌" },
];
async function loadAyahTags() {
  try {
    const res = await window.storage.get("unisk:ayah-tags", false);
    return res?.value ? JSON.parse(res.value) : {};
  } catch { return {}; }
}
async function saveAyahTags(map) {
  try { await window.storage.set("unisk:ayah-tags", JSON.stringify(map), false); } catch { /* best effort */ }
}

async function loadHiddenAyahs() {
  try {
    const res = await window.storage.get("unisk:hidden-ayahs", false);
    return res?.value ? JSON.parse(res.value) : {};
  } catch { return {}; }
}
async function saveHiddenAyahs(map) {
  try { await window.storage.set("unisk:hidden-ayahs", JSON.stringify(map), false); } catch { /* best effort */ }
}

// Word-level diff (simple LCS-based alignment) so we can show the reciter
// exactly which word(s) in the ayah didn't match what was heard, instead of
// a flat correct/incorrect verdict.
function diffWords(expectedText, heardText) {
  const exp = normalizeArabic(expectedText).split(" ").filter(Boolean);
  const heard = normalizeArabic(heardText).split(" ").filter(Boolean);
  const n = exp.length, m = heard.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      dp[i][j] = exp[i - 1] === heard[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
    }
  }
  const matched = new Array(n).fill(false);
  let i = n, j = m;
  while (i > 0 && j > 0) {
    if (exp[i - 1] === heard[j - 1]) { matched[i - 1] = true; i--; j--; }
    else if (dp[i - 1][j] >= dp[i][j - 1]) i--;
    else j--;
  }
  const originalWords = expectedText.split(" ").filter(Boolean);
  return originalWords.map((w, idx) => ({ word: w, ok: matched[idx] }));
  }

/* =========================================================================
   RecitationEngine — real word-by-word recitation tracking.

   HONESTY NOTE ON THE UNDERLYING TECHNOLOGY (see also the in-app note in
   the recitation setup screen): this engine uses the browser's built-in
   continuous speech recognition (Web Speech API) as its recognizer. That
   API gives final-chunk transcripts (roughly one chunk per natural pause),
   not true per-word streaming timestamps, and its per-result confidence
   score is unreliable/inconsistent across browsers. What IS real here:
   - continuous, hands-free listening (not record→stop→analyze)
   - a genuine sequential word-alignment algorithm (not random/hardcoded)
     that walks the recognized words against the verified expected words
     for the selected passage, detecting correct/skipped/repeated/
     reordered/wrong words as they come in
   - a real state machine driving the UI
   A production-grade Quran-specific ASR model (word-level timestamps,
   Quran-vocabulary-constrained decoding, tajweed/makharij analysis) is
   NOT implemented — the adapter below is the seam where such a service
   would plug in later without changing the rest of the engine.
   ========================================================================= */

const RECOGNIZER_ADAPTERS = {
  webSpeech: "webSpeech", // only implemented adapter today
  // quranASR: reserved seam for a dedicated Quran ASR/alignment service
};

function useRecitationEngine(ayahs, mode = "training") {
  // ayahs: [{ surahId, ayahIndexInSurah, globalNumber, text, words: [{id,text,norm}] }]
  // mode: training (تسامح أكتر، تلميحات فورية) | test (بدون كشف مباشر) | advanced (صرامة أعلى، محاولات أقل قبل التخطي)
  const [status, setStatus] = useState("idle"); // idle|listening|paused|completed|error
  const [ayahPos, setAyahPos] = useState(0);
  const [wordIdx, setWordIdx] = useState(0);
  const [wordStatus, setWordStatus] = useState({}); // `${ayahPos}:${wordId}` -> status
  const [errorMsg, setErrorMsg] = useState("");
  const [hintsUsed, setHintsUsed] = useState({}); // `${ayahPos}` -> level
  const [sessionMistakes, setSessionMistakes] = useState([]);
  const [extraWords, setExtraWords] = useState(0); // كلمات اتقالت ومالهاش أي تطابق في النطاق كله
  const startTimeRef = useRef(null);
  const attemptsRef = useRef({});
  const recRef = useRef(null);
  const shouldListenRef = useRef(false);
  const ayahPosRef = useRef(0); ayahPosRef.current = ayahPos;
  const wordIdxRef = useRef(0); wordIdxRef.current = wordIdx;
  const maxAttempts = mode === "advanced" ? 2 : mode === "test" ? 3 : 4;
  const lookWindow = mode === "advanced" ? 2 : 3;

  const currentAyah = ayahs[ayahPos];
  const key = (pos, wid) => `${pos}:${wid}`;

  const markWord = useCallback((pos, wid, st) => {
    setWordStatus((prev) => ({ ...prev, [key(pos, wid)]: st }));
  }, []);

  const logMistake = useCallback((pos, wid, type) => {
    const ayah = ayahs[pos];
    const word = ayah?.words[wid];
    if (!word) return;
    const entry = {
      surahId: ayah.surahId, ayahIndex: ayah.ayahIndexInSurah, wordId: wid, word: word.text,
      type, date: todayKey(), ts: Date.now(),
    };
    setSessionMistakes((m) => [...m, entry]);
  }, [ayahs]);

  const advanceToNextAyah = useCallback(() => {
    if (ayahPosRef.current + 1 >= ayahs.length) {
      shouldListenRef.current = false;
      recRef.current?.stop();
      setStatus("completed");
    } else {
      setAyahPos((p) => p + 1);
      setWordIdx(0);
    }
  }, [ayahs.length]);

  const consumeWord = useCallback((normWord, confidence) => {
    const pos = ayahPosRef.current;
    const ayah = ayahs[pos];
    if (!ayah) return;
    const words = ayah.words;
    let idx = wordIdxRef.current;
    if (idx >= words.length) return;

    if (words[idx].norm === normWord) {
      const uncertain = typeof confidence === "number" && confidence > 0 && confidence < 0.4;
      markWord(pos, idx, uncertain ? "uncertain" : "correct");
      if (!uncertain) idx++;
    } else {
      const LOOKAHEAD = 3;
      let found = -1;
      for (let k = idx + 1; k < Math.min(words.length, idx + 1 + LOOKAHEAD); k++) {
        if (words[k].norm === normWord) { found = k; break; }
      }
      if (found !== -1) {
        for (let k = idx; k < found; k++) { markWord(pos, k, "skipped"); logMistake(pos, k, "skipped"); }
        markWord(pos, found, "correct");
        idx = found + 1;
      } else if (idx > 0 && words[idx - 1].norm === normWord) {
        markWord(pos, idx - 1, "correct"); // natural repetition — not an error
      } else {
        const LOOKBACK = 3;
        let back = -1;
        for (let k = idx - 1; k >= Math.max(0, idx - LOOKBACK); k--) {
          if (words[k].norm === normWord) { back = k; break; }
        }
        if (back !== -1) {
          markWord(pos, back, "reordered");
        } else {
          const aKey = key(pos, idx);
          attemptsRef.current[aKey] = (attemptsRef.current[aKey] || 0) + 1;
          markWord(pos, idx, "wrong");
          logMistake(pos, idx, "wrong");
          if (attemptsRef.current[aKey] >= 3) {
            markWord(pos, idx, "skipped");
            idx++;
          }
        }
      }
    }
    setWordIdx(idx);
    if (idx >= words.length) advanceToNextAyah();
  }, [ayahs, markWord, logMistake, advanceToNextAyah]);

  const handleFinalTranscript = useCallback((transcript, confidence) => {
    const words = normalizeArabic(transcript).split(" ").filter(Boolean);
    words.forEach((w) => consumeWord(w, confidence));
  }, [consumeWord]);

  const interimConsumedRef = useRef(0); // كام كلمة اتاستهلكت من النتيجة الحالية (نهائية أو مؤقتة)
  const start = useCallback(() => {
    setErrorMsg("");
    if (!speechSupported()) {
      setStatus("error");
      setErrorMsg(
        isSafariBrowser()
          ? "متصفح Safari (آيفون/ماك) لسه ما بيدعمش خاصية التعرف الصوتي في المتصفح. افتحي التطبيق من متصفح Chrome بدل Safari عشان ميزة التسميع تشتغل."
          : "التعرف الصوتي غير متاح في هذا المتصفح — جرّبي فتح التطبيق من Chrome."
      );
      return;
    }
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    const rec = new SR();
    rec.lang = "ar-EG";
    rec.continuous = true;
    rec.interimResults = true;
    rec.maxAlternatives = 1;
    rec.onresult = (e) => {
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const res = e.results[i];
        const words = normalizeArabic(res[0].transcript).split(" ").filter(Boolean);
        // بنستهلك أي كلمة جديدة ظهرت في النتيجة سواء كانت مؤقتة (interim) أو نهائية —
        // ده اللي بيدي الإحساس بالسرعة اللحظية بدل انتظار وقفة الصوت عشان تتأكد الجملة.
        // الكلمات اللي اتأكدت مؤقتًا وبعدين اتصححت في النتيجة النهائية هتتراجع تلقائيًا
        // لأن consumeWord بيشتغل بمنطق مطابقة تسلسلي مش استبدال، فالتصحيح بيحصل لحظة
        // النتيجة النهائية لو فيه اختلاف.
        const already = interimConsumedRef.current;
        for (let w = already; w < words.length; w++) {
          consumeWord(words[w], res[0].confidence);
        }
        interimConsumedRef.current = words.length;
        if (res.isFinal) interimConsumedRef.current = 0; // النتيجة اللي بعدها هتبدأ عدّ جديد
      }
    };
    // قبل كده كانت أي حالة خطأ غير "رفض الإذن" بتتجاهل تمامًا وبصمت (لا رسالة ولا
    // أي تغيير في الحالة) — فلو حصل مثلًا "مفيش مايك متوصّل" أو "مفيش إنترنت" (خدمة
    // جوجل السحابية اللي بيعتمد عليها التعرف الصوتي محتاجة إنترنت فعليًا) أو
    // الخدمة مرفوضة من المتصفح، المستخدمة كانت بتحس إن "المايك مش شغال" من غير أي
    // تفسير أو حل. دلوقتي كل كود خطأ معروف بيدّي رسالة واضحة ومحدّدة.
    rec.onerror = (e) => {
      shouldListenRef.current = false;
      setStatus("error");
      switch (e.error) {
        case "not-allowed":
        case "permission-denied":
          setErrorMsg("تم رفض إذن الميكروفون. فعّليه من إعدادات المتصفح (أيقونة القفل بجانب رابط الموقع) ثم أعيدي المحاولة.");
          break;
        case "audio-capture":
          setErrorMsg("مفيش ميكروفون متاح على هذا الجهاز، أو جهاز تاني بياخد التحكم فيه حاليًا.");
          break;
        case "network":
          setErrorMsg("التعرف الصوتي محتاج اتصال إنترنت فعّال (بيتم عبر خدمة سحابية) — تأكدي من اتصالك وحاولي تاني.");
          break;
        case "service-not-allowed":
          setErrorMsg("خدمة التعرف الصوتي مرفوضة من هذا المتصفح أو الجهاز حاليًا.");
          break;
        case "language-not-supported":
          setErrorMsg("اللهجة العربية غير مدعومة على هذا الجهاز حاليًا.");
          break;
        case "no-speech":
          shouldListenRef.current = true; // benign — continuous mode will restart via onend
          setStatus("listening");
          break;
        case "aborted":
          break; // تم الإيقاف يدويًا — مش خطأ حقيقي
        default:
          setErrorMsg("تعذّر تشغيل التعرف الصوتي (خطأ: " + (e.error || "غير معروف") + "). جرّبي تاني أو من متصفح Chrome.");
      }
    };
    rec.onend = () => {
      interimConsumedRef.current = 0;
      if (shouldListenRef.current) { try { rec.start(); } catch { /* already starting */ } }
    };
    recRef.current = rec;
    shouldListenRef.current = true;
    try {
      rec.start();
      setStatus("listening");
    } catch {
      setStatus("error");
      setErrorMsg("تعذّر بدء الاستماع — أغلقي أي تطبيق آخر بيستخدم الميكروفون وحاولي تاني.");
    }
  }, [consumeWord]);

  const pause = useCallback(() => { shouldListenRef.current = false; recRef.current?.stop(); setStatus("paused"); }, []);
  const resume = useCallback(() => { start(); }, [start]);
  const stop = useCallback(() => { shouldListenRef.current = false; recRef.current?.stop(); setStatus("idle"); }, []);

  const retryCurrentAyah = useCallback(() => {
    const pos = ayahPosRef.current;
    const ayah = ayahs[pos];
    if (!ayah) return;
    setWordStatus((prev) => {
      const next = { ...prev };
      ayah.words.forEach((w) => delete next[key(pos, w.id)]);
      return next;
    });
    setWordIdx(0);
  }, [ayahs]);

  const useHint = useCallback(() => {
    const pos = ayahPosRef.current;
    setHintsUsed((h) => ({ ...h, [pos]: Math.min(4, (h[pos] || 0) + 1) }));
  }, []);

  const finish = useCallback(() => {
    shouldListenRef.current = false;
    recRef.current?.stop();
    setStatus("completed");
  }, []);

  useEffect(() => () => { shouldListenRef.current = false; recRef.current?.stop(); }, []);

  const summary = useMemo(() => {
    let correct = 0, wrong = 0, skipped = 0, total = 0;
    ayahs.forEach((ayah, pos) => {
      ayah.words.forEach((w) => {
        total++;
        const st = wordStatus[key(pos, w.id)];
        if (st === "correct" || st === "reordered") correct++;
        else if (st === "wrong") wrong++;
        else if (st === "skipped") skipped++;
      });
    });
    return { correct, wrong, skipped, total, needsReview: wrong + skipped };
  }, [ayahs, wordStatus]);

  return {
    status, ayahPos, wordIdx, wordStatus, errorMsg, hintsUsed, sessionMistakes, summary, currentAyah,
    start, pause, resume, stop, finish, retryCurrentAyah, useHint,
    getWordStatus: (pos, wid) => wordStatus[key(pos, wid)] || "pending",
  };
}


function MemorizeFlow({ surahId, surahName, ayat, reciter, day, updateDay, onBack }) {
  const [stage, setStage] = useState("setup"); // setup | practice | result | mistakes
  const [mode, setMode] = useState("recite"); // read | recite | test
  const [rangeStart, setRangeStart] = useState(1);
  const [rangeEnd, setRangeEnd] = useState(Math.min(5, ayat.length));
  const [playingAudio, setPlayingAudio] = useState(false);
  const [audioError, setAudioError] = useState("");
  const [savedPosition, setSavedPosition] = useState(null);
  const [mistakeList, setMistakeList] = useState(null);
  const listenAudioRef = useRef(null);
  const finalizedRef = useRef(false);

  useEffect(() => {
    loadRecitationPosition().then((pos) => { if (pos && pos.surahId === surahId) setSavedPosition(pos); });
  }, [surahId]);

  const sessionAyahs = useMemo(() => {
    const list = [];
    for (let i = rangeStart - 1; i <= rangeEnd - 1 && i < ayat.length; i++) {
      list.push({ surahId, ayahIndexInSurah: i, globalNumber: ayat[i].globalNumber, text: ayat[i].text, words: tokenizeWords(ayat[i].text) });
    }
    return list;
  }, [rangeStart, rangeEnd, ayat, surahId]);

  const engine = useRecitationEngine(sessionAyahs);

  useEffect(() => {
    if (engine.status === "completed" && stage === "practice") {
      setStage("result");
      if (!finalizedRef.current) {
        finalizedRef.current = true;
        loadMistakes().then((prev) => saveMistakes([...prev, ...engine.sessionMistakes]));
        updateDay({ memorized: (day.memorized || 0) + engine.summary.correct });
        saveRecitationPosition(null);
      }
    }
  }, [engine.status]); // eslint-disable-line

  const playAyahAudio = (ayahObj) => {
    setAudioError("");
    if (!reciter?.edition) { setAudioError("لا يتوفر صوت لهذا القارئ حاليًا — جرّب قارئًا آخر من الإعدادات."); return; }
    if (!ayahObj?.globalNumber) { setAudioError("هذا النص محلي بلا رقم آية عالمي، فلا يتوفر له صوت."); return; }
    const url = ayahAudioUrl(reciter.edition, ayahObj.globalNumber);
    if (!listenAudioRef.current) listenAudioRef.current = new Audio();
    const el = listenAudioRef.current;
    el.src = url;
    el.onplay = () => setPlayingAudio(true);
    el.onended = () => setPlayingAudio(false);
    el.onerror = () => { setPlayingAudio(false); setAudioError("تعذّر تحميل الصوت — تحقّق من الاتصال بالإنترنت."); };
    el.play().catch(() => setAudioError("تعذّر تشغيل الصوت."));
  };
  const stopAyahAudio = () => { listenAudioRef.current?.pause(); setPlayingAudio(false); };
  useEffect(() => () => listenAudioRef.current?.pause(), []);

  const startSession = () => {
    finalizedRef.current = false;
    setStage("practice");
    if (mode !== "read") engine.start();
  };

  const resumeSaved = () => {
    if (!savedPosition) return;
    setRangeStart(savedPosition.ayahIndex + 1);
    setRangeEnd(ayat.length);
    setMode("recite");
  };

  /* ---------------- SETUP ---------------- */
  if (stage === "setup") {
    return (
      <div>
        <TopBarBack onBack={onBack} title="وضع التسميع" />
        <Card style={{ padding: 20, marginBottom: 16 }}>
          <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", fontWeight: 600, marginBottom: 10 }}>سورة {surahName} — {ayat.length} آيات</div>
          <div style={{ fontSize: 12.5, color: "var(--textDim)" }}>استمع → اقرأ → أخفِ → سمّع → راجع</div>
        </Card>

        {savedPosition && (
          <Card style={{ padding: 16, marginBottom: 16, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontSize: 13, color: "var(--text)", fontFamily: "'Cairo', sans-serif" }}>نكمل من حيث توقفت؟ (آية {savedPosition.ayahIndex + 1})</span>
            <button onClick={resumeSaved} style={btnGhost()}>نعم</button>
          </Card>
        )}

        <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, color: "var(--textDim)", marginBottom: 10 }}>اختر الوضع</div>
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 20 }}>
          {[
            { id: "read", label: "القراءة", sub: "عرض النص الكامل بلا مطابقة صوتية" },
            { id: "recite", label: "التسميع", sub: "النص ظاهر، والذكاء الاصطناعي يتابع كلماتك أثناء القراءة" },
            { id: "test", label: "اختبار الحفظ", sub: "النص مخفي، ويظهر تدريجيًا كل ما سمّعت كلمة صحيحة" },
          ].map((o) => (
            <Card key={o.id} onClick={() => setMode(o.id)} style={{ padding: "13px 16px", cursor: "pointer", border: mode === o.id ? "1.5px solid var(--primary)" : "1px solid var(--border)" }}>
              <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, color: "var(--text)", fontWeight: 600 }}>{o.label}</div>
              <div style={{ fontSize: 12, color: "var(--textDim)" }}>{o.sub}</div>
            </Card>
          ))}
        </div>

        <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, color: "var(--textDim)", marginBottom: 10 }}>نطاق الآيات</div>
        <div style={{ display: "flex", gap: 10, marginBottom: 16 }}>
          <select value={rangeStart} onChange={(e) => { const v = Number(e.target.value); setRangeStart(v); if (v > rangeEnd) setRangeEnd(v); }} style={{ ...inputStyle(), flex: 1 }}>
            {ayat.map((_, i) => <option key={i} value={i + 1}>من آية {i + 1}</option>)}
          </select>
          <select value={rangeEnd} onChange={(e) => setRangeEnd(Number(e.target.value))} style={{ ...inputStyle(), flex: 1 }}>
            {ayat.map((_, i) => <option key={i} value={i + 1} disabled={i + 1 < rangeStart}>إلى آية {i + 1}</option>)}
          </select>
        </div>

        {mode !== "read" && !speechSupported() && (
          <div style={{ display: "flex", gap: 8, alignItems: "flex-start", background: "var(--surfaceAlt)", padding: 12, borderRadius: 12, marginBottom: 16 }}>
            <Info size={15} color="var(--textDim)" style={{ marginTop: 2, flexShrink: 0 }} />
            <span style={{ fontSize: 12, color: "var(--textDim)", lineHeight: 1.7 }}>
              {isSafariBrowser()
                ? "متصفح Safari (آيفون/ماك) لسه ما بيدعمش خاصية التعرف الصوتي في المتصفح — ده قيد من آبل نفسها، مش عيب في التطبيق. افتحي أنيسك من متصفح Chrome عشان وضع التسميع يشتغل، أو استخدمي وضع \"القراءة\" اللي شغال في كل المتصفحات."
                : "التعرف الصوتي غير متاح في هذا المتصفح/الجهاز حاليًا — جرّبي فتح التطبيق من Chrome، أو استخدمي وضع \"القراءة\" اللي شغال دايمًا."}
            </span>
          </div>
        )}

        <button onClick={startSession} style={btnPrimary()}>ابدأ</button>

        <button onClick={() => loadMistakes().then((m) => { setMistakeList(m.filter((x) => x.surahId === surahId)); setStage("mistakes"); })} style={{ ...btnGhost(), width: "100%", justifyContent: "center", marginTop: 12 }}>
          📖 سجل أخطائي في هذه السورة
        </button>
      </div>
    );
  }

  /* ---------------- MISTAKES LOG ---------------- */
  if (stage === "mistakes") {
    const grouped = {};
    (mistakeList || []).forEach((m) => {
      const k = `${m.ayahIndex}:${m.wordId}`;
      grouped[k] = grouped[k] || { ...m, count: 0 };
      grouped[k].count++;
    });
    const rows = Object.values(grouped).sort((a, b) => b.count - a.count);
    return (
      <div>
        <TopBarBack onBack={() => setStage("setup")} title="سجل أخطائي" />
        {rows.length === 0 ? (
          <EmptyState icon={<Sparkles size={26} />} title="لا يوجد أخطاء مسجّلة في هذه السورة 🤍" />
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {rows.map((r, i) => (
              <Card key={i} style={{ padding: "13px 16px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <div style={{ fontFamily: "'Amiri', serif", fontSize: 17, color: "var(--text)" }}>{r.word}</div>
                  <div style={{ fontSize: 11.5, color: "var(--textDim)" }}>آية {r.ayahIndex + 1} · {r.type === "skipped" ? "كلمة فائتة" : "خطأ"}</div>
                </div>
                <span style={{ fontSize: 12, color: "var(--danger)", fontFamily: "'Cairo', sans-serif" }}>×{r.count}</span>
              </Card>
            ))}
            {rows.length > 0 && (
              <button onClick={() => { setRangeStart(rows[0].ayahIndex + 1); setRangeEnd(rows[0].ayahIndex + 1); setMode("test"); setStage("setup"); }} style={{ ...btnPrimary(), marginTop: 10 }}>
                🧠 بدء مراجعة ذكية لأكثر الكلمات خطأً
              </button>
            )}
          </div>
        )}
      </div>
    );
  }

  /* ---------------- RESULT ---------------- */
  if (stage === "result") {
    const { correct, wrong, skipped, total } = engine.summary;
    const pct = total ? Math.round((correct / total) * 100) : 0;
    return (
      <div>
        <TopBarBack onBack={onBack} title="نتيجة التسميع 🤍" />
        <Card style={{ padding: 26, textAlign: "center" }}>
          <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, color: "var(--textDim)" }}>سورة {surahName} — آيات {rangeStart} إلى {rangeEnd}</div>
          <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 34, color: "var(--primary)", margin: "10px 0" }}>{correct} / {total}</div>
          <div style={{ fontSize: 14, color: "var(--text)" }}>{pct}% من الكلمات صحيحة</div>
        </Card>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginTop: 16 }}>
          <MiniStat icon={<Flame size={16} />} label="كلمات فائتة" value={skipped} />
          <MiniStat icon={<Info size={16} />} label="تحتاج مراجعة" value={wrong} />
        </div>
        {(wrong + skipped) > 0 ? (
          <button onClick={() => loadMistakes().then((m) => { setMistakeList(m.filter((x) => x.surahId === surahId)); setStage("mistakes"); })} style={{ ...btnPrimary(), marginTop: 20 }}>راجع الأخطاء</button>
        ) : (
          <div style={{ textAlign: "center", marginTop: 20, color: "var(--primary)", fontFamily: "'Cairo', sans-serif" }}>أحسنت! تسميع متقن تمامًا 🤍</div>
        )}
        <button onClick={() => setStage("setup")} style={{ ...btnGhost(), width: "100%", justifyContent: "center", marginTop: 12 }}>تسميع جديد</button>
      </div>
    );
  }

  /* ---------------- PRACTICE ---------------- */
  const curPos = engine.ayahPos;
  const curAyah = sessionAyahs[curPos];
  const hintLvl = engine.hintsUsed[curPos] || 0;
  const statusLabel = {
    idle: "جاهز للبدء", listening: "جاري الاستماع...", paused: "متوقف مؤقتًا", completed: "اكتمل التسميع", error: "تعذّر الاستماع",
  }[engine.status] || "جاري المطابقة";

  const renderWord = (w) => {
    const st = mode === "read" ? "visible" : engine.getWordStatus(curPos, w.id);
    const isCurrent = mode !== "read" && w.id === engine.wordIdx;
    const revealedByHint = isCurrent && hintLvl >= 3;
    const hideInTest = mode === "test" && !["correct", "reordered"].includes(st) && !revealedByHint;

    let content;
    if (mode === "read" || !hideInTest) {
      content = w.text;
    } else if (isCurrent && hintLvl === 1) {
      content = w.text[0] + " " + "○".repeat(Math.max(1, w.text.length - 2));
    } else if (isCurrent && hintLvl === 2) {
      content = w.text.slice(0, Math.ceil(w.text.length / 2)) + "○".repeat(Math.max(1, Math.floor(w.text.length / 2)));
    } else {
      content = "○".repeat(Math.min(5, Math.max(2, w.text.length - 1)));
    }

    const color = mode === "read" ? "var(--text)"
      : st === "correct" || st === "reordered" ? "var(--primary)"
      : st === "wrong" ? "var(--danger)"
      : st === "skipped" ? "var(--textDim)"
      : st === "uncertain" ? "var(--accent)"
      : isCurrent ? "var(--accent)" : "var(--text)";

    return (
      <span key={w.id} style={{
        fontFamily: "'Amiri', serif", fontSize: 21, color,
        background: isCurrent ? "var(--accentSoft)" : "transparent",
        borderRadius: 6, padding: "2px 5px", margin: "0 1px",
        textDecoration: st === "skipped" ? "line-through" : "none",
        opacity: st === "skipped" ? 0.55 : 1,
        transition: "background .25s, color .25s",
        display: "inline-block",
      }}>
        {content}
      </span>
    );
  };

  return (
    <div>
      <TopBarBack onBack={() => { engine.stop(); onBack(); }} title={`آية ${curPos + rangeStart} من ${rangeEnd}`} right={
        <button onClick={() => setStage("setup")} style={iconBtn()}><X size={16} /></button>
      } />

      <Card style={{ padding: 24, minHeight: 180, textAlign: "center", lineHeight: 2.4 }}>
        {curAyah?.words.map(renderWord)}
      </Card>

      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginTop: 14 }}>
        <span style={{
          width: 8, height: 8, borderRadius: "50%",
          background: engine.status === "listening" ? "var(--primary)" : engine.status === "error" ? "var(--danger)" : "var(--textDim)",
          boxShadow: engine.status === "listening" ? "0 0 0 4px var(--accentSoft)" : "none", transition: "box-shadow .6s ease",
        }} />
        <span style={{ fontSize: 12.5, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>{statusLabel}</span>
      </div>
      {engine.errorMsg && <p style={{ textAlign: "center", fontSize: 12, color: "var(--danger)", marginTop: 6 }}>{engine.errorMsg}</p>}

      <div style={{ display: "flex", justifyContent: "center", gap: 10, marginTop: 16, flexWrap: "wrap" }}>
        <button onClick={() => (playingAudio ? stopAyahAudio() : playAyahAudio(curAyah))} style={btnGhost()}>
          {playingAudio ? <Pause size={14} /> : <Volume2 size={14} />} استماع
        </button>
        {mode !== "read" && (
          <>
            <button onClick={() => (engine.status === "paused" ? engine.resume() : engine.pause())} style={btnGhost()}>
              {engine.status === "paused" ? <Play size={14} /> : <SkipBack size={14} />} {engine.status === "paused" ? "استئناف" : "إيقاف مؤقت"}
            </button>
            <button onClick={engine.retryCurrentAyah} style={btnGhost()}><Repeat size={14} /> إعادة الآية</button>
            <button onClick={engine.useHint} style={btnGhost()}>💡 تلميح</button>
          </>
        )}
      </div>
      {audioError && <p style={{ textAlign: "center", fontSize: 11.5, color: "var(--danger)", marginTop: 8 }}>{audioError}</p>}

      <div style={{ display: "flex", gap: 10, marginTop: 20 }}>
        {mode === "read" ? (
          <button onClick={() => setStage("result")} style={{ ...btnPrimarySmall(), flex: 1 }}>إنهاء</button>
        ) : (
          <>
            {engine.status !== "listening" && engine.status !== "paused" && (
              <button onClick={engine.start} style={{ ...btnPrimarySmall(), flex: 1 }}><Mic size={14} /> ابدأ التسميع</button>
            )}
            <button onClick={engine.finish} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}>✓ إنهاء التسميع</button>
          </>
        )}
      </div>
      <p style={{ textAlign: "center", fontSize: 11, color: "var(--textDim)", marginTop: 12, fontFamily: "'Cairo', sans-serif" }}>
        استماع مستمر — لا حاجة لتسجيل ثم إيقاف؛ تتبّع الكلمات يحدث أثناء كلامك.
      </p>
    </div>
  );
}

/* =========================================================================
   Ibadah — prayers, sunnah, qiyam, charity
   ========================================================================= */

/* =========================================================================
   حاسبة الزكاة — أداة إرشادية مبسّطة (نصاب الذهب + نسبة ٢.٥٪ الشائعة على الأموال
   النقدية والذهب والفضة وعروض التجارة). سعر الذهب بيتغيّر يوميًا فمفيش طريقة
   موثوقة نجيبه بيها تلقائيًا بدون مفتاح API، فبنطلبه من المستخدمة نفسها.
   ========================================================================= */
function ZakatCalculator({ onClose }) {
  const [cash, setCash] = useState("");
  const [gold, setGold] = useState("");
  const [silver, setSilver] = useState("");
  const [business, setBusiness] = useState("");
  const [debts, setDebts] = useState("");
  const [goldPricePerGram, setGoldPricePerGram] = useState("");

  const n = (v) => Math.max(0, Number(v) || 0);
  const totalWealth = n(cash) + n(gold) + n(silver) + n(business) - n(debts);
  const nisabGold = n(goldPricePerGram) * 85; // نصاب الذهب التقريبي: ٨٥ جرام ذهب عيار ٢٤
  const canCompute = n(goldPricePerGram) > 0;
  const meetsNisab = canCompute && totalWealth >= nisabGold;
  const zakatDue = meetsNisab ? totalWealth * 0.025 : 0;

  return (
    <Card style={{ padding: 18, marginTop: 14 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, fontWeight: 700, color: "var(--text)" }}>🧮 حاسبة الزكاة</span>
        <X size={16} color="var(--textDim)" style={{ cursor: "pointer" }} onClick={onClose} />
      </div>

      <p style={{ fontSize: 11.5, color: "var(--textDim)", lineHeight: 1.8, marginBottom: 14 }}>
        زكاة المال تجب إذا بلغ إجمالي ما تملكينه (بعد خصم الديون) نصاب الذهب (٨٥ جرامًا) واستمر معكِ حولًا كاملًا (سنة هجرية)، وتُحسب بنسبة ٢.٥٪.
      </p>

      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        <label style={fieldLabel()}>سعر جرام الذهب اليوم (بعملتك)
          <input type="number" inputMode="decimal" value={goldPricePerGram} onChange={(e) => setGoldPricePerGram(e.target.value)} placeholder="مثال: 3500" style={inputStyle()} />
        </label>
        <label style={fieldLabel()}>النقود (كاش + أرصدة بنكية)
          <input type="number" inputMode="decimal" value={cash} onChange={(e) => setCash(e.target.value)} placeholder="0" style={inputStyle()} />
        </label>
        <label style={fieldLabel()}>قيمة الذهب المدّخر
          <input type="number" inputMode="decimal" value={gold} onChange={(e) => setGold(e.target.value)} placeholder="0" style={inputStyle()} />
        </label>
        <label style={fieldLabel()}>قيمة الفضة المدّخرة
          <input type="number" inputMode="decimal" value={silver} onChange={(e) => setSilver(e.target.value)} placeholder="0" style={inputStyle()} />
        </label>
        <label style={fieldLabel()}>عروض التجارة (بضاعة معدّة للبيع)
          <input type="number" inputMode="decimal" value={business} onChange={(e) => setBusiness(e.target.value)} placeholder="0" style={inputStyle()} />
        </label>
        <label style={fieldLabel()}>ديون مستحقة عليكِ (تُخصم)
          <input type="number" inputMode="decimal" value={debts} onChange={(e) => setDebts(e.target.value)} placeholder="0" style={inputStyle()} />
        </label>
      </div>

      {canCompute && (
        <Card style={{ padding: 16, marginTop: 16, background: meetsNisab ? "var(--accentSoft)" : "var(--surfaceAlt)" }}>
          <div style={{ fontSize: 11.5, color: "var(--textDim)", marginBottom: 4 }}>نصاب الزكاة (٨٥ جم ذهب) ≈ {nisabGold.toLocaleString()}</div>
          <div style={{ fontSize: 11.5, color: "var(--textDim)", marginBottom: 10 }}>إجمالي مالك الزكوي ≈ {totalWealth.toLocaleString()}</div>
          {meetsNisab ? (
            <>
              <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, fontWeight: 700, color: "var(--text)" }}>الزكاة الواجبة عليكِ (٢.٥٪):</div>
              <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 24, color: "var(--accent)", marginTop: 4 }}>{zakatDue.toLocaleString(undefined, { maximumFractionDigits: 2 })}</div>
            </>
          ) : (
            <div style={{ fontSize: 12.5, color: "var(--text)" }}>مالك لسه ما بلغش النصاب، فلا زكاة واجبة عليكِ حاليًا 🤍</div>
          )}
        </Card>
      )}

      <p style={{ fontSize: 10.5, color: "var(--textDim)", marginTop: 12, lineHeight: 1.7 }}>
        ملاحظة: أداة إرشادية مبسّطة (نصاب الذهب ونسبة ٢.٥٪ العامة على النقد والذهب والفضة وعروض التجارة فقط) ولا تغني عن سؤال أهل العلم في حالتك الخاصة — زكاة الأنعام والزروع والمعادن لها أحكام مختلفة.
      </p>
    </Card>
  );
}

function Ibadah({ day, updateDay, goTo }) {
  const [showZakat, setShowZakat] = useState(false);
  const toggleArr = (key, i) => {
    const arr = [...day[key]];
    arr[i] = !arr[i];
    updateDay({ [key]: arr });
  };
  const toggleMulti = (key, val) => {
    const arr = day[key].includes(val) ? day[key].filter((x) => x !== val) : [...day[key], val];
    updateDay({ [key]: arr });
  };

  const prayersDone = day.prayers.filter(Boolean).length;
  const sunnahDone = day.sunnah.filter(Boolean).length;
  const qiyamDone = (day.qiyam || []).length > 0;
  const totalTasks = PRAYERS.length + SUNNAH.length + 1 + 1; // صلوات + سنن + قيام + صدقة
  const doneTasks = prayersDone + sunnahDone + (qiyamDone ? 1 : 0) + (day.charity.length > 0 ? 1 : 0);
  const pct = day.excused ? dayCompletion(day) : Math.round((doneTasks / totalTasks) * 100);

  return (
    <div>
      <SectionTitle>عبادتي</SectionTitle>

      {/* تنقّل واضح بين عباداتي والأذكار بدل إخفاء الأذكار في زر صغير */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16 }}>
        <div style={{
          border: "1px solid var(--accent)", background: "var(--accentSoft)", color: "var(--accent)",
          borderRadius: 15, padding: "11px 12px", display: "flex", alignItems: "center", justifyContent: "center",
          gap: 7, fontFamily: "'Cairo', sans-serif", fontSize: 12.5, fontWeight: 800, boxShadow: "0 5px 18px rgba(0,0,0,.04)"
        }}>
          🤲 عباداتي
        </div>
        <button onClick={() => goTo?.("adhkar")} style={{
          border: "1px solid var(--border)", background: "var(--surface)", color: "var(--text)",
          borderRadius: 15, padding: "11px 12px", display: "flex", alignItems: "center", justifyContent: "center",
          gap: 7, fontFamily: "'Cairo', sans-serif", fontSize: 12.5, fontWeight: 800, cursor: "pointer",
          transition: "all .2s ease"
        }}>
          📿 الأذكار
        </button>
      </div>

      {/* لوحة إنجاز اليوم — أول حاجة تشوفها تبقى مفيدة فورًا */}
      <Card className="anisk-stagger-1" style={{ padding: 22, marginBottom: 22, background: "linear-gradient(160deg, var(--surface), var(--accentSoft))" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 18 }}>
          <div style={{ position: "relative", width: 92, height: 92, flexShrink: 0 }}>
            <Ring percent={pct} size={92} stroke={8} />
            <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
              <span style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 21, color: "var(--accent)", lineHeight: 1 }}>{pct}٪</span>
            </div>
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 16, color: "var(--text)", marginBottom: 5 }}>
              {day.excused ? "يوم عذر شرعي 🌸" : pct === 100 ? "ما شاء الله، يوم مكتمل! 🤍" : "إنجازك اليوم"}
            </div>
            <div style={{ fontSize: 12, color: "var(--textDim)", lineHeight: 1.7 }}>
              {day.excused
                ? "عباداتك غير المرتبطة بالصلاة محسوبة هنا برفق"
                : `${doneTasks} من ${totalTasks} عبادة اتسجّلت النهارده`}
            </div>
            {!day.excused && (
              <div style={{ display: "flex", gap: 10, marginTop: 10, fontSize: 10.5, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>
                <span>🕌 {prayersDone}/٥</span>
                <span>✨ {sunnahDone}/{SUNNAH.length}</span>
                <span>{day.qiyam.length > 0 ? "🌙 قيام ✓" : "🌙 قيام —"}</span>
                <span>{day.charity.length > 0 ? "🤲 صدقة ✓" : "🤲 صدقة —"}</span>
              </div>
            )}
          </div>
        </div>
      </Card>

      {/* لوحة الصلوات: 5 أعمدة ثابتة × 3 صفوف — فرض / سنة / جماعة.
          التصميم يحافظ على كل البيانات الحالية لكن يعرضها في مساحة صغيرة ومرتبة بدل
          ما كل صلاة تأخذ صفًا كاملًا. */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "0 2px 10px", opacity: day.excused ? 0.55 : 1 }}>
        <div>
          <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", fontWeight: 700 }}>🕌 صلواتي اليوم</div>
          <div style={{ fontSize: 10.5, color: "var(--textDim)", marginTop: 2 }}>فرض · سنة · جماعة</div>
        </div>
        <span style={{ fontSize: 12.5, color: "var(--accent)", fontFamily: "'Cairo', sans-serif", fontWeight: 700 }}>{day.excused ? "غير واجبة اليوم" : `${prayersDone} / 5 فرض`}</span>
      </div>
      {day.excused ? (
        <Card style={{ padding: 18, textAlign: "center", marginBottom: 14 }}>
          <p style={{ fontSize: 12.5, color: "var(--textDim)", margin: 0 }}>لا قضاء للصلاة، اطمئني 🤍</p>
        </Card>
      ) : (
        <Card style={{ padding: 10, marginBottom: 14, overflow: "hidden" }}>
          <div style={{ display: "grid", gridTemplateColumns: "46px repeat(5, minmax(0, 1fr))", gap: 5, direction: "rtl" }}>
            <div />
            {PRAYERS.map((p, i) => {
              const Icon = PRAYER_TIME_ICONS[i];
              return (
                <div key={p} style={{ minWidth: 0, textAlign: "center", padding: "7px 2px 8px", borderRadius: 11, background: "var(--surfaceAlt)" }}>
                  <Icon size={15} color="var(--accent)" style={{ marginBottom: 3 }} />
                  <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 10.5, fontWeight: 700, color: "var(--text)", whiteSpace: "nowrap" }}>{p}</div>
                </div>
              );
            })}

            {[["فرض", "prayers"], ["سنة", "sunnah"], ["جماعة", "jamaah"]].map(([rowLabel, key]) => (
              <React.Fragment key={key}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Cairo', sans-serif", fontSize: 9.5, fontWeight: 700, color: "var(--textDim)", padding: "6px 0" }}>{rowLabel}</div>
                {PRAYERS.map((p, i) => {
                  const hasSunnah = key !== "sunnah" || PRAYER_SUNNAH_LINKS[i].length > 0;
                  const isSunnah = key === "sunnah";
                  const done = key === "jamaah" ? !!(day.jamaah || [])[i] : !!day[key][i];
                  const toggle = () => {
                    if (isSunnah) {
                      const links = PRAYER_SUNNAH_LINKS[i];
                      if (!links.length) return;
                      const next = [...day.sunnah];
                      if (links.length === 1) next[links[0].sunnahIndex] = !next[links[0].sunnahIndex];
                      else next[links[0].sunnahIndex] = !next[links[0].sunnahIndex];
                      updateDay({ sunnah: next });
                    } else {
                      toggleArr(key, i);
                    }
                  };
                  const sunnahLinks = isSunnah ? PRAYER_SUNNAH_LINKS[i] : [];
                  const sunnahDoneCount = sunnahLinks.filter((x) => !!day.sunnah[x.sunnahIndex]).length;

                  if (isSunnah) {
                    return (
                      <div key={`${key}-${p}`} style={{
                        minWidth: 0, minHeight: 43, borderRadius: 11, border: `1px solid ${sunnahDoneCount > 0 ? "var(--accent)" : "var(--border)"}`,
                        background: sunnahDoneCount > 0 ? "var(--accentSoft)" : "var(--surface)", display: "flex", alignItems: "center", justifyContent: "center",
                        gap: 3, padding: 4, opacity: hasSunnah ? 1 : 0.55,
                      }}>
                        {sunnahLinks.length === 0 ? (
                          <span style={{ fontSize: 11, color: "var(--border)" }}>—</span>
                        ) : (
                          sunnahLinks.map((link) => {
                            const linkDone = !!day.sunnah[link.sunnahIndex];
                            const short = link.label.includes("قبل") ? "ق" : "ب";
                            return (
                              <button
                                key={link.sunnahIndex}
                                title={link.label}
                                onClick={() => {
                                  const next = [...day.sunnah];
                                  next[link.sunnahIndex] = !next[link.sunnahIndex];
                                  updateDay({ sunnah: next });
                                }}
                                style={{
                                  width: 25, height: 30, borderRadius: 8, border: `1px solid ${linkDone ? "var(--accent)" : "var(--border)"}`,
                                  background: linkDone ? "var(--accent)" : "var(--surfaceAlt)", color: linkDone ? "var(--onPrimary)" : "var(--textDim)",
                                  cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 0, padding: 0,
                                  fontFamily: "'Cairo', sans-serif", fontSize: 8.5, fontWeight: 800,
                                }}
                              >
                                <span style={{ fontSize: 10 }}>{linkDone ? "✓" : short}</span>
                                <span style={{ fontSize: 6.5, opacity: .85 }}>{short === "ق" ? "قبل" : "بعد"}</span>
                              </button>
                            );
                          })
                        )}
                      </div>
                    );
                  }

                  return (
                    <button key={`${key}-${p}`} onClick={toggle} disabled={!hasSunnah} style={{
                      minWidth: 0, minHeight: 43, borderRadius: 11, border: `1px solid ${done ? "var(--accent)" : "var(--border)"}`,
                      background: done ? "var(--accentSoft)" : "var(--surface)", color: done ? "var(--accent)" : hasSunnah ? "var(--textDim)" : "var(--border)",
                      cursor: hasSunnah ? "pointer" : "default", display: "flex", alignItems: "center", justifyContent: "center",
                      fontFamily: "'Cairo', sans-serif", padding: 3, position: "relative", opacity: hasSunnah ? 1 : 0.55,
                    }}>
                      {done ? <CheckCircle2 size={17} /> : <span style={{ width: 9, height: 9, borderRadius: "50%", border: "1.5px solid currentColor" }} />}
                    </button>
                  );
                })}
              </React.Fragment>
            ))}
          </div>
          <div style={{ marginTop: 8, paddingTop: 8, borderTop: "1px solid var(--border)", fontSize: 9.5, color: "var(--textDim)", textAlign: "center", fontFamily: "'Cairo', sans-serif" }}>
            اضغطي على الخانة لتسجيلها · سنة الظهر تشمل قبل/بعد الظهر
          </div>
        </Card>
      )}


      {gregorianToHijri(new Date()).month === 9 && (
        <>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "26px 2px 10px" }}>
            <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", fontWeight: 700 }}>🌙 قيام رمضان (التراويح)</span>
          </div>
          <Card style={{ overflow: "hidden" }}>
            <CheckRow label="صلاة التراويح" checked={!!day.taraweeh} onToggle={() => updateDay({ taraweeh: !day.taraweeh })} last />
          </Card>
        </>
      )}

      {new Date().getDay() === 5 && (
        <>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "26px 2px 10px" }}>
            <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", fontWeight: 700 }}>✨ خصائص يوم الجمعة</span>
            <span style={{ fontSize: 12.5, color: "var(--accent)", fontFamily: "'Cairo', sans-serif", fontWeight: 700 }}>{(day.fridayTasks || []).length} / {FRIDAY_TASKS.length}</span>
          </div>
          <Card style={{ overflow: "hidden" }}>
            {FRIDAY_TASKS.map((t, i) => (
              <CheckRow
                key={t.id}
                label={t.label}
                checked={(day.fridayTasks || []).includes(t.id)}
                onToggle={() => toggleMulti("fridayTasks", t.id)}
                last={i === FRIDAY_TASKS.length - 1}
              />
            ))}
          </Card>
        </>
      )}

      {!day.excused && (() => {
        const reasons = fastingRecommendationFor(new Date());
        if (reasons.length === 0) return null;
        return (
          <>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "26px 2px 10px" }}>
              <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", fontWeight: 700 }}>🌙 صيام تطوّع</span>
            </div>
            <Card
              onClick={() => updateDay({ fasting: !day.fasting })}
              className={day.fasting ? "anisk-pop" : ""}
              style={{ padding: 16, cursor: "pointer", display: "flex", alignItems: "center", gap: 14, background: day.fasting ? "var(--accentSoft)" : "var(--surface)", transition: "background .25s ease" }}
            >
              <div style={{
                width: 40, height: 40, borderRadius: "50%", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center",
                background: day.fasting ? "var(--accent)" : "var(--surfaceAlt)", transition: "background .25s ease",
              }}>
                <span style={{ fontSize: 18 }}>🌙</span>
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, fontWeight: 700, color: "var(--text)" }}>
                  النهارده يوم مستحب للصيام ({reasons.join(" و")})
                </div>
                <div style={{ fontSize: 11.5, color: "var(--textDim)", marginTop: 2 }}>دوسي هنا لو صايمة النهارده</div>
              </div>
              {day.fasting ? <CheckCircle2 size={20} color="var(--accent)" /> : <Circle size={16} color="var(--border)" />}
            </Card>
          </>
        );
      })()}

      {/* نوافل إضافية — لوحة صغيرة موحّدة بدل بطاقات طويلة */}
      <div style={{ margin: "22px 2px 10px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div>
          <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", fontWeight: 800 }}>🌙 نوافلي الإضافية</div>
          <div style={{ fontSize: 10.5, color: "var(--textDim)", marginTop: 2 }}>قيام الليل والضحى</div>
        </div>
        <span style={{ fontSize: 10.5, color: "var(--textDim)" }}>اختاري ما أنجزتِه</span>
      </div>

      <Card style={{ padding: 10, overflow: "hidden" }}>
        <div style={{
          display: "grid", gridTemplateColumns: "62px repeat(4, minmax(0, 1fr))", gap: 6, direction: "rtl", alignItems: "stretch"
        }}>
          <div />
          {[
            ["🕌", "صلاة"],
            ["📿", "استغفار"],
            ["🤲", "دعاء"],
            ["📖", "تلاوة قرآن"],
          ].map(([icon, label]) => (
            <div key={label} style={{ textAlign: "center", padding: "7px 2px", borderRadius: 10, background: "var(--surfaceAlt)", border: "1px solid var(--border)" }}>
              <div style={{ fontSize: 14, lineHeight: 1.1 }}>{icon}</div>
              <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 8.5, fontWeight: 800, color: "var(--text)", marginTop: 4, whiteSpace: "nowrap" }}>{label}</div>
            </div>
          ))}

          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", padding: 4, borderRadius: 10, background: "var(--surfaceAlt)", fontFamily: "'Cairo', sans-serif", fontSize: 9.5, fontWeight: 800, color: "var(--textDim)" }}>قيام الليل</div>
          {["صلاة", "استغفار", "دعاء", "تلاوة القرآن"].map((o) => {
            const done = (day.qiyam || []).includes(o);
            return (
              <button key={o} onClick={() => toggleMulti("qiyam", o)} aria-label={`قيام الليل: ${o}`} style={{
                minHeight: 44, borderRadius: 11, border: `1px solid ${done ? "var(--accent)" : "var(--border)"}`,
                background: done ? "var(--accentSoft)" : "var(--surface)", color: done ? "var(--accent)" : "var(--textDim)",
                cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", transition: "all .2s ease", padding: 3
              }}>
                {done ? <CheckCircle2 size={17} /> : <span style={{ width: 10, height: 10, borderRadius: "50%", border: "1.5px solid currentColor" }} />}
              </button>
            );
          })}

          <div style={{ gridColumn: "1 / -1", height: 1, background: "var(--border)", margin: "2px 0" }} />

          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", padding: 4, borderRadius: 10, background: "var(--surfaceAlt)", fontFamily: "'Cairo', sans-serif", fontSize: 9.5, fontWeight: 800, color: "var(--textDim)" }}>☀️ الضحى</div>
          <button onClick={() => updateDay({ duha: !day.duha })} style={{
            gridColumn: "2 / -1", minHeight: 44, borderRadius: 11, border: `1px solid ${day.duha ? "var(--accent)" : "var(--border)"}`,
            background: day.duha ? "var(--accentSoft)" : "var(--surface)", color: day.duha ? "var(--accent)" : "var(--textDim)",
            cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 12px",
            fontFamily: "'Cairo', sans-serif", fontSize: 11, fontWeight: 800
          }}>
            <span>{day.duha ? "تم تسجيل صلاة الضحى اليوم" : "تسجيل صلاة الضحى"}</span>
            {day.duha ? <CheckCircle2 size={17} /> : <span style={{ width: 10, height: 10, borderRadius: "50%", border: "1.5px solid currentColor" }} />}
          </button>
        </div>
      </Card>
      <p style={{ fontSize: 11, color: "var(--textDim)", margin: "7px 4px", fontFamily: "'Cairo', sans-serif" }}>ولو ركعتين — لا بأس بالقليل المستمر 🤍</p>

      <div style={{ margin: "26px 2px 10px" }}>
        <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14.5, color: "var(--text)", fontWeight: 700 }}>🤲 صدقة في يومي</span>
      </div>
      <Card style={{ padding: 16 }}>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
          {CHARITY_OPTIONS.map((o) => (
            <Pill key={o} active={day.charity.includes(o)} onClick={() => toggleMulti("charity", o)}>{o}</Pill>
          ))}
        </div>
      </Card>

      <button
        onClick={() => setShowZakat((v) => !v)}
        style={{ ...btnGhost(), width: "100%", justifyContent: "center", marginTop: 12 }}
      >
        🧮 حاسبة الزكاة
      </button>
      {showZakat && <ZakatCalculator onClose={() => setShowZakat(false)} />}

      <ExcusedDayToggle day={day} updateDay={updateDay} />
      <div style={{ height: 24 }} />
    </div>
  );
}

// أقل بروزًا وموضوعة أسفل الصفحة، تُفتح بضغطة لمن يحتاجها فقط
function ExcusedDayToggle({ day, updateDay }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ marginTop: 26 }}>
      <button onClick={() => setOpen((o) => !o)} style={{
        background: "none", border: "none", cursor: "pointer", color: "var(--textDim)",
        fontFamily: "'Cairo', sans-serif", fontSize: 11.5, padding: 0, display: "flex", alignItems: "center", gap: 4,
      }}>
        🌸 عذر شرعي {open ? <ChevronDown size={12} /> : <ChevronLeft size={12} />}
      </button>
      {open && (
        <Card style={{ padding: 14, marginTop: 8 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div style={{ fontSize: 11.5, color: "var(--textDim)", lineHeight: 1.7, maxWidth: 220 }}>
              الصلاة والصيام غير واجبين عليكِ اليوم — مفيش أي تأثير على السلسلة المتتالية.
            </div>
            <Toggle checked={day.excused} onChange={(v) => updateDay({ excused: v })} />
          </div>
        </Card>
      )}
    </div>
  );
}

/* =========================================================================
   Adhkar
   ========================================================================= */

const ADHKAR_ICON = { sunrise: <Sunrise size={17} />, sunset: <Sunset size={17} />, star: <Star size={17} />, moon: <Moon size={17} /> };

// قراءة صوتية باستخدام محرك المتصفح. تحميل الأصوات بيحصل مبكرًا وبشكل غير متزامن
// (module-level)، فلما المستخدمة تدوس على الزرار، speak() بيتنفّذ فورًا وبشكل
// متزامن داخل نفس الـ click handler — ده ضروري جدًا لأن أغلب المتصفحات (خصوصًا
// سفاري) بترفض تشغيل صوت مش مربوط مباشرة بضغطة المستخدم (نفس سياسة منع autoplay).
// النسخة اللي فاتت كانت بتستنى (await) تحميل الأصوات قبل النداء، وده كان بيكسر
// الارتباط المباشر بالضغطة فيفشل التشغيل بصمت — ده السبب الحقيقي للعطل.
let cachedVoices = typeof speechSynthesis !== "undefined" ? speechSynthesis.getVoices() : [];
if (typeof speechSynthesis !== "undefined") {
  speechSynthesis.onvoiceschanged = () => { cachedVoices = speechSynthesis.getVoices(); };
}
function speakArabic(text, onEnd, onError) {
  if (typeof speechSynthesis === "undefined") { if (onError) onError("unsupported"); return false; }
  if (cachedVoices.length === 0) cachedVoices = speechSynthesis.getVoices(); // محاولة أخيرة لحظة الضغط نفسها
  const arabicVoice = cachedVoices.find((v) => v.lang && v.lang.toLowerCase().startsWith("ar"));
  try {
    speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = arabicVoice ? arabicVoice.lang : "ar-SA";
    if (arabicVoice) u.voice = arabicVoice;
    u.rate = 0.85;
    if (onEnd) u.onend = onEnd;
    u.onerror = () => { if (onError) onError("error"); };
    speechSynthesis.speak(u); // نداء متزامن مباشرة جوه الـ click handler
    if (!arabicVoice && onError) onError("no-arabic-voice");
    return true;
  } catch { if (onError) onError("error"); return false; }
}

// عنصر ذكر واحد جوّه القائمة الطويلة — نص + عدّاده الخاص + زر استماع، كلهم تحت بعض
function DhikrRow({ item, idx, totalDone, onTick, playingIdx, setPlayingIdx, ttsSupported, reciterId }) {
  const [count, setCount] = useState(0);
  const target = item.count;
  const finished = count >= target;
  const [pop, setPop] = useState(false);
  const isPlaying = playingIdx === idx;
  const [ttsError, setTtsError] = useState(null);
  const audioElRef = useRef(null);

  useEffect(() => { if (finished) onTick(idx, true); }, [finished]); // eslint-disable-line

  const tap = () => {
    if (finished) return;
    setPop(true); setTimeout(() => setPop(false), 300);
    setCount((c) => c + 1);
  };

  // لو الذكر آية قرآنية حقيقية (آية الكرسي، الإخلاص، الفلق، الناس) بنشغّل صوت
  // القارئ المختار فعليًا من نفس مصدر تلاوة القرآن — مش تخليق صوتي اصطناعي
  const reciter = RECITERS.find((r) => r.id === reciterId);
  const canUseRealAudio = item.quranRef && reciter?.edition;

  const toggleListen = () => {
    if (isPlaying) {
      if (audioElRef.current) audioElRef.current.pause();
      speechSynthesis.cancel();
      setPlayingIdx(null);
      return;
    }
    setTtsError(null);
    setPlayingIdx(idx);
    if (canUseRealAudio) {
      if (!audioElRef.current) audioElRef.current = new Audio();
      const el = audioElRef.current;
      el.onended = () => setPlayingIdx(null);
      el.onerror = () => { setTtsError("error"); setPlayingIdx(null); };
      el.src = item.quranRef.ayah
        ? ayahAudioUrl(reciter.edition, globalAyahNumberFor(item.quranRef.surah, item.quranRef.ayah))
        : surahAudioUrl(reciter.edition, item.quranRef.surah);
      el.play().catch(() => { setTtsError("error"); setPlayingIdx(null); });
    } else {
      speakArabic(item.text, () => setPlayingIdx(null), (err) => { setTtsError(err); setPlayingIdx(null); });
    }
  };

  return (
    <Card style={{ padding: 18, opacity: finished ? 0.75 : 1, border: finished ? "1px solid var(--primary)" : "1px solid var(--border)" }}>
      <p style={{ fontFamily: "'Amiri', serif", fontSize: 19, lineHeight: 1.9, color: "var(--text)", margin: "0 0 6px" }}>{item.text}</p>
      <p style={{ fontSize: 11.5, color: "var(--textDim)", margin: "0 0 12px" }}>{item.source}{canUseRealAudio ? " · صوت القارئ الحقيقي 🎙️" : ""}</p>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
        {(ttsSupported || canUseRealAudio) ? (
          <button onClick={toggleListen} style={{ ...btnGhost(), padding: "6px 12px", fontSize: 12 }}>
            {isPlaying ? "⏸ إيقاف" : "🔊 استماع"}
          </button>
        ) : <span />}
        {finished ? (
          <span style={{ color: "var(--primary)", fontFamily: "'Cairo', sans-serif", fontWeight: 700, fontSize: 13 }}>✓ تم ({target})</span>
        ) : (
          <button
            onClick={tap}
            style={{
              width: 56, height: 56, borderRadius: "50%", border: "none", cursor: "pointer",
              background: "linear-gradient(135deg, var(--primary), color-mix(in srgb, var(--primary) 78%, black))",
              color: "var(--onPrimary)", fontFamily: "'Reem Kufi', sans-serif", fontSize: 15,
              transform: pop ? "scale(1.12)" : "scale(1)", transition: "transform .15s ease",
              boxShadow: "0 3px 10px color-mix(in srgb, var(--primary) 30%, transparent)",
            }}
          >
            {count}/{target}
          </button>
        )}
      </div>
      {ttsError === "no-arabic-voice" && (
        <p style={{ fontSize: 10.5, color: "var(--textDim)", marginTop: 8 }}>جهازك مفيهوش صوت عربي مثبّت، فهيقرأ بلكنة مختلفة أو ما يتكلمش. جربي من موبايل تاني أو فعّلي صوت عربي من إعدادات جهازك.</p>
      )}
      {ttsError === "unsupported" && (
        <p style={{ fontSize: 10.5, color: "var(--textDim)", marginTop: 8 }}>متصفحك مش بيدعم القراءة الصوتية — جربي كروم أو سفاري محدّث.</p>
      )}
    </Card>
  );
}

/* =========================================================================
   السبحة الإلكترونية — عداد تسبيح عام غير مرتبط بفئة أذكار معيّنة، بهدف
   قابل للتغيير (٣٣/٩٩/١٠٠) وذكر قابل للاختيار من قائمة شائعة.
   ========================================================================= */
// عدّاد السبحة بيتحفظ لكل ذكر لوحده — عشان لو رجعتِ لذكر سبق وعديتي فيه، تكمّلي من
// نفس الرقم بدل ما يبدأ من الصفر في كل مرة.
async function loadTasbihCounts() {
  try {
    const res = await window.storage.get("unisk:tasbih-counts", false);
    return res?.value ? JSON.parse(res.value) : {};
  } catch { return {}; }
}
async function saveTasbihCounts(map) {
  try { await window.storage.set("unisk:tasbih-counts", JSON.stringify(map), false); } catch { /* best effort */ }
}

function TasbihCounter({ onBack }) {
  const [counts, setCounts] = useState({}); // { [dhikrText]: number } — محفوظة لكل ذكر لوحده
  const [countsLoaded, setCountsLoaded] = useState(false);
  const [target, setTarget] = useState(33);
  const [dhikrText, setDhikrText] = useState("سبحان الله");
  const presets = ["سبحان الله", "الحمد لله", "الله أكبر", "لا إله إلا الله", "أستغفر الله", "لا حول ولا قوة إلا بالله"];
  const [pop, setPop] = useState(false);

  useEffect(() => { loadTasbihCounts().then((c) => { setCounts(c); setCountsLoaded(true); }); }, []);
  useEffect(() => { if (countsLoaded) saveTasbihCounts(counts); }, [counts, countsLoaded]);

  const count = counts[dhikrText] || 0;

  const tap = () => {
    setPop(true); setTimeout(() => setPop(false), 220);
    setCounts((c) => ({ ...c, [dhikrText]: (c[dhikrText] || 0) + 1 }));
    try { if (navigator.vibrate) navigator.vibrate(10); } catch { /* بعض الأجهزة/المتصفحات ما بتدعمش الاهتزاز */ }
  };
  const reset = () => setCounts((c) => ({ ...c, [dhikrText]: 0 }));
  const justCompletedCycle = target > 0 && count > 0 && count % target === 0;

  return (
    <div>
      <TopBarBack onBack={onBack} title="السبحة الإلكترونية" />

      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 16 }}>
        {presets.map((p) => (
          <Pill key={p} active={dhikrText === p} onClick={() => setDhikrText(p)}>{p}</Pill>
        ))}
      </div>

      <Card style={{ padding: 24, textAlign: "center", marginBottom: 16 }}>
        <div style={{ fontFamily: "'Amiri', serif", fontSize: 20, color: "var(--text)", marginBottom: 20 }}>{dhikrText}</div>
        <button
          onClick={tap}
          style={{
            width: 160, height: 160, borderRadius: "50%", border: "none", cursor: "pointer", margin: "0 auto",
            background: "linear-gradient(135deg, var(--primary), color-mix(in srgb, var(--primary) 78%, black))",
            color: "var(--onPrimary)", display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column",
            boxShadow: "0 10px 26px color-mix(in srgb, var(--primary) 35%, transparent)",
            transform: pop ? "scale(1.08)" : "scale(1)", transition: "transform .15s ease",
          }}
        >
          <span style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 44, lineHeight: 1 }}>{count}</span>
          <span style={{ fontSize: 11, opacity: 0.85, marginTop: 6 }}>دوسي هنا</span>
        </button>
        {justCompletedCycle && (
          <div className="anisk-pop" style={{ marginTop: 16, color: "var(--primary)", fontFamily: "'Cairo', sans-serif", fontWeight: 700 }}>
            ✓ أكملتِ {target} — تقبّل الله منكِ 🤍
          </div>
        )}
        {count > 0 && (
          <div style={{ marginTop: 10, fontSize: 11, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>
            العدّاد محفوظ — تقدري ترجعي له في أي وقت
          </div>
        )}
      </Card>

      <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 16 }}>
        <span style={{ fontSize: 12.5, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>الهدف:</span>
        {[33, 99, 100].map((t) => (
          <Pill key={t} active={target === t} onClick={() => setTarget(t)}>{t}</Pill>
        ))}
      </div>

      <button onClick={reset} style={{ ...btnGhost(), width: "100%", justifyContent: "center" }}>
        <Repeat size={15} /> مسح هذا العدّاد والبدء من جديد
      </button>
    </div>
  );
}

// تسجيل صوتي حقيقي وموثّق (مش تخليق صوتي) لأذكار الصباح والمساء بصوت الشيخ مشاري
// راشد العفاسي بالكامل، من موقع إسلام ويب. مش مقسّم لحظيًا لكل ذكر لوحده (محتاج
// توقيتات دقيقة مافيش مصدر موثوق بيها)، فبنشغّله كتسجيل متكامل تسمعينه بجانب
// العدّ، وده أقرب لتجربة الاستماع الحقيقية لهذا التسجيل المعروف.
const ALAFASY_ADHKAR_URL = "https://audio.islamweb.net/audio/downloadmp3.php?audioid=125063";
function AlafasyAdhkarPlayer() {
  const [status, setStatus] = useState("idle"); // idle | loading | playing | error
  const audioRef = useRef(null);
  useEffect(() => {
    const el = new Audio();
    audioRef.current = el;
    el.onplaying = () => setStatus("playing");
    el.onpause = () => setStatus((s) => (s === "error" ? s : "idle"));
    el.onerror = () => setStatus("error");
    el.onended = () => setStatus("idle");
    return () => { el.pause(); el.src = ""; };
  }, []);
  const toggle = () => {
    const el = audioRef.current;
    if (!el) return;
    if (status === "playing") { el.pause(); return; }
    setStatus("loading");
    if (!el.src) el.src = ALAFASY_ADHKAR_URL;
    el.play().catch(() => setStatus("error"));
  };
  return (
    <Card style={{ padding: 14, marginBottom: 16, display: "flex", alignItems: "center", gap: 12 }}>
      <button
        onClick={toggle}
        style={{
          width: 42, height: 42, borderRadius: "50%", border: "none", cursor: "pointer", flexShrink: 0,
          background: "var(--primary)", color: "var(--onPrimary)",
          display: "flex", alignItems: "center", justifyContent: "center",
        }}
      >
        {status === "loading" ? <Gauge size={18} /> : status === "playing" ? <Pause size={18} /> : <Play size={18} />}
      </button>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: "var(--text)" }}>🎙️ استمعي بصوت الشيخ مشاري العفاسي</div>
        <div style={{ fontSize: 11, color: "var(--textDim)" }}>{status === "error" ? "تعذّر تحميل التسجيل الآن — جرّبي تاني" : "التسجيل الكامل لأذكار الصباح والمساء"}</div>
      </div>
    </Card>
  );
}

// مكتبة أدعية بحسب الموقف — أدعية معروفة وموثّقة من القرآن والسنة، كل دعاء مذكور
