/* =========================================================================
   Journey — weekly overview, streak, goals
   ========================================================================= */

function last7Days(days) {
  const out = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const key = todayKey(d);
    out.push({ key, label: d.toLocaleDateString("ar-EG", { weekday: "short" }), pct: dayCompletion(days[key]) });
  }
  return out;
}

/* =========================================================================
   Prayer Times — standalone tab. Defaults to Cairo until the user grants
   precise location; real geolocation + original astronomical calculation.
   ========================================================================= */

// إحداثيات الكعبة المشرفة (مكة المكرمة) — لحساب اتجاه القبلة بمعادلة الجَيَبة الملاحية (great-circle bearing)
const KAABA_LAT = 21.4225, KAABA_LON = 39.8262;
function qiblaBearing(lat, lon) {
  const toRad = (d) => (d * Math.PI) / 180;
  const toDeg = (r) => (r * 180) / Math.PI;
  const φ1 = toRad(lat), φ2 = toRad(KAABA_LAT);
  const Δλ = toRad(KAABA_LON - lon);
  const y = Math.sin(Δλ) * Math.cos(φ2);
  const x = Math.cos(φ1) * Math.sin(φ2) - Math.sin(φ1) * Math.cos(φ2) * Math.cos(Δλ);
  return (toDeg(Math.atan2(y, x)) + 360) % 360; // درجة الاتجاه من الشمال الحقيقي (0-360)
}

function QiblaScreen({ prefs, onBack }) {
  const [heading, setHeading] = useState(null); // اتجاه الجهاز الحالي (بوصلة الجهاز)
  const [permState, setPermState] = useState("idle"); // idle | granted | denied | unsupported
  const loc = prefs.location || {};
  const bearing = (loc.lat != null && loc.lon != null) ? qiblaBearing(loc.lat, loc.lon) : null;

  const enableCompass = async () => {
    if (typeof DeviceOrientationEvent === "undefined") { setPermState("unsupported"); return; }
    try {
      if (typeof DeviceOrientationEvent.requestPermission === "function") {
        const res = await DeviceOrientationEvent.requestPermission();
        if (res !== "granted") { setPermState("denied"); return; }
      }
      setPermState("granted");
      const handler = (e) => {
        const h = e.webkitCompassHeading != null ? e.webkitCompassHeading : (e.alpha != null ? 360 - e.alpha : null);
        if (h != null) setHeading(h);
      };
      window.addEventListener("deviceorientationabsolute", handler, true);
      window.addEventListener("deviceorientation", handler, true);
    } catch {
      setPermState("denied");
    }
  };

  // زاوية دوران السهم: فرق اتجاه القبلة عن اتجاه الجهاز الحالي (لو البوصلة شغالة)، وإلا زاوية القبلة من الشمال مباشرة
  const arrowRotation = heading != null && bearing != null ? bearing - heading : bearing;

  return (
    <div>
      <TopBarBack onBack={onBack} title="اتجاه القبلة" />
      {bearing == null ? (
        <EmptyState icon={<Compass size={26} />} title="فعّلي الموقع من صفحة الصلاة أولًا لحساب اتجاه القبلة" />
      ) : (
        <>
          <Card style={{ padding: 30, display: "flex", flexDirection: "column", alignItems: "center", gap: 18 }}>
            <div style={{ position: "relative", width: 220, height: 220 }}>
              <svg width="220" height="220" viewBox="0 0 220 220" style={{ position: "absolute", inset: 0 }}>
                <circle cx="110" cy="110" r="104" fill="none" stroke="var(--border)" strokeWidth="2" />
                <circle cx="110" cy="110" r="88" fill="none" stroke="var(--border)" strokeWidth="1" opacity="0.5" />
                {Array.from({ length: 36 }, (_, i) => {
                  const a = (i * 10 * Math.PI) / 180;
                  const long = i % 9 === 0;
                  const r1 = long ? 92 : 98, r2 = 104;
                  return (
                    <line key={i}
                      x1={110 + r1 * Math.sin(a)} y1={110 - r1 * Math.cos(a)}
                      x2={110 + r2 * Math.sin(a)} y2={110 - r2 * Math.cos(a)}
                      stroke="var(--textDim)" strokeWidth={long ? 1.5 : 0.75} opacity={long ? 0.7 : 0.35}
                    />
                  );
                })}
                <text x="110" y="24" textAnchor="middle" fontSize="13" fill="var(--textDim)" fontFamily="Cairo, sans-serif">ش</text>
                <text x="110" y="204" textAnchor="middle" fontSize="13" fill="var(--textDim)" fontFamily="Cairo, sans-serif">ج</text>
                <text x="16" y="115" textAnchor="middle" fontSize="13" fill="var(--textDim)" fontFamily="Cairo, sans-serif">غ</text>
                <text x="204" y="115" textAnchor="middle" fontSize="13" fill="var(--textDim)" fontFamily="Cairo, sans-serif">ش.ق</text>
              </svg>
              <div style={{
                position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center",
                transform: `rotate(${arrowRotation}deg)`, transition: "transform .25s ease",
              }}>
                <svg width="60" height="180" viewBox="0 0 60 180">
                  <polygon points="30,4 44,60 30,46 16,60" fill="var(--accent)" />
                  <line x1="30" y1="60" x2="30" y2="150" stroke="var(--textDim)" strokeWidth="2" opacity="0.5" />
                  <text x="30" y="30" textAnchor="middle" fontSize="18" fill="var(--onPrimary)">🕋</text>
                </svg>
              </div>
            </div>
            <div style={{ textAlign: "center" }}>
              <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 22, color: "var(--accent)" }}>{Math.round(bearing)}°</div>
              <div style={{ fontSize: 12, color: "var(--textDim)" }}>اتجاه القبلة من الشمال الجغرافي</div>
            </div>
          </Card>

          {permState !== "granted" && (
            <button onClick={enableCompass} style={{ ...btnPrimary(), marginTop: 16 }}>
              📱 تفعيل بوصلة الجهاز (يوجّه السهم تلقائيًا وانتِ بتتحركي)
            </button>
          )}
          {permState === "granted" && (
            <p style={{ textAlign: "center", fontSize: 12, color: "var(--textDim)", marginTop: 12 }}>
              حركي جهازك وثبّتيه أفقيًا — السهم بيشاور ناحية الكعبة مباشرة.
            </p>
          )}
          {permState === "denied" && (
            <p style={{ textAlign: "center", fontSize: 12, color: "var(--danger)", marginTop: 12 }}>
              محتاجين إذن الوصول لبوصلة الجهاز. لو رفضتيه بالغلط، فعّليه من إعدادات المتصفح.
            </p>
          )}
          {permState === "unsupported" && (
            <p style={{ textAlign: "center", fontSize: 12, color: "var(--textDim)", marginTop: 12 }}>
              جهازك أو متصفحك مش بيدعم البوصلة، بس الرقم فوق (اتجاه القبلة بالدرجة من الشمال) هيفيدك بالبوصلة العادية.
            </p>
          )}
        </>
      )}
    </div>
  );
}

function PrayerTimesView({ prefs, updatePrefs, reminders, tr }) {
  const [qiblaOpen, setQiblaOpen] = useState(false);
  const PRAYER_ROWS = [
    ["الفجر", "fajr"], ["الشروق", "sunrise"], ["الظهر", "dhuhr"],
    ["العصر", "asr"], ["المغرب", "maghrib"], ["العشاء", "isha"],
  ];
  const loc = prefs.location || {};

  if (qiblaOpen) return <QiblaScreen prefs={prefs} onBack={() => setQiblaOpen(false)} />;

  return (
    <div>
      <SectionTitle right={<button onClick={() => setQiblaOpen(true)} style={btnGhost()}><Compass size={14} /> القبلة</button>}>{tr("prayerTimesTitle")}</SectionTitle>

      <Card style={{ padding: 22 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14, color: "var(--textDim)", fontSize: 12.5 }}>
          <MapPin size={14} />
          <span>{loc.label || (loc.lat != null ? `${loc.lat.toFixed(2)}, ${loc.lon.toFixed(2)}` : "—")}</span>
        </div>

        {reminders.nextPrayer && (
          <div style={{ textAlign: "center", marginBottom: 18 }}>
            <div style={{ fontSize: 12, color: "var(--textDim)" }}>{tr("nextPrayer")}</div>
            <div style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 24, color: "var(--primary)", marginTop: 4 }}>
              {reminders.nextPrayer[0]} — {fmtTime(reminders.nextPrayer[1])}
            </div>
            {prefs.notifIqama && reminders.nextPrayer[1] && (
              <div style={{ fontSize: 12, color: "var(--accent)", marginTop: 6, fontFamily: "'Cairo', sans-serif" }}>
                الإقامة — {fmtTime(new Date(reminders.nextPrayer[1].getTime() + (Number(prefs.iqamaDelayMin) || 15) * 60000))}
              </div>
            )}
          </div>
        )}

        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 10 }}>
          {PRAYER_ROWS.map(([label, key]) => (
            <div key={key} style={{ background: "var(--surfaceAlt)", borderRadius: 14, padding: "12px 6px", textAlign: "center" }}>
              <div style={{ fontSize: 12, color: "var(--textDim)" }}>{label}</div>
              <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 15, color: "var(--text)", fontWeight: 700, marginTop: 4 }}>{fmtTime(reminders.times?.[key])}</div>
            </div>
          ))}
        </div>

        <div style={{ display: "flex", gap: 10, marginTop: 18, flexWrap: "wrap" }}>
          <button onClick={reminders.requestLocation} style={{ ...btnGhost(), flex: 1, justifyContent: "center" }}>
            <MapPin size={14} /> {tr("updateLocation")}
          </button>
          {reminders.notifPermission !== "granted" && (
            <button onClick={reminders.requestNotifPermission} style={{ ...btnPrimarySmall(), flex: 1 }}>{tr("enableNotif")}</button>
          )}
        </div>
        {loc.denied && <p style={{ fontSize: 11.5, color: "var(--danger)", textAlign: "center", marginTop: 10 }}>تم رفض إذن الموقع من المتصفح — يمكن تفعيله من إعدادات المتصفح.</p>}
      </Card>

      <SectionTitle>{tr("calcMethod")}</SectionTitle>
      <Card style={{ padding: 8 }}>
        {Object.entries(CALC_METHODS).map(([id, m]) => (
          <div
            key={id}
            onClick={() => updatePrefs({ calcMethod: id })}
            style={{
              display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 14px", cursor: "pointer",
              borderRadius: 12, background: prefs.calcMethod === id ? "var(--accentSoft)" : "transparent",
            }}
          >
            <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, color: "var(--text)" }}>{m.label}</span>
            {prefs.calcMethod === id && <CheckCircle2 size={17} color="var(--primary)" />}
          </div>
        ))}
      </Card>
      <p style={{ fontSize: 11, color: "var(--textDim)", textAlign: "center", marginTop: 12, fontFamily: "'Cairo', sans-serif" }}>
        حساب فلكي تقريبي — للدقة الكاملة في المناسبات المهمة راجع مصدرًا محليًا معتمدًا.
      </p>
      <div style={{ height: 24 }} />
    </div>
  );
}

function MonthlyTracker({ state, updateState }) {
  const [monthOffset, setMonthOffset] = useState(0);
  const [selectedDay, setSelectedDay] = useState(null);
  const base = new Date();
  base.setDate(1);
  base.setMonth(base.getMonth() + monthOffset);
  const year = base.getFullYear(), month = base.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstWeekday = new Date(year, month, 1).getDay(); // 0=Sunday

  const cells = [];
  for (let i = 0; i < firstWeekday; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const dayKeyFor = (d) => todayKey(new Date(year, month, d));
  const monthLabel = base.toLocaleDateString("ar-EG", { month: "long", year: "numeric" });

  // نسبة الصلوات المكتملة تحديدًا (مش الإنجاز العام) — الامتلاء داخل المربع بيبقى بنفس
  // النسبة بالظبط: ٥ من ٥ تمتلئ كاملة، ٣ من ٥ تمتلئ للنص تقريبًا، وهكذا.
  const prayerRatio = (dayRec) => (dayRec ? dayRec.prayers.filter(Boolean).length / 5 : 0);

  const selectedRec = selectedDay ? state.days[dayKeyFor(selectedDay)] : null;

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
        <button onClick={() => setMonthOffset((m) => m - 1)} style={iconBtn()}><ChevronRight size={16} /></button>
        <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, fontWeight: 700, color: "var(--text)" }}>{monthLabel}</span>
        <button onClick={() => setMonthOffset((m) => Math.min(0, m + 1))} disabled={monthOffset >= 0} style={{ ...iconBtn(), opacity: monthOffset >= 0 ? 0.3 : 1 }}><ChevronLeft size={16} /></button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 4, marginBottom: 6 }}>
        {["أحد", "اثن", "ثلا", "أرب", "خمي", "جمع", "سبت"].map((d) => (
          <div key={d} style={{ textAlign: "center", fontSize: 9.5, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>{d}</div>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 4 }}>
        {cells.map((d, i) => {
          if (d === null) return <div key={i} />;
          const rec = state.days[dayKeyFor(d)];
          const isToday = dayKeyFor(d) === todayKey(new Date());
          const ratio = rec && !rec.excused ? prayerRatio(rec) : 0;
          const filled = ratio > 0;
          return (
            <button
              key={i}
              onClick={() => setSelectedDay(d)}
              style={{
                aspectRatio: "1", borderRadius: 8, border: isToday ? "2px solid var(--primary)" : "1px solid var(--border)",
                background: rec?.excused
                  ? "var(--accent)"
                  : filled
                    ? `linear-gradient(0deg, var(--primary) ${Math.round(ratio * 100)}%, var(--surfaceAlt) ${Math.round(ratio * 100)}%)`
                    : "var(--surfaceAlt)",
                color: rec && !rec.excused && ratio >= 0.6 ? "var(--onPrimary)" : "var(--text)",
                fontSize: 11, fontFamily: "'Cairo', sans-serif", cursor: "pointer", position: "relative", overflow: "hidden",
                transition: "background .3s",
              }}
            >
              {d}
              {rec?.excused && <span style={{ position: "absolute", top: 1, insetInlineEnd: 2, fontSize: 8 }}>🌸</span>}
            </button>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: 12, marginTop: 14, flexWrap: "wrap", fontSize: 10.5, color: "var(--textDim)" }}>
        <span style={{ display: "flex", alignItems: "center", gap: 4 }}><span style={{ width: 10, height: 10, borderRadius: 3, background: "var(--primary)", display: "inline-block" }} /> الصلوات الخمس ٥/٥</span>
        <span style={{ display: "flex", alignItems: "center", gap: 4 }}><span style={{ width: 10, height: 10, borderRadius: 3, background: "linear-gradient(0deg, var(--primary) 50%, var(--surfaceAlt) 50%)", border: "1px solid var(--border)", display: "inline-block" }} /> جزء من الصلوات</span>
        <span style={{ display: "flex", alignItems: "center", gap: 4 }}><span style={{ width: 10, height: 10, borderRadius: 3, background: "var(--accent)", display: "inline-block" }} /> 🌸 يوم عذر</span>
      </div>
      {selectedDay && (
        <Card style={{ padding: 14, marginTop: 14 }}>
          <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 12.5, fontWeight: 700, color: "var(--text)", marginBottom: 10 }}>
            {new Date(year, month, selectedDay).toLocaleDateString("ar-EG", { weekday: "long", day: "numeric", month: "long" })}
          </div>
          {selectedRec ? (
            selectedRec.excused ? (
              <p style={{ fontSize: 12, color: "var(--textDim)", margin: 0 }}>🌸 يوم عذر شرعي — إنجاز {dayCompletion(selectedRec)}٪ من العبادات غير المرتبطة بالصلاة</p>
            ) : (
              <>
                <p style={{ fontSize: 12, color: "var(--textDim)", margin: "0 0 10px" }}>الصلوات: {selectedRec.prayers.filter(Boolean).length}/٥ — الإنجاز العام: {dayCompletion(selectedRec)}٪</p>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
                  {PRAYERS.map((p, i) => {
                    const done = selectedRec.prayers[i];
                    return (
                      <span
                        key={p}
                        style={{
                          display: "flex", alignItems: "center", gap: 5, padding: "5px 10px", borderRadius: 999,
                          background: done ? "var(--accentSoft)" : "color-mix(in srgb, #E4573D 15%, transparent)",
                          color: done ? "var(--accent)" : "#E4573D",
                          fontFamily: "'Cairo', sans-serif", fontSize: 11.5, fontWeight: 600,
                        }}
                      >
                        {done ? <CheckCircle2 size={12} /> : <X size={12} />} {p}
                      </span>
                    );
                  })}
                </div>
                {selectedRec.prayers.some((v) => !v) && (
                  <p style={{ fontSize: 10.5, color: "var(--textDim)", marginTop: 10, marginBottom: 0, lineHeight: 1.7 }}>
                    الصلاة المفروضة الفائتة لا تُقضى بمعنى قضاء النافلة، لكن يستحب المبادرة بأدائها بمجرد التذكّر إن أمكن، مع التوبة والاستغفار.
                  </p>
                )}
              </>
            )
          ) : (
            <p style={{ fontSize: 12, color: "var(--textDim)", margin: 0 }}>مفيش تسجيل لهذا اليوم</p>
          )}
        </Card>
      )}
    </div>
  );
}

function Journey({ state, updateState }) {
  const week = last7Days(state.days);
  const [sharingAchievement, setSharingAchievement] = useState(null); // "week" | "month" | null
  const [goalTitle, setGoalTitle] = useState("");
  const addGoal = () => {
    if (!goalTitle.trim()) return;
    updateState({ goals: [...state.goals, { title: goalTitle, progress: 0, done: false }] });
    setGoalTitle("");
  };
  const toggleGoal = (i) => {
    const goals = [...state.goals];
    goals[i].done = !goals[i].done;
    updateState({ goals });
  };

  const shareAchievement = async (period) => {
    setSharingAchievement(period);
    try {
      const now = new Date();
      let keys, label;
      if (period === "week") {
        keys = week.map((d) => d.key);
        label = "هذا الأسبوع";
      } else {
        keys = [];
        const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
        for (let day = 1; day <= daysInMonth; day++) keys.push(todayKey(new Date(now.getFullYear(), now.getMonth(), day)));
        label = now.toLocaleDateString("ar-EG", { month: "long" });
      }
      const stats = computePeriodStats(state.days, keys);
      const T = getTokens("light", "classic");
      const blob = await generateAchievementCard(stats, label, state.prefs?.name, { hero1: T.primary, hero2: T.accent });
      const file = new File([blob], "anisk-achievement.png", { type: "image/png" });
      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: "إنجازي مع أنيسك" });
      } else {
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url; a.download = "anisk-achievement.png";
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }
    } catch { /* تجاهل فشل المشاركة */ }
    setSharingAchievement(null);
  };

  return (
    <div>
      <SectionTitle>رحلتي</SectionTitle>
      {state.streak > 0 && (
        <Card style={{ padding: 20, marginBottom: 16, display: "flex", alignItems: "center", gap: 14, background: "linear-gradient(135deg, var(--accentSoft), transparent)", border: "none" }}>
          <Flame size={32} color="var(--accent)" />
          <div>
            <div style={{ display: "flex", alignItems: "baseline", gap: 6 }}>
              <span style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 32, color: "var(--accent)", lineHeight: 1 }}>{state.streak}</span>
              <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, color: "var(--text)", fontWeight: 600 }}>يوم متتالي</span>
            </div>
            <div style={{ fontSize: 12, color: "var(--textDim)", marginTop: 3 }}>فاتك يوم، ولا يفوتك اليوم 🤍</div>
          </div>
        </Card>
      )}

      <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
        <button onClick={() => shareAchievement("week")} disabled={sharingAchievement === "week"} style={{ ...btnPrimarySmall(), flex: 1, justifyContent: "center", opacity: sharingAchievement === "week" ? 0.6 : 1 }}>
          📤 مشاركة إنجاز الأسبوع
        </button>
        <button onClick={() => shareAchievement("month")} disabled={sharingAchievement === "month"} style={{ ...btnGhost(), flex: 1, justifyContent: "center", opacity: sharingAchievement === "month" ? 0.6 : 1 }}>
          📤 مشاركة إنجاز الشهر
        </button>
      </div>

      <SectionTitle>المتتبّع الشهري</SectionTitle>
      <Card style={{ padding: 16 }}>
        <MonthlyTracker state={state} updateState={updateState} />
      </Card>

      <SectionTitle>ختمة القرآن</SectionTitle>
      <KhatmPlanner state={state} updateState={updateState} />

      <SectionTitle>هذا الأسبوع</SectionTitle>
      <Card style={{ padding: "22px 18px" }}>
        <div style={{ display: "flex", gap: 8, alignItems: "flex-end", height: 110 }}>
          {week.map((d) => (
            <div key={d.key} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
              <div style={{ width: "100%", height: 80, display: "flex", alignItems: "flex-end", background: "var(--surfaceAlt)", borderRadius: 8, overflow: "hidden" }}>
                <div style={{ width: "100%", height: `${d.pct}%`, background: "var(--primary)", borderRadius: 8, transition: "height .5s" }} />
              </div>
              <span style={{ fontSize: 10.5, color: "var(--textDim)" }}>{d.label}</span>
            </div>
          ))}
        </div>
      </Card>

      <SectionTitle>أهدافي</SectionTitle>
      <Card style={{ padding: 16, marginBottom: 12 }}>
        <div style={{ display: "flex", gap: 8 }}>
          <input value={goalTitle} onChange={(e) => setGoalTitle(e.target.value)} placeholder="هدف جديد، مثل: حفظ سورة الملك" style={{ ...inputStyle(), flex: 1 }} />
          <button onClick={addGoal} style={btnPrimarySmall()}>إضافة</button>
        </div>
      </Card>
      {state.goals.length === 0 ? (
        <EmptyState icon={<Target size={28} />} title="أضف أول هدف يقربك من ربك 🤍" />
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {state.goals.map((g, i) => (
            <Card key={i} onClick={() => toggleGoal(i)} style={{ padding: "13px 16px", cursor: "pointer", display: "flex", alignItems: "center", gap: 12 }}>
              {g.done ? <CheckCircle2 size={19} color="var(--primary)" /> : <Circle size={19} color="var(--textDim)" />}
              <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, color: "var(--text)", textDecoration: g.done ? "line-through" : "none", opacity: g.done ? 0.6 : 1 }}>{g.title}</span>
            </Card>
          ))}
        </div>
      )}
      <div style={{ height: 24 }} />
    </div>
  );
}

/* =========================================================================
   Settings
   ========================================================================= */

// مشاركة حقيقية عبر Web Share API (أو نسخ الرابط لو مش متاحة) — مفيش رابط وهمي
function ShareAppRow({ tr }) {
  const [copied, setCopied] = useState(false);
  const appUrl = typeof window !== "undefined" ? window.location.href : "";
  const shareText = "لو عجبك تطبيق أنيسك واستفدت منه، شاركه مع شخص تحبه 🤍\nيمكن يكون سببًا في قراءة قرآن أو ذكر أو عبادة، ويكون لك أجر بإذن الله.";

  const share = async () => {
    if (navigator.share) {
      try { await navigator.share({ title: "أنيسك | Anisk", text: shareText, url: appUrl }); }
      catch { /* المستخدم لغى المشاركة — لا داعي لأي رسالة خطأ */ }
    } else {
      try {
        await navigator.clipboard.writeText(`${shareText}\n${appUrl}`);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      } catch { /* تجاهل */ }
    }
  };

  return (
    <div onClick={share} style={{ padding: "16px 18px", cursor: "pointer", display: "flex", alignItems: "center", gap: 14 }}>
      <div style={{ width: 38, height: 38, borderRadius: 12, background: "var(--accentSoft)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontSize: 17 }}>📤</div>
      <div style={{ flex: 1 }}>
        <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, fontWeight: 600, color: "var(--text)" }}>شارك أنيسك</div>
        <div style={{ fontSize: 11.5, color: "var(--textDim)" }}>{copied ? "✓ انسخ الرابط جاهز للصق" : "واتساب، تيليجرام، أو أي تطبيق على جهازك"}</div>
      </div>
      <ChevronLeft size={16} color="var(--textDim)" />
    </div>
  );
}

// مفيش صفحة تقييم حقيقية على متجر تطبيقات (التطبيق مش منشور كتطبيق مستقل)، فبدل ما
// نحط زرار وهمي بيوديك لمكان مش موجود، بنفتح البريد لإرسال رأيك مباشرة — فعلي وشغال.
function RateAppRow() {
  const feedbackUrl = "mailto:?subject=" + encodeURIComponent("رأيي في تطبيق أنيسك") + "&body=" + encodeURIComponent("حابة أشارك رأيي في التطبيق:\n\n");
  return (
    <a href={feedbackUrl} style={{ padding: "16px 18px", cursor: "pointer", display: "flex", alignItems: "center", gap: 14, textDecoration: "none", color: "inherit" }}>
      <div style={{ width: 38, height: 38, borderRadius: 12, background: "var(--accentSoft)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontSize: 17 }}>⭐</div>
      <div style={{ flex: 1 }}>
        <div style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, fontWeight: 600, color: "var(--text)" }}>شاركينا رأيك</div>
        <div style={{ fontSize: 11.5, color: "var(--textDim)" }}>التطبيق مش على متجر تطبيقات لسه، فرأيك بييجيلنا مباشرة بالإيميل</div>
      </div>
      <ChevronLeft size={16} color="var(--textDim)" />
    </a>
  );
}

const ANISK_AI_SYSTEM = `أنت "أنيسك AI"، مساعد ديني إسلامي داخل تطبيق أنيسك. مهمتك مساعدة المستخدم في فهم القرآن والتفسير وأسباب النزول والأحاديث والسيرة النبوية والفقه والعبادات (الصلاة، الصيام، الزكاة، الحج، الأذكار، الأدعية) والأسئلة الدينية العامة.

قواعد صارمة يجب الالتزام بها دائمًا:

١. لا تختلق أبدًا آيات قرآنية أو أحاديث أو أقوال علماء أو مصادر. لو مش متأكد من نص أو مصدر، قول بوضوح "مش متأكد من الصيغة الدقيقة" بدل ما تخترع.

٢. لما تذكر حديثًا، اذكر مصدره (البخاري، مسلم، إلخ) قدر الإمكان، ولو كان الحديث ضعيفًا أو مختلفًا في تصحيحه وضّح ذلك.

٣. لو السؤال فتوى شخصية أو حكم فقهي ("حلال ولا حرام؟"، "ما حكم كذا؟"):
   - لا تتصرف كأنك مفتٍ مستقل يصدر أحكامًا قطعية.
   - اذكر الحكم مع مصدره الشرعي عند الإمكان.
   - لو فيه خلاف معتبر بين المذاهب أو العلماء، اذكر الخلاف ولا تفرض رأيًا واحدًا كأنه الصواب المطلق.
   - فرّق بوضوح بين "معلومة دينية عامة" و"فتوى شخصية تحتاج سياق حياة المستخدم الكامل".
   - في المسائل الحساسة أو الشخصية جدًا (طلاق، ميراث معقّد، حالات صحية تؤثر على العبادة)، انصح المستخدم بالرجوع لعالم أو مفتٍ موثوق يعرف تفاصيل حالته.

٤. الدقة الدينية أهم من سرعة الإجابة. لو مش متأكد، قول إنك مش متأكد.

٥. كن دافئًا ومحترمًا ومختصرًا قدر الإمكان (فقرتين إلى ثلاث فقرات عادةً)، بدون وعظ مبالغ فيه أو إطالة غير ضرورية.

٦. رد بالعربية الفصحى المبسّطة، إلا لو المستخدم كتب بالإنجليزية.`;

async function loadSavedAiAnswers() {
  try {
    const res = await window.storage.get("unisk:saved-ai-answers", false);
    return res?.value ? JSON.parse(res.value) : [];
  } catch { return []; }
}
async function saveSavedAiAnswers(list) {
  try { await window.storage.set("unisk:saved-ai-answers", JSON.stringify(list), false); } catch { /* best effort */ }
}

function SavedAiAnswers({ items, onDelete, onBack }) {
  return (
    <div>
      <TopBarBack onBack={onBack} title="إجاباتي المحفوظة" />
      {items.length === 0 ? (
        <EmptyState icon={<Bookmark size={26} />} title="لسه مفيش إجابات محفوظة — احفظي أي إجابة مفيدة من أسأل أنيسك AI" />
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {items.slice().reverse().map((it, i) => (
            <Card key={i} style={{ padding: 14 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8, marginBottom: 8 }}>
                <p style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13, fontWeight: 700, color: "var(--accent)", margin: 0 }}>{it.question}</p>
                <X size={15} color="var(--textDim)" style={{ cursor: "pointer", flexShrink: 0 }} onClick={() => onDelete(it)} />
              </div>
              <p style={{ fontSize: 13, color: "var(--text)", lineHeight: 1.8, whiteSpace: "pre-wrap", margin: 0 }}>{it.answer}</p>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

function AnisqAI() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [savedAnswers, setSavedAnswers] = useState([]);
  const [showSaved, setShowSaved] = useState(false);
  const scrollRef = useRef(null);

  useEffect(() => { scrollRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages, loading]);
  useEffect(() => { loadSavedAiAnswers().then(setSavedAnswers); }, []);

  const isSaved = (question, answer) => savedAnswers.some((s) => s.question === question && s.answer === answer);
  const toggleSaveAnswer = (question, answer) => {
    setSavedAnswers((prev) => {
      const next = isSaved(question, answer)
        ? prev.filter((s) => !(s.question === question && s.answer === answer))
        : [...prev, { question, answer, savedAt: Date.now() }];
      saveSavedAiAnswers(next);
      return next;
    });
  };

  const send = async () => {
    const text = input.trim();
    if (!text || loading) return;
    const newMessages = [...messages, { role: "user", content: text }];
    setMessages(newMessages);
    setInput("");
    setLoading(true);
    setError(null);
    const payload = {
      system: ANISK_AI_SYSTEM,
      messages: newMessages.map((m) => ({ role: m.role, content: m.content })),
    };
    try {
      // النداء الوحيد اللي يقدر يشتغل فعليًا من متصفح المستخدمة هو بروكسي التطبيق
      // (/api/ai) — سواء دالة Vercel الحقيقية بعد النشر، أو محاكاتها المحلية أثناء
      // npm run dev (مُعرَّفة في vite.config.js). نداء مباشر لـ api.anthropic.com
      // من كود المتصفح مستحيل يشتغل أصلًا (تحتاج مفتاح سرّي ما ينفعش يتحط في كود
      // العميل، والـ API العام أصلًا لا يسمح بنداءات مباشرة من متصفحات خارجية)،
      // فمحاولته هنا كانت وهمية وبتخلي رسالة الخطأ مضلِّلة.
      const res = await fetch("/api/ai", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || "http-" + res.status);
      const textBlocks = (data.content || []).filter((b) => b.type === "text").map((b) => b.text);
      const reply = textBlocks.join("\n").trim();
      if (!reply) throw new Error("empty");
      setMessages((m) => [...m, { role: "assistant", content: reply }]);
    } catch (e) {
      const msg = typeof e?.message === "string" ? e.message : "";
      setError(
        msg
          ? msg
          : "تعذّر الوصول للمساعد الآن. تأكدي من الاتصال بالإنترنت. لو المشكلة مستمرة: محليًا تأكدي من وجود ملف .env فيه ANTHROPIC_API_KEY، وعلى Vercel تأكدي من إضافته من Settings → Environment Variables ثم إعادة النشر (راجعي README)."
      );
    }
    setLoading(false);
  };

  const suggestions = ["ما معنى آية الكرسي؟", "ما حكم قصر الصلاة في السفر؟", "احكيلي عن غزوة بدر باختصار", "علّمني دعاء لتفريج الهم"];

  if (showSaved) {
    return (
      <SavedAiAnswers
        items={savedAnswers}
        onBack={() => setShowSaved(false)}
        onDelete={(it) => {
          const next = savedAnswers.filter((s) => !(s.question === it.question && s.answer === it.answer));
          setSavedAnswers(next);
          saveSavedAiAnswers(next);
        }}
      />
    );
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <SectionTitle>✨ اسأل أنيسك AI</SectionTitle>
        <button onClick={() => setShowSaved(true)} style={{ ...iconBtn(), position: "relative" }} title="إجاباتي المحفوظة">
          <Bookmark size={16} />
          {savedAnswers.length > 0 && (
            <span style={{ position: "absolute", top: -4, insetInlineEnd: -4, background: "var(--primary)", color: "var(--onPrimary)", fontSize: 9, borderRadius: 999, minWidth: 15, height: 15, display: "flex", alignItems: "center", justifyContent: "center" }}>
              {savedAnswers.length}
            </span>
          )}
        </button>
      </div>
      <p style={{ fontSize: 11.5, color: "var(--textDim)", lineHeight: 1.7, marginBottom: 14 }}>
        مساعد ديني بيجاوبك عن التفسير والحديث والفقه والسيرة. في المسائل الشخصية أو المختلف عليها، هيوجّهك لعالم موثوق بدل ما يفتيك بنفسه.
      </p>

      {messages.length === 0 && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 16 }}>
          {suggestions.map((s, i) => (
            <button key={i} onClick={() => { setInput(s); }} style={{ ...btnGhost(), justifyContent: "flex-start", textAlign: "start" }}>
              {s}
            </button>
          ))}
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 16 }}>
        {messages.map((m, i) => {
          const prevUserMsg = m.role === "assistant" ? messages[i - 1]?.content : null;
          const saved = m.role === "assistant" && prevUserMsg ? isSaved(prevUserMsg, m.content) : false;
          return (
            <div key={i} style={{ display: "flex", flexDirection: "column", alignItems: m.role === "user" ? "flex-end" : "flex-start" }}>
              <div style={{
                maxWidth: "85%", padding: "10px 14px", borderRadius: 14,
                background: m.role === "user" ? "var(--primary)" : "var(--surfaceAlt)",
                color: m.role === "user" ? "var(--onPrimary)" : "var(--text)",
                fontFamily: "'Cairo', sans-serif", fontSize: 13.5, lineHeight: 1.8, whiteSpace: "pre-wrap",
              }}>
                {m.content}
              </div>
              {m.role === "assistant" && prevUserMsg && (
                <button
                  onClick={() => toggleSaveAnswer(prevUserMsg, m.content)}
                  style={{
                    marginTop: 4, background: "none", border: "none", cursor: "pointer", padding: "2px 4px",
                    display: "flex", alignItems: "center", gap: 4, color: saved ? "var(--accent)" : "var(--textDim)",
                    fontFamily: "'Cairo', sans-serif", fontSize: 11,
                  }}
                >
                  <Bookmark size={12} fill={saved ? "currentColor" : "none"} /> {saved ? "محفوظة" : "احفظي هذه الإجابة"}
                </button>
              )}
            </div>
          );
        })}
        {loading && (
          <div style={{ display: "flex", justifyContent: "flex-start" }}>
            <div style={{ padding: "10px 14px", borderRadius: 14, background: "var(--surfaceAlt)", color: "var(--textDim)", fontSize: 13 }}>جارٍ التفكير...</div>
          </div>
        )}
        {error && <p style={{ fontSize: 12, color: "var(--danger)", textAlign: "center" }}>{error}</p>}
        <div ref={scrollRef} />
      </div>

      <div style={{ position: "sticky", bottom: 8, display: "flex", gap: 8, background: "var(--bg)", paddingTop: 6 }}>
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") send(); }}
          placeholder="اسأليني أي سؤال ديني..."
          style={{ ...inputStyle(), flex: 1 }}
        />
        <button onClick={send} disabled={loading} style={{ ...btnPrimarySmall(), opacity: loading ? 0.6 : 1 }}>إرسال</button>
      </div>
    </div>
  );
}

function SettingsSection({ state, updateState, prefs, updatePrefs, themeMode, setThemeMode, resolvedTheme, reminders, tr }) {
  return (
    <div>
      <SectionTitle>{tr("settings")}</SectionTitle>

      <div style={rowLabel()}>{tr("language")}</div>
      <Card style={{ padding: 8, display: "flex", gap: 6, marginBottom: 20 }}>
        {[{ id: "ar", label: tr("arabic") }, { id: "en", label: tr("english") }].map((l) => (
          <button key={l.id} onClick={() => updateState({ lang: l.id })} style={{
            flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 6, padding: "11px 4px", borderRadius: 12,
            border: "none", cursor: "pointer", background: state.lang === l.id ? "var(--primary)" : "transparent",
            color: state.lang === l.id ? "var(--onPrimary)" : "var(--textDim)", fontFamily: "'Cairo', sans-serif", fontSize: 13,
          }}><Languages size={14} />{l.label}</button>
        ))}
      </Card>

      <div style={rowLabel()}>{tr("appearance")}</div>
      <Card style={{ padding: 8, display: "flex", gap: 6, marginBottom: 12 }}>
        {[{ id: "light", label: tr("light"), icon: <Sun size={15} /> }, { id: "dark", label: tr("dark"), icon: <Moon size={15} /> }, { id: "system", label: tr("system"), icon: <Laptop size={15} /> }].map((m) => (
          <button key={m.id} onClick={() => setThemeMode(m.id)} style={{
            flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 5, padding: "12px 4px", borderRadius: 12,
            border: "none", cursor: "pointer", background: themeMode === m.id ? "var(--primary)" : "transparent",
            color: themeMode === m.id ? "var(--onPrimary)" : "var(--textDim)", fontFamily: "'Cairo', sans-serif", fontSize: 12.5,
          }}>{m.icon}{m.label}</button>
        ))}
      </Card>

      {resolvedTheme !== "dark" && (
        <>
          <div style={{ ...rowLabel(), margin: "0 4px 8px" }}>{tr("lightColor")}</div>
          <Card style={{ padding: 12, marginBottom: 20, display: "flex", gap: 10, flexWrap: "wrap" }}>
            {Object.entries(LIGHT_PRESETS).map(([id, p]) => (
              <button key={id} onClick={() => updateState(gregorianToHijri(new Date()).month === 9 ? { lightTheme: id, disableRamadanTheme: true } : { lightTheme: id })} style={{
                display: "flex", flexDirection: "column", alignItems: "center", gap: 6, border: "none", background: "transparent", cursor: "pointer", flex: 1, minWidth: 64,
              }}>
                <div style={{
                  width: 40, height: 40, borderRadius: "50%", display: "flex", overflow: "hidden",
                  border: state.lightTheme === id ? "2.5px solid var(--accent)" : "1px solid var(--border)",
                }}>
                  <div style={{ width: "50%", background: p.swatch[0] }} />
                  <div style={{ width: "50%", background: p.swatch[1] }} />
                </div>
                <span style={{ fontSize: 11, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>{p.label}</span>
              </button>
            ))}
          </Card>
        </>
      )}

      {resolvedTheme === "dark" && (
        <>
          <div style={{ ...rowLabel(), margin: "0 4px 8px" }}>لون الوضع الليلي</div>
          <Card style={{ padding: 12, marginBottom: 20, display: "flex", gap: 10, flexWrap: "wrap" }}>
            {Object.entries(DARK_PRESETS).map(([id, p]) => (
              <button key={id} onClick={() => updateState({ darkTheme: id })} style={{
                display: "flex", flexDirection: "column", alignItems: "center", gap: 6, border: "none", background: "transparent", cursor: "pointer", flex: 1, minWidth: 64,
              }}>
                <div style={{
                  width: 40, height: 40, borderRadius: "50%", display: "flex", overflow: "hidden",
                  border: (state.darkTheme || "classic") === id ? "2.5px solid var(--accent)" : "1px solid var(--border)",
                }}>
                  <div style={{ width: "50%", background: p.swatch[0] }} />
                  <div style={{ width: "50%", background: p.swatch[1] }} />
                </div>
                <span style={{ fontSize: 11, color: "var(--textDim)", fontFamily: "'Cairo', sans-serif" }}>{p.label}</span>
              </button>
            ))}
          </Card>
        </>
      )}

      <div style={rowLabel()}>القرآن</div>
      <Card style={{ marginBottom: 20 }}>
        <SettingRow label="قارئ القراءة والتكرار" value={RECITERS.find((r) => r.id === prefs.quranReciter)?.name} />
        <SettingRow label="قارئ الاستماع والأذكار" value={RECITERS.find((r) => r.id === prefs.reciter)?.name} />
        <SettingRow label="الورد اليومي" value={`${prefs.dailyGoal} صفحات`} />
      </Card>

      <div style={rowLabel()}>الإشعارات</div>
      <Card style={{ padding: "4px 16px", marginBottom: 20 }}>
        <ToggleRow label="تذكير الصلاة (الأذان)" checked={prefs.notifPrayer} onChange={(v) => updatePrefs({ notifPrayer: v })} />
        <ToggleRow label="⏰ تنبيه قبل الصلاة بـ ١٥ دقيقة" checked={prefs.notifPreAdhan} onChange={(v) => updatePrefs({ notifPreAdhan: v })} />
        <ToggleRow label="🔊 تشغيل صوت الأذان" checked={prefs.adhanSoundEnabled} onChange={(v) => updatePrefs({ adhanSoundEnabled: v })} />
        {prefs.adhanSoundEnabled && (
          <div style={{ padding: "10px 0", borderBottom: "1px solid var(--border)" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
              <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, color: "var(--textDim)" }}>صوت الأذان</span>
              <select value={prefs.adhanVoice} onChange={(e) => updatePrefs({ adhanVoice: e.target.value })} style={{ ...inputStyle(), width: 150, padding: "6px 8px", fontSize: 12.5 }}>
                {ADHAN_SOUNDS.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
            </div>
            <p style={{ fontSize: 10.5, color: "var(--textDim)", lineHeight: 1.6, margin: 0 }}>
              ملحوظة: صوت الأذان بيشتغل بس والتطبيق مفتوح قدامك (تبويب المتصفح شغال). المتصفحات ما بتسمحش بتشغيل صوت من تطبيق مقفول أو الشاشة مقفولة — ده قيد تقني عام مش خاص بالتطبيق.
            </p>
          </div>
        )}
        <ToggleRow label="تذكير الإقامة" checked={prefs.notifIqama} onChange={(v) => updatePrefs({ notifIqama: v })} />
        {prefs.notifIqama && (
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 0", borderBottom: "1px solid var(--border)" }}>
            <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 13.5, color: "var(--textDim)" }}>الفاصل بين الأذان والإقامة</span>
            <select value={prefs.iqamaDelayMin} onChange={(e) => updatePrefs({ iqamaDelayMin: Number(e.target.value) })} style={{ ...inputStyle(), width: 110, padding: "6px 8px", fontSize: 13 }}>
              {[10, 15, 20, 25, 30].map((m) => <option key={m} value={m}>{m} دقيقة</option>)}
            </select>
          </div>
        )}
        <ToggleRow label="تذكير الورد اليومي" checked={prefs.notifQuran} onChange={(v) => updatePrefs({ notifQuran: v })} />
        <ToggleRow label="تذكير الأذكار" checked={prefs.notifAdhkar} onChange={(v) => updatePrefs({ notifAdhkar: v })} />
        <ToggleRow label="🌙 تذكير قيام الليل" checked={prefs.notifQiyam} onChange={(v) => updatePrefs({ notifQiyam: v })} />
        <ToggleRow label="☀️ تذكير صلاة الضحى" checked={prefs.notifDuha} onChange={(v) => updatePrefs({ notifDuha: v })} />
        <ToggleRow label="🌙 تنبيه صيام السنة قبلها بيوم" checked={prefs.notifFastingEve} onChange={(v) => updatePrefs({ notifFastingEve: v })} />
        <ToggleRow label="📜 حديث اليوم" checked={prefs.notifHadith !== false} onChange={(v) => updatePrefs({ notifHadith: v })} />
        <ToggleRow
          label="⏰ منبّه الفجر المتكرر (لحد ما تأكدي إنك قمتِ)"
          checked={prefs.fajrAlarmEnabled}
          onChange={(v) => updatePrefs({ fajrAlarmEnabled: v })}
          last
        />
        {prefs.fajrAlarmEnabled && (
          <p style={{ fontSize: 10.5, color: "var(--textDim)", lineHeight: 1.6, margin: "0 0 10px" }}>
            هيكرر التنبيه كل ٥ دقايق بعد أذان الفجر لحد ما تدوسي على "قمت للصلاة ✓" من الصفحة الرئيسية.
          </p>
        )}
      </Card>

      <div style={rowLabel()}>مواعيد الصلاة والموقع</div>
      <Card style={{ padding: 16, marginBottom: 20 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
          <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, color: "var(--text)" }}>الموقع الحالي</span>
          <span style={{ fontSize: 12.5, color: "var(--textDim)" }}>
            {prefs.location?.lat != null ? `${prefs.location.lat.toFixed(2)}, ${prefs.location.lon.toFixed(2)}` : "غير محدد"}
          </span>
        </div>
        <button onClick={reminders.requestLocation} style={{ ...btnGhost(), width: "100%", justifyContent: "center", marginBottom: 14 }}>تحديث الموقع</button>
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          <span style={{ fontSize: 12.5, color: "var(--textDim)" }}>طريقة الحساب</span>
          <select value={prefs.calcMethod} onChange={(e) => updatePrefs({ calcMethod: e.target.value })} style={inputStyle()}>
            {Object.entries(CALC_METHODS).map(([id, m]) => <option key={id} value={id}>{m.label}</option>)}
          </select>
        </div>
      </Card>

      <div style={rowLabel()}>ترحيب صوتي عند الفتح</div>
      <Card style={{ padding: "4px 16px", marginBottom: 20 }}>
        <ToggleRow label="تشغيل آية ترحيب عند فتح التطبيق" checked={prefs.welcomeSoundEnabled} onChange={(v) => updatePrefs({ welcomeSoundEnabled: v })} last />
        {prefs.welcomeSoundEnabled && (
          <div style={{ padding: "0 0 14px" }}>
            <select value={prefs.welcomeAyah} onChange={(e) => updatePrefs({ welcomeAyah: e.target.value })} style={{ ...inputStyle(), width: "100%" }}>
              {Object.entries(WELCOME_AYAHS).map(([id, a]) => <option key={id} value={id}>{a.label}</option>)}
            </select>
          </div>
        )}
      </Card>

      <div style={rowLabel()}>إشعارات التذكير 🤍</div>
      <Card style={{ padding: "8px 16px 14px", marginBottom: 20 }}>
        <div style={{ padding: "8px 0 12px", fontSize: 11.5, color: "var(--textDim)", lineHeight: 1.7 }}>
          حددي لكل تذكير المدة التي تريدينها بشكل مستقل. الخيارات تبدأ من دقيقة واحدة، ويمكنك كتابة أي عدد دقائق مخصص.
        </div>
        <ReminderSetting label="الصلاة على النبي ﷺ" enabled={prefs.salawatEnabled} interval={prefs.salawatIntervalMin} onEnabled={(v) => updatePrefs({ salawatEnabled: v })} onInterval={(v) => updatePrefs({ salawatIntervalMin: v })} />
        {prefs.salawatEnabled && (
          <p style={{ fontSize: 10.5, color: "var(--textDim)", lineHeight: 1.6, margin: "0 0 10px" }}>من مغرب الخميس لمغرب الجمعة، التذكير بيتكرر كل ١٥ دقيقة تلقائيًا مهما كان الفاصل اللي اخترتيه — تكريمًا لفضل الصلاة على النبي ﷺ يوم الجمعة.</p>
        )}
        <ReminderSetting label="الاستغفار" enabled={prefs.istighfarEnabled} interval={prefs.istighfarIntervalMin} onEnabled={(v) => updatePrefs({ istighfarEnabled: v })} onInterval={(v) => updatePrefs({ istighfarIntervalMin: v })} />
        <ReminderSetting label="🌿 آية حكمة/موعظة/ترغيب/ترهيب" enabled={prefs.wisdomVerseEnabled} interval={prefs.wisdomIntervalMin} onEnabled={(v) => updatePrefs({ wisdomVerseEnabled: v })} onInterval={(v) => updatePrefs({ wisdomIntervalMin: v })} />
        <ToggleRow label="🌙 تذكير بصيام الاثنين والخميس والأيام البيض" checked={prefs.fastingReminderEnabled} onChange={(v) => updatePrefs({ fastingReminderEnabled: v })} last />
        <div style={{ marginTop: 12, padding: 11, borderRadius: 12, background: "var(--accentSoft)", fontSize: 11, color: "var(--textDim)", lineHeight: 1.7 }}>
          🔔 <b>حالة الإشعارات:</b> التذكيرات تعمل فعليًا عند منح المتصفح إذن الإشعارات. استخدمي زر «تفعيل الإشعارات الآن» للتأكد من الإذن وإرسال إشعار تجريبي.
          <button onClick={reminders.requestNotifPermission} style={{ ...btnGhost(), width: "100%", justifyContent: "center", marginTop: 8 }}>
            🔔 تفعيل الإشعارات الآن
          </button>
          <div style={{ textAlign: "center", marginTop: 6, fontSize: 10.5 }}>
            {reminders.notifPermission === "granted" ? "✓ الإشعارات مفعّلة" : reminders.notifPermission === "denied" ? "✕ تم رفض الإشعارات — اسمحي بها من إعدادات المتصفح" : "لم يتم منح الإذن بعد"}
          </div>
        </div>
      </Card>

      <div style={rowLabel()}>حسابي</div>
      <Card style={{ padding: 16 }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          <span style={{ fontSize: 12.5, color: "var(--textDim)" }}>الاسم</span>
          <input value={prefs.name} onChange={(e) => updatePrefs({ name: e.target.value })} style={inputStyle()} />
        </div>
      </Card>

      <div style={rowLabel()}>ساعد أنيسك ينتشر 🤍</div>
      <Card style={{ padding: 0, overflow: "hidden" }}>
        <ShareAppRow tr={tr} />
        <div style={{ height: 1, background: "var(--border)" }} />
        <RateAppRow />
      </Card>

      <p style={{ textAlign: "center", fontSize: 11.5, color: "var(--textDim)", marginTop: 24, fontFamily: "'Cairo', sans-serif" }}>{tr("appName")} · رفيقك في طريقك إلى الله</p>
      <p style={{ textAlign: "center", fontSize: 10.5, color: "var(--textDim)", marginTop: 6, fontFamily: "'Cairo', sans-serif" }}>نص القرآن الكريم: مجموعة بيانات "quran-json" (رخصة CC-BY-4.0) — github.com/risan/quran-json</p>
      <div style={{ height: 24 }} />
    </div>
  );
}

function rowLabel() {
  return { fontFamily: "'Cairo', sans-serif", fontSize: 13, color: "var(--textDim)", fontWeight: 600, margin: "18px 4px 8px" };
}
function SettingRow({ label, value }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", padding: "13px 16px", borderBottom: "1px solid var(--border)" }}>
      <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, color: "var(--text)" }}>{label}</span>
      <span style={{ fontSize: 13, color: "var(--textDim)" }}>{value}</span>
    </div>
  );
}
function ReminderSetting({ label, enabled, interval, onEnabled, onInterval }) {
  const isCustom = ![1, 3, 5, 10, 20, 30, 60].includes(Number(interval));
  return (
    <div style={{ padding: "10px 0", borderBottom: "1px solid var(--border)" }}>
      <ToggleRow label={label} checked={enabled} onChange={onEnabled} />
      {enabled && (
        <div style={{ marginTop: 7, display: "flex", gap: 8, alignItems: "center" }}>
          <span style={{ fontSize: 11.5, color: "var(--textDim)", whiteSpace: "nowrap" }}>كل</span>
          <select value={isCustom ? "custom" : String(interval)} onChange={(e) => {
            const v = e.target.value;
            if (v === "custom") onInterval(Number(interval) > 0 ? Number(interval) : 15);
            else onInterval(Number(v));
          }} style={{ ...inputStyle(), flex: 1, padding: "7px 9px", fontSize: 12 }}>
            {[1, 3, 5, 10, 20, 30, 60].map(m => <option key={m} value={m}>{m === 20 ? "ثلث ساعة (20 دقيقة)" : m === 60 ? "ساعة (60 دقيقة)" : `${m} دقيقة`}</option>)}
            <option value="custom">مخصص…</option>
          </select>
          {isCustom && (
            <input type="number" min="1" max="1440" value={interval || 15} onChange={(e) => onInterval(Math.max(1, Math.min(1440, Number(e.target.value) || 1)))} style={{ ...inputStyle(), width: 78, padding: "7px 8px", fontSize: 12 }} />
          )}
        </div>
      )}
    </div>
  );
}

function ToggleRow({ label, checked, onChange, last }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "13px 0", borderBottom: last ? "none" : "1px solid var(--border)" }}>
      <span style={{ fontFamily: "'Cairo', sans-serif", fontSize: 14, color: "var(--text)" }}>{label}</span>
      <Toggle checked={checked} onChange={onChange} />
    </div>
  );
}


/* =========================================================================
   Audio player — driven by a real <audio> element (App-level controller).
   Streams verified per-ayah recitation from the alquran.cloud CDN when the
   reciter has an audio edition and the network allows it; otherwise shows
   an honest status instead of pretending playback is happening.
   ========================================================================= */

function MiniPlayer({ audio, prefs, onOpen }) {
  const { player } = audio;
  if (!player.surahId) return null;
  const reciter = RECITERS.find((r) => r.id === prefs.quranReciter);

  return (
    <div onClick={onOpen} style={{
      position: "fixed", insetInlineStart: 0, insetInlineEnd: 0, bottom: 0, zIndex: 40,
      maxWidth: 480, margin: "0 auto", cursor: "pointer",
    }}>
      <div style={{
        margin: "0 12px 12px", background: "var(--surface)", border: "1px solid var(--border)",
        borderRadius: 18, padding: "10px 14px", display: "flex", alignItems: "center", gap: 12, boxShadow: "var(--shadow)",
      }}>
        <div style={{ width: 38, height: 38, borderRadius: 10, background: "var(--accentSoft)", color: "var(--accent)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Mic size={16} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 12.5, fontFamily: "'Cairo', sans-serif", color: "var(--text)", fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{reciter?.name}</div>
          <div style={{ fontSize: 11, color: "var(--textDim)" }}>
            سورة {player.surahName} {player.status === "loading" ? "— جارٍ التحميل" : player.status === "error" ? "— تعذّر التشغيل" : ""}
          </div>
        </div>
        <button onClick={(e) => { e.stopPropagation(); audio.togglePlaying(); }} style={{ ...iconBtn(), border: "none", background: "var(--primary)", color: "var(--onPrimary)" }}>
          {player.playing ? <Pause size={15} /> : <Play size={15} />}
        </button>
        <button onClick={(e) => { e.stopPropagation(); audio.stop(); }} style={iconBtn()}>
          <X size={15} />
        </button>
      </div>
      <div style={{ height: 2, background: "var(--border)", margin: "0 12px" }}>
        <div style={{ height: "100%", width: `${player.progress}%`, background: "var(--accent)" }} />
      </div>
    </div>
  );
}

function FullPlayer({ audio, prefs, onClose }) {
  const { player } = audio;
  const reciter = RECITERS.find((r) => r.id === prefs.quranReciter);
  return (
    <div style={{ position: "fixed", inset: 0, background: "var(--bg)", zIndex: 90, display: "flex", flexDirection: "column", padding: 24, maxWidth: 480, margin: "0 auto" }}>
      <div style={{ display: "flex", justifyContent: "flex-end" }}>
        <button onClick={onClose} style={iconBtn()}><X size={18} /></button>
      </div>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center" }}>
        <div style={{ width: 200, height: 200, borderRadius: "50%", background: "var(--accentSoft)", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 30 }}>
          <BookOpen size={64} color="var(--accent)" />
        </div>
        <h2 style={{ fontFamily: "'Reem Kufi', sans-serif", fontSize: 24, color: "var(--text)", margin: 0 }}>سورة {player.surahName}</h2>
        <p style={{ color: "var(--textDim)", fontSize: 13, margin: "6px 0 2px" }}>الآية {player.ayahIndex + 1}</p>
        <p style={{ color: "var(--accent)", fontSize: 13.5, fontFamily: "'Cairo', sans-serif" }}>{reciter?.name}</p>
        {!reciter?.edition && (
          <div style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 6, background: "var(--surfaceAlt)", padding: "4px 10px", borderRadius: 999 }}>
            <Info size={11} color="var(--textDim)" />
            <span style={{ fontSize: 10.5, color: "var(--textDim)" }}>لا يتوفر مصدر صوت لهذا القارئ حاليًا</span>
          </div>
        )}
        {player.status === "error" && reciter?.edition && (
          <div style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 6, background: "var(--surfaceAlt)", padding: "4px 10px", borderRadius: 999 }}>
            <Info size={11} color="var(--textDim)" />
            <span style={{ fontSize: 10.5, color: "var(--textDim)" }}>تعذّر تحميل الصوت — تحقّق من الاتصال</span>
          </div>
        )}

        <div style={{ width: "100%", marginTop: 34 }}>
          <div style={{ height: 4, borderRadius: 999, background: "var(--surfaceAlt)" }}>
            <div style={{ height: "100%", width: `${player.progress}%`, background: "var(--primary)", borderRadius: 999, transition: "width .1s linear" }} />
          </div>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 26, marginTop: 26 }}>
            <button onClick={audio.prevAyah} style={circleBtn()}><SkipForward size={18} style={{ transform: "scaleX(-1)" }} /></button>
            <button onClick={audio.togglePlaying} style={{ ...circleBtn(), width: 64, height: 64, background: "var(--primary)", color: "var(--onPrimary)" }}>
              {player.playing ? <Pause size={24} /> : <Play size={24} />}
            </button>
            <button onClick={audio.nextAyah} style={circleBtn()}><SkipForward size={18} /></button>
          </div>
        </div>

        <div style={{ display: "flex", gap: 8, marginTop: 30, flexWrap: "wrap", justifyContent: "center" }}>
          {[0.75, 1, 1.25, 1.5].map((s) => (
            <Pill key={s} active={player.speed === s} onClick={() => audio.setSpeed(s)} icon={<Gauge size={12} />}>{s}x</Pill>
          ))}
          <Pill active={player.repeat} onClick={audio.toggleRepeat} icon={<Repeat size={12} />}>تكرار</Pill>
        </div>
      </div>
    </div>
  );
}
function circleBtn() {
  return { width: 48, height: 48, borderRadius: "50%", border: "1px solid var(--border)", background: "var(--surface)", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: "var(--text)" };
}


